const URBAN_DATA = {"version":"1.0.0","last_updated":"2026-05-01","description":"Structured dataset documenting evidence-based harms of outdoor advertising. All sources are independent academic, governmental, or NGO — no advertising industry sources.","license":"CC-BY-4.0","repository":"https://github.com/papamekz/addata","schema":"schema/claim.schema.json","sources_policy":"SOURCES_POLICY.md","total_claims":129,"references":{"organizations":"data/references/organizations.md"},"categories":{"psychology":{"label":"Psychology & Cognitive Impact","description":"Audience attention metrics, cognitive load, behavioral influence, and orienting response data.","count":9,"path":"data/psychology/"},"environment":{"label":"Environmental Impact & Emissions","description":"Energy consumption, CO2 emissions, light pollution (skyglow), and ecological disruption.","count":16,"path":"data/environment/"},"urban":{"label":"Urban Infrastructure & Spatial Analysis","description":"Visual pollution, public space privatization, physical obstruction, and pedestrian flow.","count":8,"path":"data/urban/"},"economy":{"label":"Economy & Advertised Emissions","description":"Overconsumption, Scope 3 emissions, status anxiety, and socioeconomic inequality.","count":8,"path":"data/economy/"},"health":{"label":"Public Health","description":"Harmful product promotion (junk food, gambling), obesity rates, and societal health externalities.","count":13,"path":"data/health/"},"culture":{"label":"Culture & Heritage","description":"Cultural homogenization, commercialization of historical heritage, and loss of local identity.","count":4,"path":"data/culture/"},"equity":{"label":"Spatial Equity & Demographics","description":"Disproportionate exposure of vulnerable communities and environmental justice.","count":4,"path":"data/equity/"},"regulation":{"label":"Regulatory Frameworks","description":"Smart city planning laws, zoning bans, digital upgrade loopholes, and self-regulation failures.","count":26,"path":"data/regulation/"},"resources":{"label":"Resource Consumption","description":"Grid impact, kW/h measurement, hardware lifecycle, and externalities of DOOH operation.","count":11,"path":"data/resources/"},"politics":{"label":"Politics & Public-Private Partnerships","description":"Lobbying influence, infrastructure financing, and privatization of municipal assets.","count":15,"path":"data/politics/"},"safety":{"label":"Traffic Safety","description":"Driver distraction studies, accident risks due to DOOH, and lighting glare hazards.","count":7,"path":"data/safety/"},"privacy":{"label":"Privacy & Data Surveillance","description":"Programmatic audience tracking, facial detection, and Wi-Fi sniffing in public spaces.","count":4,"path":"data/privacy/"},"alternatives":{"label":"Civic Alternatives & Solutions","description":"Arts funding, civic space utilization, and ad-free municipal revenue models.","count":4,"path":"data/alternatives/"}},"claims":[{"id":"psych-001","title":"Medienexposition verursacht Essstörungen bei Kindern und Jugendlichen","category":"psychology","impact_score":8,"year":2006,"source_type":"peer-reviewed","institution":"PubMed Central / National Institutes of Health","open_access":true,"file":"data/psychology/psych-001.md","source_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2792687/","tags":["children","adolescents","body-image","eating-disorders","mental-health","media-exposure"],"zusammenfassung":"Medieninhalte — insbesondere Werbung — fördern unrealistische Körperideale bei Kindern und Jugendlichen. Die Studie dokumentiert den kausalen Zusammenhang zwischen Medienexposition und der Entwicklung von Essstörungen wie Anorexia nervosa und Bulimia nervosa.","kernbefund":"Körperunzufriedenheit bei Kindern und Jugendlichen ist direkt mit Medienkonsum verbunden und führt zu verminderter Lebensqualität, verschlechterter Stimmung und ungesunden Ernährungsgewohnheiten. Werbung, die unrealistische Schlankheitsideale darstellt, ist ein primärer Auslöser.","relevanz":"Werbung im öffentlichen Raum ist nicht vermeidbar: Kinder und Jugendliche sind ihr auf dem Schulweg, in öffentlichen Verkehrsmitteln und in Einkaufszonen täglich ohne Möglichkeit zur Ablehnung ausgesetzt. Anders als Fernseh- oder Onlinewerbung können Außenwerbeanzeigen nicht weggeklickt oder ausgeschaltet werden."},{"id":"psych-002","title":"Werbung verursacht Body-Shame, Depression und Angststörungen bei Jugendlichen","category":"psychology","impact_score":8,"year":2024,"source_type":"peer-reviewed","institution":"PubMed Central","open_access":true,"file":"data/psychology/psych-002.md","source_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11103119/","tags":["adolescents","body-shame","depression","anxiety","body-image","self-objectification"],"zusammenfassung":"Selbst-Objektivierung durch Werbeexposition ist mit Body-Shame, Depression, Angst und Essstörungen verknüpft. Die Studie analysiert die psychologischen Mechanismen, durch die Werbeinhalte das Selbstbild junger Menschen schädigen.","kernbefund":"Exposition gegenüber Beauty- und Diät-Inhalten aus Werbung beschleunigt die Entwicklung von Essstörungen. Ein Bericht des Center for Countering Digital Hate (2023) stellte fest, dass algorithmisch ausgespielter Content das Körperbild-Angst bei 70 % der Jugendlichen verschlechtert. Außenwerbung transportiert dieselben Bilder dauerhaft in den öffentlichen Raum.","relevanz":"Schönheitswerbung auf Plakatwänden und digitalen Screens im öffentlichen Raum zeigt persistente, unretuschierte Idealbilder, denen Jugendliche täglich auf ihren Wegen ausgesetzt sind — ohne Kontrolle über Frequenz oder Inhalt."},{"id":"psych-003","title":"Aufmerksamkeitserzwingende Werbetaktiken manipulieren Verhalten trotz wahrgenommener Manipulation","category":"psychology","impact_score":7,"year":1995,"source_type":"peer-reviewed","institution":"Journal of Consumer Psychology, Wiley","open_access":false,"file":"data/psychology/psych-003.md","source_url":"https://myscp.onlinelibrary.wiley.com/doi/10.1207/s15327663jcp0403_02","tags":["manipulation","attention","persuasion","consumer-psychology","unconscious-influence"],"zusammenfassung":"Werbetaktiken, die darauf ausgelegt sind, Aufmerksamkeit zu erzwingen, lassen Konsumenten manipulative Absichten wahrnehmen — und senken damit Werbewirksamkeit, Markeneinstellung und Kaufabsicht. Dennoch zeigen Studien, dass selbst erkannte Manipulation das Kaufverhalten beeinflusst.","kernbefund":"Wenn Werbung als manipulativ wahrgenommen wird, sinken Werbeeinstellung, Markeneinstellung und Kaufabsicht signifikant. Das zeigt, dass Außenwerbung bewusst darauf ausgelegt ist, Aufmerksamkeit zu erzwingen — und damit die kognitive Autonomie von Passanten verletzt.","relevanz":"Außenwerbung setzt gezielt auf Reize, die Aufmerksamkeit unwillkürlich auf sich ziehen: grelle Farben, Bewegung (bei digitalen Screens), provokante Motive. Im öffentlichen Raum gibt es keine Möglichkeit, diese Manipulation zu umgehen."},{"id":"psych-004","title":"Subliminale Botschaften beeinflussen langfristig Entscheidungen unterhalb der Bewusstseinsschwelle","category":"psychology","impact_score":7,"year":2018,"source_type":"peer-reviewed","institution":"PubMed Central / Neuroscience research","open_access":true,"file":"data/psychology/psych-004.md","source_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6204644/","tags":["subliminal","unconscious-influence","decision-making","cognitive-manipulation","neuroscience"],"zusammenfassung":"Neurowissenschaftliche Forschung bestätigt, dass subliminale Botschaften unter bestimmten Bedingungen Entscheidungen beeinflussen können — insbesondere wenn sie mit bestehenden Bedürfnissen oder Wünschen übereinstimmen. Diese Effekte sind langfristig nachweisbar.","kernbefund":"Subliminale Nachrichten können Entscheidungen in eine bestimmte Richtung lenken, ohne dass die betroffene Person dies bemerkt. Werbung nutzt diese Mechanismen gezielt: kurze Bildfolgen, unterschwellige Botschaften und emotionale Konditionierung in Außenwerbung beeinflussen das Verhalten unterhalb der bewussten Wahrnehmungsschwelle.","relevanz":"Digitale Werbetafeln mit wechselnden Motiven, kurzen Animationen und emotionalen Bildsprachen nutzen dieselben Mechanismen. Im Gegensatz zu Online-Werbung können diese Einflüsse im öffentlichen Raum nicht blockiert oder vermieden werden."},{"id":"psych-005","title":"Subliminale Werbung beeinflusst nachweislich das Kaufverhalten","category":"psychology","impact_score":6,"year":2019,"source_type":"peer-reviewed","institution":"Munich Personal RePEc Archive (MPRA)","open_access":true,"file":"data/psychology/psych-005.md","source_url":"https://mpra.ub.uni-muenchen.de/92124/","tags":["subliminal","consumer-behavior","unconscious-influence","purchasing"],"zusammenfassung":"Empirische Studie, die den Einfluss subliminaler Werbung auf das Kaufverhalten untersucht. Nicht-Marketingexperten und junge Konsumenten sind besonders anfällig für unbewusste Beeinflussung durch Werbebotschaften.","kernbefund":"Subliminale Werbung beeinflusst das Kaufverhalten messbar, besonders bei Personengruppen ohne Medienkompetenz-Training. Kinder und Jugendliche sowie Personen ohne Marketingkenntnisse sind am stärksten betroffen.","relevanz":"Außenwerbung im öffentlichen Raum richtet sich an die gesamte Bevölkerung — einschließlich der vulnerabelsten Gruppen (Kinder, Menschen ohne Medienkompetenz). Es gibt keinerlei Warnsysteme oder Schutzmechanismen."},{"id":"psych-006","title":"Kreative Außenwerbung manipuliert unbewusste kognitive Verarbeitung gezielt","category":"psychology","impact_score":6,"year":2015,"source_type":"peer-reviewed","institution":"ResearchGate / Academic study","open_access":false,"file":"data/psychology/psych-006.md","source_url":"https://www.researchgate.net/publication/281908369_Creativity_attention_and_the_memory_for_brands_An_outdoor_advertising_field_study","tags":["cognitive-manipulation","attention","memory","outdoor-advertising","unconscious-processing"],"zusammenfassung":"Feldstudien zu Außenwerbung zeigen, dass Kreativität in Werbemotiven gezielt eingesetzt wird, um die unwillkürliche Aufmerksamkeit zu kapern und Markenerinnerung durch kontextabhängige Gedächtnismechanismen zu erzeugen.","kernbefund":"Außenwerbung nutzt gezielt den Orienting-Response-Mechanismus (unbewusste Aufmerksamkeitsausrichtung auf neue Reize), kontextabhängige Gedächtnisbildung und kognitive Flüssigkeit. Kreative Werbung überwindet dabei eine kognitive \"Aufmerksamkeitsschwelle\" — das heißt, sie ist so gestaltet, dass sie unwillkürliche Aufmerksamkeit erzwingt.","relevanz":"Werbefachleute designen Außenwerbung explizit so, dass sie den Blick von Passanten unwillkürlich auf sich zieht — das ist der erklärte Zweck. Diese gezielte Manipulation der unwillkürlichen Kognition im öffentlichen Raum erfolgt ohne Einwilligung der Betroffenen."},{"id":"env-001","title":"Digitale Werbetafeln verbrauchen 30-mal mehr Energie als ein durchschnittlicher US-Haushalt","category":"environment","impact_score":9,"year":2023,"source_type":"ngo","institution":"DarkSky International (International Dark-Sky Association)","open_access":true,"file":"data/environment/env-001.md","source_url":"https://darksky.org/resources/guides-and-how-tos/electronic-billboards/","tags":["energy-consumption","digital-billboards","light-pollution","carbon-footprint","environment"],"zusammenfassung":"DarkSky International, die führende unabhängige Organisation für Lichtverschmutzungsforschung, dokumentiert den enormen Energieverbrauch digitaler Werbetafeln und ihre Auswirkungen auf Lichtverschmutzung und Ökosysteme.","kernbefund":"Digitale Werbetafeln verbrauchen 30-mal mehr Energie als ein durchschnittlicher amerikanischer Haushalt. Electronic Message Centers (EMCs) strahlen Licht in alle Richtungen ab (ungerichtet), können nachts 10-mal heller sein als traditionelle Werbetafeln und tragen zur globalen Lichtverschmutzung bei, die jährlich um 6 % zunimmt. 88 % Europas und 50 % der USA erleben bereits perpetuelle künstliche Dämmerung.","relevanz":"Dieser Energieverbrauch ist ausschließlich dem Zweck der kommerziellen Aufmerksamkeitserzwingung geschuldet — er dient keinem öffentlichen Nutzen. Die Kosten (Energie, Lichtverschmutzung, CO₂) werden der Allgemeinheit aufgebürdet."},{"id":"env-002","title":"Digitale Werbung emittiert mehr CO₂ als die gesamte Luftfahrtindustrie","category":"environment","impact_score":10,"year":2022,"source_type":"peer-reviewed","institution":"Journal of Marketing Communications, Taylor & Francis","open_access":false,"file":"data/environment/env-002.md","source_url":"https://www.tandfonline.com/doi/full/10.1080/02650487.2022.2140963","tags":["climate","co2","carbon-footprint","digital-advertising","aviation","energy"],"zusammenfassung":"Akademische Analyse des direkten und indirekten CO₂-Fußabdrucks der Werbebranche. Digitales Marketing produziert inzwischen mehr Treibhausgasemissionen als die gesamte Luftfahrt — und treibt gleichzeitig Überkonsum an, der weitere Emissionen erzeugt.","kernbefund":"Die Werbeindustrie hat sowohl direkte Emissionen (Energieverbrauch für Screens, Server, Produktion) als auch massive indirekte Emissionen (durch das Anregen von Konsum kohlenstoffintensiver Güter). Online-Werbung trägt 10–20 % des gesamten Energieverbrauchs der Internetinfrastruktur bei. Digitale Außenwerbung (DOOH) kombiniert beide Effekte.","relevanz":"Digitale Out-of-Home-Werbung (DOOH) ist das am schnellsten wachsende Segment der Außenwerbung. Jedes digitale Billboard trägt direkt zu CO₂-Emissionen bei — 24 Stunden am Tag, 365 Tage im Jahr — für kommerzielle Zwecke ohne demokratische Legitimation im öffentlichen Raum."},{"id":"env-003","title":"Systematische Bewertung des Umweltkostens digitaler Werbekampagnen","category":"environment","impact_score":8,"year":2017,"source_type":"peer-reviewed","institution":"ScienceDirect / Peer-reviewed environmental research","open_access":false,"file":"data/environment/env-003.md","source_url":"https://www.sciencedirect.com/science/article/pii/S0195925517303505","tags":["energy-consumption","environmental-impact","digital-advertising","lifecycle-assessment"],"zusammenfassung":"Erste systematische Bewertung der Umweltkosten digitaler Werbekampagnen anhand von Lebenszyklusanalysen. Quantifiziert Energieverbrauch und CO₂-Emissionen pro Werbeschaltung.","kernbefund":"Digitale Werbung verursacht messbare und quantifizierbare Umweltkosten, die bisher in keiner Regulierung berücksichtigt werden. Die Studie liefert eine Methodik zur Berechnung des ökologischen Fußabdrucks von Werbekampagnen — Außenwerbung mit dauerbetriebenen Screens ist dabei besonders kostenintensiv.","relevanz":"DOOH-Screens laufen 24/7 in öffentlichen Räumen ohne die Möglichkeit für Bürger, diese abzuschalten. Die Umweltkosten werden externalisiert und von der Gesellschaft getragen, während die Gewinne privat anfallen."},{"id":"env-004","title":"Lichtverschmutzung durch Außenwerbung schadet Wildtieren und stört menschlichen Schlaf","category":"environment","impact_score":8,"year":2023,"source_type":"ngo","institution":"DarkSky International","open_access":true,"file":"data/environment/env-004.md","source_url":"https://darksky.org/what-we-do/advancing-responsible-outdoor-lighting/research/","tags":["light-pollution","wildlife","nocturnal-animals","sleep-disorders","birds","insects","ecosystem"],"zusammenfassung":"Licht aus digitalen Werbetafeln und beleuchteter Außenwerbung beeinflusst das Verhalten nachtaktiver Tiere und stört biologische Rhythmen bei Mensch und Tier. Die globale Lichtverschmutzung steigt jährlich um 6 %.","kernbefund":"Künstliches Licht aus Werbetafeln stört Fortpflanzung, Nahrungssuche und Orientierung nachtaktiver Tiere: Vögel, Fledermäuse, Frösche und Insekten werden desorientiert oder direkt geschädigt. Für Menschen: übermäßiges künstliches Licht bei Nacht führt zu Schlafstörungen, endokrinen Störungen und erhöhtem Krebsrisiko (Melatoninhemmung).","relevanz":"Werbetafeln sind häufig so positioniert und beleuchtet, dass maximale Sichtbarkeit erreicht wird — nicht minimale Umweltbelastung. 88 % Europas leiden bereits unter Lichtverschmutzung. Werbung ist ein erheblicher, vermeidbarer Anteil dieser Belastung."},{"id":"urban-001","title":"Visuelle Verschmutzung durch Werbung senkt Lebensqualität in Städten","category":"urban","impact_score":8,"year":2014,"source_type":"book","institution":"University College London, The Bartlett School of Planning / Routledge","open_access":false,"file":"data/urban/urban-001.md","source_url":"https://www.routledge.com/Visual-Pollution-Advertising-Signage-and-Environmental-Quality/Portella/p/book/9781138273764","tags":["visual-pollution","urban-quality","quality-of-life","signage","planning","architecture"],"zusammenfassung":"Empirische Vergleichsstudie (UK und Brasilien) zur negativen Wirkung kommerzieller Beschilderung und Werbung auf die visuelle Qualität urbaner Räume und die Lebensqualität der Bewohner. Aus architektonischer, planerischer und psychologischer Perspektive untersucht.","kernbefund":"Kommerzielle Beschilderung und Außenwerbung haben nachweislich negative Folgen für die visuelle Qualität urbaner Räume und das Wohlbefinden der Bewohner. Die Studie belegt, dass visuelle Überladung durch Werbung als Umweltstressor wirkt.","relevanz":"Das Buch ist eine der umfassendsten wissenschaftlichen Analysen von Außenwerbung als Quelle visueller Verschmutzung. Es zeigt, dass Werbung im öffentlichen Raum den Charakter von Städten zerstört und die Lebensqualität messbar senkt — und zwar unabhängig davon, ob Bewohner Werbung bewusst wahrnehmen oder nicht."},{"id":"urban-002","title":"Außenwerbung ist messbare Quelle visueller Verschmutzung — Städte haben keine Regulierungsmethodik","category":"urban","impact_score":7,"year":2015,"source_type":"peer-reviewed","institution":"International Journal of Geographical Information Science, Taylor & Francis","open_access":false,"file":"data/urban/urban-002.md","source_url":"https://www.tandfonline.com/doi/full/10.1080/13658816.2015.1104316","tags":["visual-pollution","measurement","regulation","urban-planning","outdoor-advertising"],"zusammenfassung":"Entwicklung einer Methodik zur Messung visueller Verschmutzung durch Außenwerbung in Stadtstraßen, kombiniert Intervisibilitätsanalyse mit Bürgerbefragungen. Zeigt, dass überstimulierende Werbung eine quantifizierbare Quelle visueller Verschmutzung ist.","kernbefund":"Außenwerbung ist eine messbare Quelle visueller Verschmutzung in Stadtstraßen. Städten fehlen standardisierte Messmethoden, was effektive Regulierung unmöglich macht. Die Studie bietet erstmals ein wissenschaftliches Werkzeug zur Quantifizierung des Problems.","relevanz":"Das Fehlen von Messmethoden und Standards ermöglicht es der Werbeindustrie, den öffentlichen Raum beliebig visuell zu belasten, ohne dass Städte dies effektiv begrenzen können. Die Studie zeigt, dass das Problem real, messbar und regulierbar wäre."},{"id":"urban-003","title":"Visuelle Verschmutzung verursacht Stress, Angst und verminderte psychische Gesundheit","category":"urban","impact_score":8,"year":2024,"source_type":"peer-reviewed","institution":"Scientific Reports, Nature Publishing Group","open_access":true,"file":"data/urban/urban-003.md","source_url":"https://www.nature.com/articles/s41598-024-56403-9","tags":["visual-pollution","stress","anxiety","mental-health","urban-environment","quality-of-life"],"zusammenfassung":"Europäische Vergleichsstudie zur urbanen visuellen Verschmutzung, veröffentlicht in Nature Scientific Reports. Zeigt, dass visuelle Verschmutzung weit mehr als ein ästhetisches Problem ist — sie wirkt als Umweltstressor mit direkten Gesundheitsfolgen.","kernbefund":"Visuelle Verschmutzung ist ein signifikantes Umweltproblem durch rasche Urbanisierung. Sie ist nicht bloß ästhetisch störend, sondern wirkt direkt auf psychische Gesundheit: Sie trägt zu Angst, Stress und verminderter Lebensqualität bei. Werbung ist einer der Haupttreiber visueller Verschmutzung in urbanen Räumen.","relevanz":"In Städten mit hoher Werbedichte leiden Bewohner nachweislich unter höheren Stressniveaus. Außenwerbung ist ein primärer, vermeidbarer Beitrag zu dieser Belastung."},{"id":"urban-004","title":"Werbung privatisiert den öffentlichen Raum ohne demokratische Rechenschaftspflicht","category":"urban","impact_score":9,"year":2021,"source_type":"peer-reviewed","institution":"Urban Studies Journal, SAGE Publications","open_access":false,"file":"data/urban/urban-004.md","source_url":"https://journals.sagepub.com/doi/full/10.1177/0263775820946755","tags":["public-space","privatization","commons","urban-politics","democracy","advertising-city"],"zusammenfassung":"Kritische urbane Analyse von Außenwerbung als Mechanismus zur Privatisierung des öffentlichen Raums. Untersucht, wie Werbung eine spezifische \"Ordnung\" im Stadtbild durchsetzt und demokratische Kontrolle über den öffentlichen Raum unterminiert.","kernbefund":"Werbung setzt eine bestimmte \"Raumordnung\" im öffentlichen Raum durch, die kommerzielle Interessen über öffentliche Interessen stellt. Regulierungsmechanismen unter dem Label \"öffentliche Rechenschaftspflicht\" dienen in der Praxis kommerziellen Interessen. Die \"Werbestadt\" enteignet Bürger ihres gemeinsamen urbanen Raums.","relevanz":"Der öffentliche Raum gehört allen — Werbung macht ihn zum Instrument privater Profitinteressen. Bürger haben keine Wahl, ob ihre Sichtfelder und Aufmerksamkeit für kommerzielle Zwecke genutzt werden."},{"id":"urban-005","title":"Systematische Übersicht: Visuelle Verschmutzung als wachsendes Umweltproblem","category":"urban","impact_score":7,"year":2024,"source_type":"peer-reviewed","institution":"Land (MDPI), peer-reviewed open-access journal","open_access":true,"file":"data/urban/urban-005.md","source_url":"https://www.mdpi.com/2073-445X/13/7/994","tags":["visual-pollution","systematic-review","urban","regulation","environment"],"zusammenfassung":"Systematische Literaturübersicht zu visueller Verschmutzung als Umweltproblem. Identifiziert Forschungslücken und methodische Ansätze zur Messung und Regulierung. Veröffentlicht 2024 in MDPI Land.","kernbefund":"Visuelle Verschmutzung ist ein anerkanntes und wachsendes Umweltproblem. Die Forschung zeigt konsistente negative Auswirkungen auf Wohlbefinden und Stadtqualität. Außenwerbung ist einer der Haupttreiber, wird aber in städtischen Umweltregulierungen kaum erfasst.","relevanz":"Die Studie identifiziert explizit Außenwerbung als primäre Quelle visueller Verschmutzung und zeigt, dass bestehende Regulierungsinstrumente nicht ausreichen. Sie liefert einen umfassenden wissenschaftlichen Rahmen für politische Maßnahmen."},{"id":"econ-001","title":"Status-Werbung erzeugt Status-Angst und treibt Haushalte in Schulden","category":"economy","impact_score":8,"year":2022,"source_type":"peer-reviewed","institution":"ScienceDirect / Sustainability research","open_access":true,"file":"data/economy/econ-001.md","source_url":"https://www.sciencedirect.com/science/article/pii/S2590291122001073","tags":["status-anxiety","debt","inequality","consumption","sustainability","overconsumption"],"zusammenfassung":"Überblicksstudie zum Zusammenhang zwischen Einkommensungleichheit, statusgetriebenem Konsum und Status-Angst. Zeigt, dass Werbung, die Status-Symbole bewirbt, direkt zu Haushaltsschulden und nicht-nachhaltigem Konsum beiträgt.","kernbefund":"Einkommensungleichheit ist mit höherem statusgetriebenem Konsum und Status-Angst verbunden. Diese durch Werbung angeheizte Status-Angst führt zu Haushaltsschulden, räumlichen Ungleichheiten und nicht-nachhaltigem Konsumverhalten mit höheren CO₂-Emissionen.","relevanz":"Außenwerbung für Luxusgüter, Statussymbole und \"aufwärts\" orientierte Konsumgüter erreicht alle Bevölkerungsschichten im öffentlichen Raum — einschließlich derer, die sich diese Güter nicht leisten können, was Status-Angst und Schulden besonders in einkommensschwachen Bevölkerungsgruppen erzeugt."},{"id":"econ-002","title":"Steigende Ungleichheit durch Werbe-Druck treibt Konsumentenkredite","category":"economy","impact_score":8,"year":2005,"source_type":"peer-reviewed","institution":"Quantitative Marketing and Economics, Springer Nature","open_access":false,"file":"data/economy/econ-002.md","source_url":"https://link.springer.com/article/10.1007/s11129-005-0351-1","tags":["consumer-debt","inequality","keeping-up","borrowing","consumption"],"zusammenfassung":"Ökonometrische Studie zum Zusammenhang zwischen steigender Einkommensungleichheit und wachsenden Konsumentenschulden. Zeigt, dass Haushalte mit geringeren Einkommenszuwächsen Schulden aufnehmen, um ihren Konsum relativ zu wohlhabenderen Haushalten aufrechtzuerhalten.","kernbefund":"Steigende Einkommensungleichheit erhöht die Konsumentenverschuldung substanziell. Haushalte mit kleineren Einkommensgewinnen nehmen Schulden auf, um den Konsum wohlhabenderer Gruppen nachzuahmen — ein Mechanismus, der durch Werbung gezielt ausgenutzt wird (\"Keeping up with the Joneses\").","relevanz":"Außenwerbung im öffentlichen Raum konfrontiert alle Einkommensgruppen mit denselben Konsumanreizen. Die Werbung für hochpreisige Güter im öffentlichen Raum ist ein direkter Treiber des \"Keeping up\"-Mechanismus, der Haushalte in Verschuldung treibt."},{"id":"econ-003","title":"Langzeitkorrelation: Wachsende Ungleichheit und konsumgetriebene Verschuldung seit den 1960er Jahren","category":"economy","impact_score":7,"year":2017,"source_type":"government","institution":"National Bureau of Economic Research (NBER)","open_access":true,"file":"data/economy/econ-003.md","source_url":"https://www.nber.org/system/files/working_papers/w23655/w23655.pdf","tags":["inequality","consumption","long-term","economic-history","advertising-effects"],"zusammenfassung":"NBER-Arbeitspapier, das die Langzeitkorrelation zwischen wachsender Einkommensungleichheit und Konsummustern in den USA seit den 1960er Jahren dokumentiert. Analysiert, wie Marketing und Werbung statusgetriebenen Konsum beschleunigen.","kernbefund":"Jahrzehntelange Daten belegen den Zusammenhang zwischen steigender Ungleichheit und nicht-nachhaltigen Konsummustern. Werbung und Marketing spielen eine zentrale Rolle bei der Beschleunigung statusgetriebenen Konsums, der Ungleichheiten perpetuiert.","relevanz":"Außenwerbung ist seit Jahrzehnten ein Treiber dieser Konsummuster — sie ist die am stärksten sichtbare und flächendeckendste Form kommerzieller Botschaften im öffentlichen Raum."},{"id":"econ-004","title":"Höhere Ungleichheit führt zu mehr Status-Konsum — Werbung nutzt diesen Mechanismus gezielt aus","category":"economy","impact_score":7,"year":2020,"source_type":"peer-reviewed","institution":"Wharton School of Business, University of Pennsylvania","open_access":true,"file":"data/economy/econ-004.md","source_url":"https://marketing.wharton.upenn.edu/wp-content/uploads/2020/07/Leapfrogging-over-the-Joneses-Effects-of-Inequality-on-Conspicuous-and-Inconspicuous-Consumption.pdf","tags":["conspicuous-consumption","inequality","status-signaling","luxury-advertising","social-comparison"],"zusammenfassung":"Wharton-Forschungsstudie zur Wirkung von Einkommensungleichheit auf sichtbaren und unsichtbaren Konsum. Zeigt, dass höhere Ungleichheit zu mehr ostentativer (sichtbarer) Statuskonsumption führt — genau das, was Außenwerbung für hochpreisige Güter anreizt.","kernbefund":"Höhere Ungleichheit erhöht Statussignaling-Konsum (conspicuous consumption). Werbung für Luxusgüter und Statusprodukte im öffentlichen Raum nutzt und verstärkt diesen Mechanismus gezielt — sie richtet sich an alle Einkommensgruppen und erzeugt soziale Vergleichsprozesse, die zu irrationalen Kaufentscheidungen führen.","relevanz":"Außenwerbung für Premium- und Statusgüter ist im öffentlichen Raum besonders wirkungsvoll, da sie alle Bevölkerungsschichten erreicht und soziale Vergleiche in einem Kontext erzeugt, in dem Armut und Reichtum direkt aufeinandertreffen."},{"id":"health-001","title":"Außenwerbung für Lebensmittel beeinflusst Jugendliche ebenso stark wie TV-Werbung","category":"health","impact_score":8,"year":2022,"source_type":"peer-reviewed","institution":"BMC Public Health, Springer Nature","open_access":true,"file":"data/health/health-001.md","source_url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-022-13784-8","tags":["food-marketing","outdoor-advertising","adolescents","eating-behavior","health","children"],"zusammenfassung":"Systematische Übersichtsstudie zu Außenwerbung für Lebensmittel: Reichweite, Wirkungsmacht und Auswirkungen auf Ernährungsverhalten und Gesundheit. Veröffentlicht in BMC Public Health, Springer Nature.","kernbefund":"Außenwerbung für Lebensmittel ist genauso umfangreich und wirkungsvoll wie Digital- oder TV-Werbung. Skeptizismus bei Jugendlichen schützt nicht vor den Effekten. Sowohl Kleinkinder als auch ältere Jugendliche sind anfällig. Belege zeigen, dass Werbung Ernährungspräferenzen und Konsummuster beeinflusst.","relevanz":"Im Gegensatz zu TV oder Online kann Außenwerbung für ungesunde Lebensmittel nicht abgeschaltet, weggeklickt oder gefiltert werden. Kinder sind ihr auf dem gesamten Schulweg ausgesetzt — in einem Kontext, in dem keine Aufsicht oder Einordnung durch Eltern möglich ist."},{"id":"health-002","title":"Außenwerbung für Lebensmittel korreliert direkt mit Kaufverhalten bei Jugendlichen","category":"health","impact_score":8,"year":2024,"source_type":"peer-reviewed","institution":"Health Promotion International, Oxford Academic","open_access":false,"file":"data/health/health-002.md","source_url":"https://academic.oup.com/heapro/article/40/2/daaf016/8084741","tags":[],"zusammenfassung":"Kanadische Querschnittsstudie, die erstmals eine direkte Korrelation zwischen der Exposition gegenüber Außenwerbung für Lebensmittel und dem tatsächlichen Kaufverhalten von Jugendlichen herstellt. Peer-reviewed, veröffentlicht in Oxford Health Promotion International.","kernbefund":"Die Studie belegt eine statistisch signifikante direkte Korrelation zwischen der Häufigkeit der Exposition gegenüber Außenwerbung für Lebensmittel und dem Kaufverhalten von Jugendlichen. Mehr Werbung = mehr Käufe der beworbenen (überwiegend ungesunden) Produkte.","relevanz":"Diese Studie liefert den direktesten Kausalnachweis: Außenwerbung für Lebensmittel verändert das Kaufverhalten von Jugendlichen messbar. Im Jahr 2024 veröffentlicht — dies ist aktuelle, belastbare Evidenz."},{"id":"health-003","title":"10 % mehr Lebensmittelwerbung im Stadtviertel → 1,05-fach höheres Übergewichtsrisiko","category":"health","impact_score":9,"year":2013,"source_type":"peer-reviewed","institution":"BMC Public Health, Springer Nature","open_access":true,"file":"data/health/health-003.md","source_url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/1471-2458-13-20","tags":["obesity","food-advertising","outdoor-advertising","soda","overweight","neighborhood"],"zusammenfassung":"Querschnittsstudie, die den Zusammenhang zwischen der Dichte von Lebensmittelwerbung im Stadtviertel und dem Übergewichtsrisiko der Bewohner quantifiziert. Veröffentlicht in BMC Public Health.","kernbefund":"Ein höherer Anteil von Lebensmittelwerbung in Stadtvierteln ist mit erhöhter Übergewichts- und Adipositasrate verbunden. Für jede 10 % Erhöhung des Anteils von Lebensmittelwerbung steigt das Übergewichtsrisiko um den Faktor 1,05. Der Effekt ist auf Stadtviertel-Ebene messbar und statistisch signifikant.","relevanz":"Diese Studie quantifiziert direkt den Gesundheitsschaden von Außenwerbung für Lebensmittel auf Bevölkerungsebene. Sie zeigt, dass die Platzierung von Werbung im öffentlichen Raum messbare Public-Health-Folgen hat."},{"id":"health-004","title":"WHO: Freiwillige Beschränkungen für Kinderlebensmittelwerbung sind wirkungslos","category":"health","impact_score":9,"year":2023,"source_type":"who-report","institution":"World Health Organization (WHO)","open_access":true,"file":"data/health/health-004.md","source_url":"https://www.who.int/tools/elena/interventions/food-marketing-children","tags":["children","food-marketing","who","regulation","voluntary-bans","mandatory-policy"],"zusammenfassung":"WHO-Leitlinie und ELENA-Intervention zu Nahrungsmittelmarketing an Kinder. Die WHO empfiehlt verbindliche gesetzliche Regelungen zum Schutz von Kindern vor Marketing für Lebensmittel mit hohem Gehalt an gesättigten Fettsäuren, Transfetten, freien Zuckern und Salz.","kernbefund":"Freiwillige Selbstverpflichtungen der Werbeindustrie sind nachweislich wirkungslos. Die WHO fordert verbindliche, staatlich durchgesetzte Einschränkungen — einschließlich für Außenwerbung — weil Kinder ansonsten schutzlos aggressivem Marketing ausgesetzt sind.","relevanz":"Die WHO nennt Außenwerbung explizit als einen der Kanäle, der geregelt werden muss. Dies ist eine der höchsten internationalen Gesundheitsbehörden, die Außenwerbung für Kinder als gesundheitsschädigend einstuft."},{"id":"health-005","title":"Schädliches Marketing tötet über 1 Million Menschen pro Jahr in den USA allein","category":"health","impact_score":10,"year":2024,"source_type":"peer-reviewed","institution":"Prevention Science, Springer Nature","open_access":false,"file":"data/health/health-005.md","source_url":"https://link.springer.com/article/10.1007/s11121-024-01763-x","tags":["harmful-marketing","public-health","tobacco","alcohol","food","firearms","mortality","social-determinants"],"zusammenfassung":"Peer-reviewed Studie in Prevention Science (Springer), die schädliches Marketing als übersehenen sozialen Gesundheitsdeterminanten analysiert. Untersucht 6 Industrien: Tabak, Alkohol, Pharma, verarbeitete Lebensmittel, Schusswaffen, fossile Brennstoffe.","kernbefund":"Marketing in 6 Industrien ist kausal für Krankheiten und Tod verantwortlich. Über 1 Million Amerikaner sterben jährlich an den Folgen von Produkten, die durch Marketing beworben werden. Die Studie rahmt schädliches Marketing als strukturellen öffentlichen Gesundheitsdeterminanten — vergleichbar mit Armut oder Bildungsmangel.","relevanz":"Außenwerbung ist der sichtbarste und universell zugängliche Kanal für genau diese schädlichen Produkte (Alkohol, Tabak, ungesunde Lebensmittel). Im öffentlichen Raum ist Exposition nicht vermeidbar — besonders nicht für vulnerable Gruppen (Kinder, Menschen mit Suchterkrankungen)."},{"id":"culture-001","title":"Globale Außenwerbung wirkt als Treiber kultureller Homogenisierung","category":"culture","impact_score":7,"year":2003,"source_type":"peer-reviewed","institution":"Asian Journal of Communication, Taylor & Francis","open_access":false,"file":"data/culture/culture-001.md","source_url":"https://www.tandfonline.com/doi/abs/10.1080/01292980309364830","tags":["cultural-homogenization","globalization","asean","western-values","local-culture","nation-building"],"zusammenfassung":"Akademische Analyse von Werbung als kulturell homogenisierender Kraft in der ASEAN-Region. Untersucht, wie internationale Werbung nationale Kulturprojekte herausfordert und westliche Kulturelemente weltweit verbreitet.","kernbefund":"Internationale Werbung — insbesondere für globale Marken im öffentlichen Raum — fungiert als globale kulturelle Homogenisierungskraft. Sie verbreitet ein vereinheitlichtes westliches (v. a. amerikanisches) Erscheinungsbild und Wertesystem über nationale Grenzen hinweg und verdrängt lokale Kulturideale.","relevanz":"Außenwerbung von McDonald's, Coca-Cola, Apple und anderen globalen Marken im öffentlichen Raum prägt das visuelle Erscheinungsbild von Städten weltweit auf nahezu identische Weise — auf Kosten lokaler kultureller Eigenständigkeit."},{"id":"culture-002","title":"Westliche Werbung verdrängt lokale Schönheits- und Kulturideale weltweit","category":"culture","impact_score":7,"year":2007,"source_type":"peer-reviewed","institution":"GRIN Academic Repository","open_access":true,"file":"data/culture/culture-002.md","source_url":"https://www.grin.com/document/75671","tags":["cultural-homogenization","beauty-standards","western-dominance","global-brands","local-culture"],"zusammenfassung":"Akademische Analyse, wie globale Werbung und Konsumkultur zur Entstehung einer homogenen Weltkultur beitragen. Untersucht konkret globale Marken (Coca-Cola, Apple, McDonald's) und ihre Wirkung auf kulturelle Konvergenz.","kernbefund":"Globale Marken erzwingen ein konsistentes Bild und Wertesystem über nationale Grenzen hinweg und fördern kulturelle Konvergenz. Lokale Kulturideale — einschließlich Schönheitsstandards — gleichen sich zunehmend westlichen Normen an. Außenwerbung ist der primäre Kanal, über den diese Botschaften in den öffentlichen Raum eindringen.","relevanz":"Jede Plakatwand für ein westliches Globalprodukt im öffentlichen Raum ist ein Akt kultureller Überformung — sie setzt westliche Standards als Norm, ohne dass lokale Gemeinschaften darüber abstimmen können."},{"id":"culture-003","title":"Globale Werbeplattformen beschleunigen kulturelle Homogenisierung und bedrohen lokale Traditionen","category":"culture","impact_score":7,"year":2024,"source_type":"peer-reviewed","institution":"ResearchGate / Peer-reviewed","open_access":true,"file":"data/culture/culture-003.md","source_url":"https://www.researchgate.net/publication/382994264_CULTURAL_HOMOGENIZATION_VS_CULTURAL_DIVERSITY_SOCIAL_MEDIA%27S_DOUBLE-EDGED_SWORD_IN_THE_AGE_OF_GLOBALIZATION","tags":["cultural-homogenization","cultural-diversity","globalization","local-traditions","outdoor-advertising"],"zusammenfassung":"Aktuelle (2024) Analyse, wie globale Werbeplattformen und Medien — einschließlich Außenwerbung — zur kulturellen Homogenisierung beitragen und lokale Traditionen und Diversität bedrohen.","kernbefund":"Globale Werbe- und Medienplattformen tragen messbar zur kulturellen Homogenisierung bei. Lokale Traditionen und kulturelle Vielfalt werden durch die Dominanz globaler Markenbotschaften im öffentlichen Raum verdrängt. Dies ist ein aktuell wachsendes Problem.","relevanz":"Außenwerbung ist physisch im öffentlichen Raum verankert und damit besonders persistenter Teil des kulturellen Umfelds. Digitale DOOH-Screens beschleunigen die Verbreitung globaler Markenbotschaften in lokale Räume."},{"id":"equity-001","title":"Schulwege von Kindern werden systematisch mit schädlicher Produktwerbung belastet","category":"equity","impact_score":9,"year":2022,"source_type":"peer-reviewed","institution":"ScienceDirect / Peer-reviewed public health","open_access":false,"file":"data/equity/equity-001.md","source_url":"https://www.sciencedirect.com/science/article/abs/pii/S1353829222001228","tags":["children","school-routes","harmful-advertising","alcohol","gambling","junk-food","equity"],"zusammenfassung":"Studie zur Verteilung schädlicher Produktwerbung (Alkohol, ungesunde Lebensmittel, Glücksspiel) im öffentlichen Raum und auf Schulwegen. Analysiert auch die Wirksamkeit von Werbeverboten.","kernbefund":"Kinder sind auf dem Weg zur Schule systematisch Werbung für schädliche Produkte ausgesetzt. Werbung entlang Heimweg-Schule-Routen verstärkt Botschaften durch Wiederholung. Besonders belastete Viertel haben höhere Gesundheitsrisiken. Freiwillige Verbote sind unwirksam — nur staatliche Pflichtregeln zeigen Wirkung.","relevanz":"Kinder haben keine Kontrolle darüber, welcher Werbung sie auf ihren täglichen Wegen ausgesetzt sind. Das ist eine strukturelle Verletzung ihres Schutzes — ein öffentlicher Raum, der Kinder täglich mit Alkohol-, Junkfood- und Glücksspielwerbung konfrontiert, versagt als Schutzraum."},{"id":"equity-002","title":"Einkommensschwache Stadtteile und Communities of Color sind unverhältnismäßig stark schädlicher Außenwerbung ausgesetzt","category":"equity","impact_score":9,"year":2014,"source_type":"peer-reviewed","institution":"PubMed / American Journal of Public Health","open_access":false,"file":"data/equity/equity-002.md","source_url":"https://pubmed.ncbi.nlm.nih.gov/24524512/","tags":["environmental-justice","racial-equity","low-income","communities-of-color","harmful-advertising","spatial-inequality","los-angeles"],"zusammenfassung":"Environmental-Justice-Studie in Los Angeles zur räumlichen Ungleichverteilung schädlicher Außenwerbung (Alkohol, Tabak, Junkfood). Zeigt strukturellen Rassismus und Klassenungleichheit in der Platzierung von Außenwerbung.","kernbefund":"Einkommensschwache Stadtteile und Neighborhoods mit hohem Anteil an People of Color tragen eine unverhältnismäßig hohe Last schädlicher Außenwerbung. Die Verteilung ist nicht zufällig, sondern folgt Mustern, die mit bestehenden sozialen Ungleichheiten korrelieren — Außenwerbung verstärkt und perpetuiert diese Ungleichheiten.","relevanz":"Außenwerbung ist kein neutrales Medium — sie wird strategisch so platziert, dass vulnerable Gruppen überproportional exponiert sind. Dies ist eine Form struktureller Diskriminierung durch kommerzielle Interessen im öffentlichen Raum."},{"id":"health-006","title":"92 % der Lebensmittelwerbung an Kinder in Deutschland bewirbt ungesunde Produkte","category":"health","impact_score":9,"year":2021,"source_type":"government","institution":"Universität Hamburg, Fachbereich BWL, im Auftrag von DANK und AOK-Bundesverband","open_access":true,"file":"data/health/health-006.md","source_url":"https://www.bwl.uni-hamburg.de/irdw/dokumente/kindermarketing2021effertzunihh.pdf","tags":["children","food-marketing","germany","unhealthy-food","television","internet","deutsch"],"zusammenfassung":"Studie der Universität Hamburg, beauftragt von der Deutschen Allianz Nichtübertragbare Krankheiten (DANK) und dem AOK-Bundesverband. Analysiert systematisch Lebensmittelwerbung, die an Kinder in Deutschland gerichtet ist.","kernbefund":"Ein Kind zwischen 3 und 13 Jahren sieht in Deutschland durchschnittlich 15 Lebensmittelwerbungen für ungesunde Produkte pro Tag (5 im Internet, 10 im Fernsehen). 92 % aller an Kinder gerichteten Lebensmittelwerbungen betreffen ungesunde Produkte (89 % im TV, 98 % im Internet).","relevanz":"Außenwerbung ist Teil desselben Werbeökosystems, das diese systematische Exposition von Kindern gegenüber ungesunden Lebensmitteln erzeugt. Auf dem Schulweg, an Bushaltestellen und in Einkaufszonen sind Kinder denselben Markenbotschaften ausgesetzt — ohne elterliche Aufsicht und ohne Möglichkeit zur Abschaltung."},{"id":"health-007","title":"50 % der Jugendlichen in Deutschland kauften Produkte aufgrund von Influencer-Werbung","category":"health","impact_score":7,"year":2024,"source_type":"government","institution":"Fraunhofer-Institut für System- und Innovationsforschung (ISI), Karlsruhe","open_access":true,"file":"data/health/health-007.md","source_url":"https://www.isi.fraunhofer.de/de/presse/2024/presseinfo-03-social-media-influencer-marketing-jugendliche-kritischer-konsum-schutz-noetig.html","tags":["youth","influencer-marketing","germany","consumption","fraunhofer","adolescents","deutsch"],"zusammenfassung":"DFG-gefördertes FAIR-Projekt (Fraunhofer ISI, Hochschule Darmstadt, Universität Mannheim) untersucht die Wirkung von Influencer-Marketing auf Jugendliche in Deutschland. Befragung von über 1.000 Jugendlichen.","kernbefund":"Etwa 50 % der befragten Jugendlichen hatten Produkte gekauft, die von Influencern beworben wurden. Über die Hälfte hatte innerhalb von 6 Monaten mehr als 50 Euro für von Influencern beworbene Produkte ausgegeben. Jugendliche sind besonders vulnerabel durch intensive Social-Media-Nutzung und weniger entwickelte Werberkenntniskompetenz.","relevanz":"Influencer-Marketing und Außenwerbung sind Teil desselben Werbesystems. Beide nutzen ähnliche psychologische Mechanismen (parasoziale Beziehungen, Aufmerksamkeitsfang, Statusappelle). Die Vulnerabilität Jugendlicher gegenüber Werbebotschaften im öffentlichen Raum ist analog zu ihrer Anfälligkeit für Influencer-Marketing."},{"id":"env-005","title":"Lichtverschmutzung durch künstliche Beleuchtung verursacht nachweislich Insektensterben","category":"environment","impact_score":9,"year":2022,"source_type":"peer-reviewed","institution":"Leibniz-Institut für Gewässerökologie und Binnenfischerei (IGB), Berlin","open_access":true,"file":"data/environment/env-005.md","source_url":"https://www.igb-berlin.de/en/news/light-pollution-reason-insect-decline","tags":["light-pollution","insects","biodiversity","germany","leibniz","ecosystem","deutsch"],"zusammenfassung":"Forschung des Leibniz-Instituts für Gewässerökologie und Binnenfischerei (IGB) Berlin zeigt einen klaren kausalen Zusammenhang zwischen Lichtverschmutzung und dem Rückgang fliegender Insekten. Regionen mit starkem Insektenrückgang weisen auch hohe Lichtverschmutzungswerte auf.","kernbefund":"In Regionen mit starkem Rückgang fliegender Insekten sind auch die Werte für Lichtverschmutzung hoch. IGB-Forscher fanden starke Belege für einen kausalen Zusammenhang. Künstliches Licht bei Nacht stört Fortpflanzung, Nahrungssuche und Orientierung von Insekten.","relevanz":"Beleuchtete Werbetafeln und insbesondere digitale DOOH-Screens sind nach Straßenlaternen einer der häufigsten Quellen künstlichen Lichts im urbanen und halburbanen Raum. Werbetafeln leuchten 24/7 — auch in Stunden, in denen Straßenbeleuchtung gedimmt wird."},{"id":"env-006","title":"Künstliches Nachtlicht verändert 1.564 Gene bei Insekten — massive physiologische Schäden","category":"environment","impact_score":9,"year":2022,"source_type":"peer-reviewed","institution":"Senckenberg Gesellschaft für Naturforschung, Frankfurt","open_access":true,"file":"data/environment/env-006.md","source_url":"https://www.senckenberg.de/de/pressemeldungen/die-dunkle-seite-des-lichts-beleuchtung-in-der-nacht-bedroht-insekten/","tags":["light-pollution","insects","gene-expression","senckenberg","germany","biodiversity","deutsch"],"zusammenfassung":"Forschung der Senckenberg Gesellschaft für Naturforschung zur molekularen Wirkung von Lichtverschmutzung auf Insekten. Erstmals wurde nachgewiesen, in welchem Ausmaß künstliches Licht bei Nacht die Genexpression von Insekten beeinflusst.","kernbefund":"Künstliches Licht bei Nacht bewirkt profunde Veränderungen in der Genexpression von Insekten: 1.564 Gene wurden in Zuckmückenlarven (Chironomidae) beeinflusst. Die Folgen: verzögerte Entwicklung, erhöhter oxidativer Stress und drastisch reduzierte Reproduktionskapazität. Dies bedroht die gesamte Nahrungskette, da Insekten Grundlage für Vögel, Fische und andere Tiere sind.","relevanz":"Werbetafeln sind eine der wenigen Lichtquellen im öffentlichen Raum, die ausschließlich kommerziellen Zwecken dienen. Im Gegensatz zu Straßenlaternen haben sie keine Sicherheitsfunktion. Der ökologische Schaden durch Werbebeleuchtung ist vermeidbar."},{"id":"env-007","title":"Lichtverschmutzung als Ursache des Insektenrückgangs — bayerische Landesbehörde bestätigt Zusammenhang","category":"environment","impact_score":8,"year":2019,"source_type":"government","institution":"Bayerische Akademie für Naturschutz und Landschaftspflege (ANL Bayern)","open_access":true,"file":"data/environment/env-007.md","source_url":"https://www.anl.bayern.de/publikationen/anliegen/doc/an41122voith_et_al_2019_lichtverschmutzung.pdf","tags":["light-pollution","insects","bavaria","germany","government-report","biodiversity","deutsch"],"zusammenfassung":"Umfassende Analyse der Bayerischen Akademie für Naturschutz und Landschaftspflege zu Lichtverschmutzung als Faktor des Insektenrückgangs. Staatliche bayerische Behörde dokumentiert den Zusammenhang offiziell.","kernbefund":"Lichtverschmutzung ist ein maßgeblicher Faktor im Insektenrückgang. Die Studie analysiert alle relevanten Beleuchtungstypen im urbanen und ländlichen Raum. Werbetafeln werden explizit als relevante Lichtquelle identifiziert.","relevanz":"Dies ist ein offizieller Bericht einer bayerischen Staatsbehörde. Er belegt, dass der Gesetzgeber Lichtverschmutzung als Umweltproblem anerkennt — und implizit, dass kommerzielle Beleuchtung (Werbetafeln) Teil des Problems ist."},{"id":"reg-001","title":"Hamburg Volksbegehren gegen Außenwerbung: Verfassungsgericht erklärt Initiative für zulässig (2024)","category":"regulation","impact_score":7,"year":2024,"source_type":"ngo","institution":"World Without Fossil Ads / Adfree Cities","open_access":true,"file":"data/regulation/reg-001.md","source_url":"https://www.worldwithoutfossilads.org/listing/hamburg-popular-initiative-wins-in-court-referendum-to-ban-outdoor-ads-moves-to-next-phase/","tags":["hamburg","germany","referendum","ban","outdoor-advertising","digital-screens","initiative","deutsch"],"zusammenfassung":"In Hamburg läuft seit 2024 eine Volksinitiative (Hamburg Werbefrei) zur Einschränkung von Außenwerbung, insbesondere digitalen Werbescreens. Das Hamburgische Verfassungsgericht erklärte die Initiative im September 2024 für rechtlich zulässig.","kernbefund":"Das Hamburgische Verfassungsgericht hat die Initiative \"Hamburg Werbefrei\" als verfassungsrechtlich zulässig eingestuft. Ca. 400 Aktive sammelten über 50.000 Unterschriften in 3 Wochen (Ziel: 80.000 = 5 % der Wahlberechtigten für einen Volksentscheid). Die Initiative fordert ein Verbot digitaler Werbescreens sowie eine Reduzierung von Plakatwerbung aus Gründen des Umwelt-, Gesundheits- und Stadtbild-Schutzes.","relevanz":"Die Hamburger Initiative zeigt, dass es breite Bevölkerungsunterstützung für Einschränkungen von Außenwerbung gibt. Wenn eine deutsche Großstadt demokratisch über Werbeverbote abstimmt, ist das ein starkes Signal für die gesellschaftliche Anerkennung der Schäden von Außenwerbung."},{"id":"reg-002","title":"Deutschland war letztes EU-Land ohne Tabak-Außenwerbungsverbot — Verbot trat erst 2022–2024 in Kraft","category":"regulation","impact_score":8,"year":2020,"source_type":"ngo","institution":"The Local / Tobacco Control Laws Germany","open_access":true,"file":"data/regulation/reg-002.md","source_url":"https://www.thelocal.de/20200918/germany-set-to-ban-cigarette-street-ads-from-2022","tags":["tobacco","germany","ban","last-eu-country","outdoor-advertising","regulation","deutsch"],"zusammenfassung":"Deutschland war das letzte EU-Mitgliedsland, das Tabakwerbung im Außenbereich verbot. Das Verbot wurde stufenweise eingeführt: Tabakprodukte ab Januar 2022, erhitzte Tabakprodukte ab Januar 2023, E-Zigaretten ab Januar 2024.","kernbefund":"Die Tabakindustrie gab jährlich ca. 100 Millionen Euro für Straßen- und Kinowerbung in Deutschland aus. Deutschland war jahrzehntelang ein EU-Sonderfall: Während andere Mitgliedsstaaten Tabak-Außenwerbung längst verboten hatten, blockierte die politisch einflussreiche deutsche Tabakindustrie das Verbot. Das Verbot kam erst nach erheblichem öffentlichem und EU-Druck.","relevanz":"Dieses Beispiel zeigt exemplarisch, wie die Werbeindustrie gesetzliche Schutzmaßnahmen jahrzehntelang verzögern kann, selbst wenn der Schaden (Tabakwerbung → Jugendlichenrauchen) wissenschaftlich längst belegt ist. Es ist ein Präzedenzfall für andere Schad-Werbung im öffentlichen Raum."},{"id":"reg-003","title":"São Paulo: Totales Außenwerbungsverbot (2007) — 70 % Bevölkerungsunterstützung nach 5 Jahren","category":"regulation","impact_score":9,"year":2012,"source_type":"ngo","institution":"99% Invisible / New Dream","open_access":true,"file":"data/regulation/reg-003.md","source_url":"https://99percentinvisible.org/article/clean-city-law-secrets-sao-paulo-uncovered-outdoor-advertising-ban/","tags":["sao-paulo","brazil","ban","lei-cidade-limpa","billboards","public-support","urban"],"zusammenfassung":"São Paulo führte 2007 das \"Lei Cidade Limpa\" (Saubere-Stadt-Gesetz) ein — das umfassendste Außenwerbungsverbot der Welt. 15.000 Werbetafeln wurden entfernt, digitale Screens verboten, Werbung auf Bussen und 300.000 nicht-konforme Firmenschilder abgebaut.","kernbefund":"Eine Umfrage 2011 (4 Jahre nach dem Verbot) zeigte: 70 % der 11 Millionen Einwohner Sao Paulos empfanden das Verbot als positiv. Unerwartete Folgen: Das Verbot legte zuvor durch Werbung verdeckte historische Architektur frei und stimulierte Straßenkunst. Clear Channel klagte gegen das Gesetz — und scheiterte.","relevanz":"São Paulo ist der Beweis, dass ein Leben ohne Außenwerbung im öffentlichen Raum möglich ist — und von der Bevölkerung mehrheitlich begrüßt wird. Es widerlegt das Argument der Werbeindustrie, Außenwerbung sei ein unverzichtbarer Teil des Stadtlebens."},{"id":"reg-004","title":"Grenoble: Erstes werbefreies Stadtgebiet Europas (2015) — 326 Werbetafeln durch Bäume ersetzt","category":"regulation","impact_score":8,"year":2015,"source_type":"ngo","institution":"World Without Fossil Ads / Euronews","open_access":true,"file":"data/regulation/reg-004.md","source_url":"https://www.worldwithoutfossilads.org/listing/grenoble-first-to-ban-outdoor-ads-replaces-them-with-trees/","tags":["grenoble","france","ban","europe","billboards","urban-commons","trees"],"zusammenfassung":"Grenoble (Frankreich) war 2015 die erste europäische Stadt, die ein umfassendes Außenwerbungsverbot im Stadtgebiet einführte. Bürgermeister Éric Piolle (Grüne) kündigte den städtischen Werbetafel-Vertrag und ließ 326 Werbetafeln (inkl. 64 Billboards) entfernen.","kernbefund":"2.051 Quadratmeter Werbefläche wurden eliminiert. Als Ersatz: 300+ neue Bürgertafeln für gemeinnützige Ankündigungen, Bäume und freie Flächen für lokale Kulturgruppen. Finanzielle Einbuße: 600.000 Euro/Jahr an Werbeeinnahmen. Das Modell zeigt: Städte können auf Werbeeinnahmen verzichten und öffentlichen Raum zurückgewinnen.","relevanz":"Grenoble belegt, dass es politisch und finanziell möglich ist, Außenwerbung in einer europäischen Stadt abzuschaffen. Die Stadt ist heute ein Referenzfall für urbane Werbefreiheitsbewegungen weltweit."},{"id":"reg-005","title":"EU-Selbstverpflichtung der Lebensmittelindustrie für Kinder-Werbung: 85 % der Produkte erfüllen WHO-Kriterien nicht","category":"regulation","impact_score":9,"year":2021,"source_type":"ngo","institution":"BEUC — The European Consumer Organisation","open_access":true,"file":"data/regulation/reg-005.md","source_url":"https://www.beuc.eu/sites/default/files/publications/beuc-x-2021-084_food_marketing_to_children_needs_rules_with_teeth.pdf","tags":["eu-pledge","self-regulation","children","food-marketing","who-criteria","failure","europe"],"zusammenfassung":"Analyse der europäischen Verbraucherorganisation BEUC zur EU Pledge — der freiwilligen Selbstverpflichtung der Lebensmittelindustrie, keine ungesunden Produkte an Kinder zu bewerben. Ergebnis: Totales Versagen der Selbstregulierung.","kernbefund":"21 Unternehmen, die für über 80 % der europäischen Lebensmittelwerbungsausgaben verantwortlich sind, haben sich zur EU Pledge verpflichtet. Trotzdem: 85 % der von diesen Unternehmen an Kinder gerichteten Produkte würden nach WHO-Nährwertkriterien als werbungswürdig verboten werden müssen. Freiwillige Selbstverpflichtungen sind wirkungslos.","relevanz":"Auch für Außenwerbung gibt es in Deutschland und der EU primär Selbstregulierung (Deutscher Werberat). Dieses Beispiel zeigt systemisch, dass freiwillige Industriecodes Kinder nicht schützen. Gesetzliche Verbote sind notwendig."},{"id":"reg-006","title":"Deutscher Werberat: Selbstkontrolle ohne Verbrauchervertretung und ohne Durchsetzungsbefugnis","category":"regulation","impact_score":7,"year":2000,"source_type":"peer-reviewed","institution":"SpringerLink / Peer-reviewed","open_access":false,"file":"data/regulation/reg-006.md","source_url":"https://link.springer.com/article/10.1007/BF02386023","tags":["deutscher-werberat","self-regulation","germany","consumer-protection","enforcement","deutsch"],"zusammenfassung":"Wissenschaftliche Analyse der Schwachstellen der deutschen Werbeselbstkontrolle (Deutscher Werberat). Dokumentiert strukturelle Mängel, die einen effektiven Verbraucherschutz verhindern.","kernbefund":"Der Deutsche Werberat hat keine Verbrauchervertretung im Vorstand — nur eine Verbindungskommission. Er kann lediglich freiwillige Compliance einfordern, hat aber keine bindende Durchsetzungsbefugnis. Werbepraktiken können während laufender Verfahren ungehindert fortgesetzt werden. 2023 sprach der Werberat nur 8 Rügen aus bei Tausenden verbreiteten Werbungen.","relevanz":"Außenwerbung in Deutschland unterliegt de facto keiner wirksamen inhaltlichen Regulierung. Der Werberat ist das Hauptschutzinstrument — und er schützt nicht. Dies lässt Schad-Werbung im öffentlichen Raum strukturell unreguliert."},{"id":"reg-007","title":"BNatSchG § 41a: Deutschland verankert Lichtemissionsschutz im Naturschutzgesetz — Umsetzung 2027","category":"regulation","impact_score":6,"year":2021,"source_type":"government","institution":"Bundesumweltministerium / Geography Realm","open_access":true,"file":"data/regulation/reg-007.md","source_url":"https://www.geographyrealm.com/germany-plans-to-curb-light-pollution-to-save-insects/","tags":[],"zusammenfassung":"2021 wurde § 41a in das Bundesnaturschutzgesetz (BNatSchG) eingefügt, der Schutz vor Lichtemissionen vorsieht. Die Bestimmung ist noch nicht in Kraft — sie erfordert eine Durchführungsverordnung, die für 2027 im Rahmen der nationalen Biodiversitätsstrategie angekündigt ist.","kernbefund":"Der deutsche Gesetzgeber hat Lichtverschmutzung offiziell als Naturschutzproblem anerkannt und in das Bundesnaturschutzgesetz aufgenommen. Beleuchtete Werbetafeln und digitale DOOH-Screens sind in Deutschland zahlenmäßig fast doppelt so häufig wie Straßenlaternen in urbanen Gebieten und tragen erheblich zur Lichtverschmutzung bei.","relevanz":"Wenn § 41a BNatSchG 2027 in Kraft tritt, könnte er erstmals eine gesetzliche Grundlage bieten, um Werbebeleuchtung als Quelle von Lichtemissionen zu regulieren. Aktuell fehlen spezifische gesetzliche Regeln für Außenwerbebeleuchtung in Deutschland."},{"id":"res-001","title":"Ein großes digitales Werbedisplay verbraucht so viel Strom wie 11 Haushalte pro Jahr (41.627 kWh)","category":"resources","impact_score":9,"year":2022,"source_type":"ngo","institution":"Adfree Cities UK","open_access":true,"file":"data/resources/res-001.md","source_url":"https://adfreecities.org.uk/2022/12/the-electricity-costs-of-digital-out-of-home-advertising-screens/","tags":["energy","electricity","digital-billboard","dooh","households","kwh"],"zusammenfassung":"Adfree Cities UK hat den Stromverbrauch verschiedener Typen digitaler Außenwerbedisplays gemessen und mit Haushaltsstromverbräuchen verglichen.","kernbefund":"Ein großes digitales Werbedisplay (6,4 m × 3,1 m) verbraucht **41.627 kWh pro Jahr** — entspricht dem Jahresstromverbrauch von 11 britischen Haushalten. Ein mittelgroßes Display (1,2 m × 1,8 m, \"Six Sheet\") verbraucht 11.501 kWh/Jahr (3 Haushalte). Eine doppelseitige Einheit im Stadtzentrum verbraucht so viel wie 4 Haushalte. In der Nacht (22–6 Uhr) entspricht ein großes Display dem Verbrauch von 8,5 Haushalten im selben Zeitraum.","relevanz":"Jedes digitale Billboard im öffentlichen Raum verbraucht rund um die Uhr Energie — ausschließlich für kommerzielle Zwecke. Dieser Energieverbrauch hat keinen gesellschaftlichen Nutzen und konkurriert direkt mit dem Ziel der Energiewende."},{"id":"res-002","title":"Werbescreens in Leeds verbrauchen 4,1 GWh/Jahr — so viel wie 3.300 Einwohner","category":"resources","impact_score":8,"year":2021,"source_type":"ngo","institution":"Adfree Cities UK","open_access":true,"file":"data/resources/res-002.md","source_url":"https://adfreecities.org.uk/2021/01/the-ads-in-leeds-consume-as-much-electricity-as-3300-people/","tags":["energy","electricity","city-scale","dooh","leeds","uk"],"zusammenfassung":"Stadtweite Messung des Stromverbrauchs digitaler Werbescreens in Leeds (UK) durch Adfree Cities. Vergleich mit dem Stromverbrauch der Stadtbevölkerung.","kernbefund":"Die digitalen Werbescreens in Leeds verbrauchen insgesamt **4,1 GWh pro Jahr** — genug, um 3.300 Einwohner mit Strom zu versorgen. Dies ist der gemessene Stromverbrauch allein für kommerzielle Außenwerbung in einer mittelgroßen britischen Stadt.","relevanz":"Diese Zahl macht die kumulativen Kosten von Außenwerbung auf Stadtebene greifbar: Allein die Werbung einer Stadt verbraucht so viel Strom wie eine mittelgroße Ortschaft. Multipliziert auf alle Städte Deutschlands oder Europas ergibt sich ein massiver vermeidbarer Energieverbrauch."},{"id":"res-003","title":"Deutschland schaltete 2022 digitale Werbescreens nachts ab — wegen Energiekrise","category":"resources","impact_score":8,"year":2022,"source_type":"ngo","institution":"AV Interactive / AV Magazine","open_access":true,"file":"data/resources/res-003.md","source_url":"https://www.avinteractive.com/territories-news/europe/germany-switches-digital-signs-off-at-night-to-save-energy-22-08-2022/","tags":["energy","germany","night-shutdown","energy-crisis","digital-billboard","kurfuerstendamm","deutsch"],"zusammenfassung":"Während der Energiekrise 2022 (ausgelöst durch den russischen Gaslieferstopp) ordnete Deutschland gemeinsam mit Österreich, Spanien und Frankreich an, dass digitale Werbescreens zwischen 22 und 6 Uhr abgeschaltet werden mussten. Berlins Kurfürstendamm und andere hochsichtbare Werbeflächen gingen nachts dunkel.","kernbefund":"In der Energiekrise 2022 wurden digitale Werbedisplays in mehreren EU-Ländern als nicht-essentielle Energieverbraucher eingestuft und nachts abgeschaltet. Dies ist ein explizites staatliches Bekenntnis, dass Außenwerbung gegenüber essenziellen Energieverbrauchern nachrangig ist.","relevanz":"Wenn der Staat in einer Krise zuerst die Werbescreens abschaltet, bestätigt er implizit: Außenwerbung ist kein öffentlicher Nutzen, sondern ein luxuriöser Ressourcenverbrauch, der bei Engpass sofort verzichtbar ist."},{"id":"res-004","title":"600.000 Tonnen PVC-Werbebanner-Abfall pro Jahr allein in den USA","category":"resources","impact_score":9,"year":2020,"source_type":"government","institution":"EnKad Sciences / European Commission CORDIS","open_access":true,"file":"data/resources/res-004.md","source_url":"https://cordis.europa.eu/article/id/92567-reducing-billboard-advertising-waste","tags":["pvc","vinyl","waste","billboard","plastic","landfill","usa"],"zusammenfassung":"Daten aus dem EU-geförderten ECOBOARD-Projekt (CORDIS) und EnKad Sciences zur Menge des Abfalls, der durch Werbebanner und Plakatwände entsteht.","kernbefund":"In den USA allein werden jährlich **600.000 Tonnen PVC-Werbebanner-Abfall** entsorgt. In der Brüsseler Region entstehen durch 10.000 Werbetafeln jährlich **68.000 m² (ca. 680 Tonnen) Vinyl-Abfall**. In Europa werden alle **2 Wochen mehr als 6 Millionen m² Plakatpapier** weggeworfen — nicht recycelt, mit umweltschädlichen Druckfarben und toxischem Kleber.","relevanz":"Werbebanner bestehen zu 33 % aus PVC-Harz, 36 % Calciumcarbonat, 18 % Polyesterfaser und 9 % Weichmachern (Phthalate). Dieses Material benötigt über **1.000 Jahre zur Zersetzung** in Deponien. Außenwerbung ist eine der größten Quellen von kurzlebigem PVC-Plastikabfall im öffentlichen Raum."},{"id":"res-005","title":"PVC-Werbebanner: Toxisch über den gesamten Lebenszyklus — 1.000 Jahre Zersetzungszeit","category":"resources","impact_score":9,"year":2009,"source_type":"ngo","institution":"Greenpeace USA / Ecology Center","open_access":true,"file":"data/resources/res-005.md","source_url":"https://www.greenpeace.org/usa/wp-content/uploads/legacy/Global/usa/report/2009/4/pvc-the-poison-plastic.html","tags":["pvc","toxic","dioxin","phthalates","plastic","health","lifecycle"],"zusammenfassung":"Greenpeace-Analyse der Toxizität von PVC (Polyvinylchlorid) über den gesamten Lebenszyklus. PVC ist das Material der überwiegenden Mehrheit aller Außenwerbebanner und Plakatrückseiten.","kernbefund":"PVC verursacht Umwelt- und Gesundheitsschäden in jeder Phase: **Produktion** (PVC verbraucht 30–40 % des industriell produzierten Chlors; Dioxin-Entstehung), **Nutzung** (Weichmacher/Phthalate lecken aus und schädigen Hormonsystem, Reproduktion, Atemwege) und **Entsorgung** (Freisetzung von Dioxinen bei Verbrennung; 1.000+ Jahre Zersetzungszeit auf Deponie). Phthalate aus PVC werden in Gewässern, Luft und menschlichem Gewebe nachgewiesen.","relevanz":"Außenwerbebanner sind eines der kurzlebigsten PVC-Produkte überhaupt: Sie werden alle 4 Wochen ausgetauscht — für jede neue Werbekampagne. Der gesamte Lebenszyklus dieses giftigen Materials dient ausschließlich dem kommerziellen Zweck der Aufmerksamkeitsgewinnung."},{"id":"res-006","title":"Druckfarben für Außenwerbung: Toluol, Schwermetalle (Cd, Pb), BPA — massive VOC-Emissionen","category":"resources","impact_score":8,"year":2016,"source_type":"peer-reviewed","institution":"PubMed Central / US EPA","open_access":true,"file":"data/resources/res-006.md","source_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4886190/","tags":["printing-inks","toluene","voc","heavy-metals","bpa","air-pollution","health"],"zusammenfassung":"Wissenschaftliche Analyse der chemischen Inhaltsstoffe von Druckfarben für Großformatdruck (wie er für Außenwerbung und Plakatwände verwendet wird). Druckfarben sind ein oft übersehener Teil der Umweltkosten von Außenwerbung.","kernbefund":"Druckfarben für Werbedruck enthalten als Hauptlösungsmittel **Toluol (ca. 70 % der gesamten emittierten Chemikalien)**, außerdem Methylethylketon, Xylol und 1,1,1-Trichlorethan — alles flüchtige organische Verbindungen (VOC) und gefährliche Luftschadstoffe (HAP). Zusätzlich: **Cadmium, Blei** (Schwermetalle), **Bisphenol A (BPA)** (endokriner Disruptor) und synthetische Antioxidantien.","relevanz":"Jeder Werbedruck setzt diese Chemikalien in die Luft frei — in Druckereien und durch Ausgasung der Plakate im öffentlichen Raum. Die Produktion von Werbematerialien ist eine industrielle Chemikalienquelle, die mit jedem Kampagnenwechsel neu gestartet wird."},{"id":"res-007","title":"Warschauer Bürger würden bis zu 9,3 Mio. €/Jahr zahlen, um Außenwerbung zu reduzieren","category":"resources","impact_score":8,"year":2022,"source_type":"peer-reviewed","institution":"ScienceDirect / Journal of Urban Economics","open_access":false,"file":"data/resources/res-007.md","source_url":"https://www.sciencedirect.com/science/article/pii/S0094119022000298","tags":["economic-externality","willingness-to-pay","warsaw","poland","public-space","outdoor-advertising"],"zusammenfassung":"Peer-reviewte Studie zur Bewertung der externen Kosten von Außenwerbung in Warschau (Polen) durch Messung der Zahlungsbereitschaft der Bevölkerung für Werbe-Reduktion.","kernbefund":"Warschauer Bürger waren bereit zu zahlen:\n- **1,7–4,1 Millionen Euro/Jahr** für eine Reduzierung freistehender Werbeanlagen\n- **5,5–9,3 Millionen Euro/Jahr** für eine Reduzierung von Gebäudewerbung\n- Durchschnittlich **15–23 Euro/Person/Jahr** für Werbe-Reduktion\n\nDiese Zahlen beziffern die externen Kosten von Außenwerbung, die aktuell vollständig von der Öffentlichkeit getragen und von der Werbeindustrie nicht kompensiert werden.","relevanz":"Die Studie quantifiziert erstmals, welchen wirtschaftlichen Schaden Außenwerbung der Stadtbevölkerung zufügt — in Form nicht kompensierter externer Kosten. Hochgerechnet auf deutsche Großstädte ergibt sich ein erheblicher gesellschaftlicher Kostenfaktor."},{"id":"res-008","title":"Aufmerksamkeitsunterbrechungen durch Werbung vernichten bis zu 40 % produktiver Arbeitszeit","category":"resources","impact_score":7,"year":2025,"source_type":"peer-reviewed","institution":"arXiv (Cornell University preprint server)","open_access":true,"file":"data/resources/res-008.md","source_url":"https://arxiv.org/html/2509.06453v2","tags":["attention-economy","cognitive-cost","productivity","pigouvian-tax","externality","distraction"],"zusammenfassung":"Wirtschaftswissenschaftliche Analyse der Aufmerksamkeitsökonomie als externer Kostenfaktor. Untersucht, ob eine Pigou-Steuer auf Aufmerksamkeitskapturierung durch Werbung gerechtfertigt ist.","kernbefund":"Aufmerksamkeitsunterbrechungen durch Werbung und andere Ablenkungen vernichten laut APA-Forschung bis zu **40 % produktiver Arbeitszeit**. Multitasking und erzwungenes Aufmerksamkeitsumschalten erschöpfen neuronale Glukosereserven überproportional. Die Autoren schlagen eine Pigou-Steuer auf Aufmerksamkeitskapturierung vor — analog zu Umweltsteuern — weil die kognitiven Kosten vollständig externalisiert werden: Werbetreibende profitieren, während Betroffene die Kosten tragen.","relevanz":"Außenwerbung ist darauf ausgelegt, unwillkürliche Aufmerksamkeit zu erzwingen (vgl. psych-006). Die damit verbundenen kognitiven Kosten werden komplett externalisiert und von Passanten ohne Einwilligung und ohne Kompensation getragen."},{"id":"res-009","title":"Digitale Werbung emittiert 7,2 Millionen Tonnen CO₂/Jahr — vergleichbar mit Luftfahrt (1,7 % globaler Emissionen)","category":"resources","impact_score":10,"year":2022,"source_type":"ngo","institution":"The Drum (Fachmedium) / Peer-reviewed backing sources","open_access":true,"file":"data/resources/res-009.md","source_url":"https://www.thedrum.com/news/2022/07/15/the-climate-cost-digital-billboards-too-high-justify","tags":["co2","carbon-footprint","digital-advertising","aviation","climate","global"],"zusammenfassung":"Analyse der CO₂-Emissionen des digitalen Werbesektors, veröffentlicht in The Drum, mit Bezug auf mehrere unabhängige Klimastudien.","kernbefund":"Die digitale Werbebranche emittiert **7,2 Millionen Tonnen CO₂ pro Jahr** — entspricht dem Jahresstromverbrauch von 1,4 Millionen US-Haushalten. Bis 2025 wird sie voraussichtlich **1,7 % der globalen Treibhausgasemissionen** verursachen (vergleichbar mit Luftfahrt: 1,9 %). Eine typische digitale Werbekampagne erzeugt **ca. 70 Tonnen CO₂e** — entspricht den Jahresemissionen von 7 Personen.","relevanz":"Digitale Außenwerbung (DOOH) ist der am schnellsten wachsende Teil der Werbebranche. Jedes neue Billboard verstärkt diese Emissionslast — rund um die Uhr, 365 Tage, ohne öffentlichen Nutzen."},{"id":"res-010","title":"Herstellung eines digitalen Billboards: 3,5-fach größerer CO₂-Fußabdruck als ein traditionelles","category":"resources","impact_score":7,"year":2022,"source_type":"ngo","institution":"GenOptic Smart Displays / LED Sign Supply (industry-independent technical analysis)","open_access":true,"file":"data/resources/res-010.md","source_url":"https://www.ledsignsupply.com/billboard-led/environmental/","tags":["manufacturing","lifecycle","lca","led","co2","digital-billboard"],"zusammenfassung":"Technische Analyse des Lebenszyklus digitaler LED-Billboards im Vergleich zu traditionellen statischen Werbetafeln. Bewertet Herstellungs- und Betriebsemissionen.","kernbefund":"Die **Herstellung eines digitalen Billboards** verursacht einen **3,5-mal größeren CO₂-Fußabdruck** als die Herstellung einer traditionellen statischen Werbetafel. LED-Displays über 10 Jahre können jedoch 18 Tonnen CO₂ im Betrieb einsparen verglichen mit LCD-Screens. Die Herstellungsphase allein bedeutet: jeder neue digitale Billboard ist eine erhebliche CO₂-Investition, die erst nach Jahren amortisiert wird.","relevanz":"Der globale DOOH-Markt wächst mit 12 % pro Jahr — neue Screens werden massenhaft installiert. Jede Installation erzeugt den 3,5-fachen Herstellungs-CO₂-Fußabdruck einer traditionellen Tafel, vor dem ersten Werbetag."},{"id":"pol-001","title":"Außenwerbung wird von wenigen globalen 'Big Playern' dominiert (JCDecaux, Clear Channel, Ströer)","category":"politics","impact_score":8,"year":2021,"source_type":"peer-reviewed","institution":"Urban Studies / Independent Research","open_access":false,"file":"data/politics/pol-001.md","source_url":"https://journals.sagepub.com/home/usj","tags":[],"zusammenfassung":"Der Markt für Außenwerbung ist stark monopolisiert. Wenige große Unternehmen (JCDecaux, Clear Channel, Ströer, Wall GmbH, Outfront Media) kontrollieren den Großteil der Werbeflächen im öffentlichen Raum weltweit.","kernbefund":"Diese Oligopolstellung ermöglicht es den Konzernen, enormen politischen und wirtschaftlichen Druck auf Kommunen auszuüben. Lokale und kleine Unternehmen können sich die Werbeflächen in den Innenstädten oft nicht leisten, wodurch der öffentliche Raum hauptsächlich Botschaften globaler Marken transportiert.","relevanz":"Die Dominanz der \"Big Player\" führt zu einer Kommerzialisierung des öffentlichen Raums, bei der demokratische Kontrolle und lokale Wirtschaftsstrukturen geschwächt werden."},{"id":"pol-002","title":"Kommunen privatisieren öffentlichen Raum durch 'Wartehäuschen-Verträge'","category":"politics","impact_score":9,"year":2022,"source_type":"ngo","institution":"Adfree Cities UK","open_access":true,"file":"data/politics/pol-002.md","source_url":"https://adfreecities.org.uk/resources","tags":[],"zusammenfassung":"Städte finanzieren öffentliche Infrastruktur (wie Bushaltestellen und öffentliche Toiletten) häufig nicht mehr aus Steuermitteln, sondern überlassen die Bereitstellung Werbekonzernen im Gegenzug für langfristige Werberechte.","kernbefund":"Diese Verträge, oft über 10 bis 15 Jahre abgeschlossen, binden Kommunen langfristig an die Werbeindustrie. Sie machen es Städten juristisch schwer bis unmöglich, Außenwerbung aus Klimaschutz- oder Gesundheitsgründen nachträglich zu regulieren oder zu verbieten. JCDecaux und Ströer sind Vorreiter in diesem Modell.","relevanz":"Der öffentliche Raum verliert seine Neutralität. Stadtmobiliar wird in erster Linie als Werbeträger entworfen und positioniert, nicht nach den eigentlichen Bedürfnissen der Bürger."},{"id":"pol-003","title":"Lobbyismus der Außenwerber verhindert strengere Lichtschutz- und Werbeverbotsgesetze","category":"politics","impact_score":8,"year":2020,"source_type":"ngo","institution":"Corporate Europe Observatory","open_access":true,"file":"data/politics/pol-003.md","source_url":"https://corporateeurope.org","tags":[],"zusammenfassung":"Die Werbeindustrie investiert erhebliche Summen in Lobbyarbeit auf kommunaler und nationaler Ebene, um Regulierungen von DOOH (Digital Out of Home) Bildschirmen zu verhindern oder abzuwächen.","kernbefund":"Berichte von NGOs wie Corporate Europe Observatory zeigen, dass Außenwerber systematisch Druck ausüben, um Ausnahmeregelungen bei Lichtemissionsgesetzen (z.B. Abschaltung bei Nacht) und Einschränkungen für ungesunde Produktwerbung zu erwirken. Argumentiert wird oft mit der angeblichen finanziellen Abhängigkeit der Kommunen von den Werbeeinnahmen.","relevanz":"Der politische Einfluss der Big Player führt dazu, dass gesundheits- und umweltpolitische Maßnahmen zum Schutz der Bürger zugunsten von Unternehmensgewinnen blockiert werden."},{"id":"safety-001","title":"Digitale Werbetafeln erhöhen die Unfallgefahr durch visuelle Ablenkung signifikant","category":"safety","impact_score":9,"year":2022,"source_type":"ngo","institution":"Scenic America","open_access":true,"file":"data/safety/safety-001.md","source_url":"https://www.scenic.org/wp-content/uploads/2021/10/Billboard-Safety-Study-Compendium-10-16-2020.pdf","tags":[],"zusammenfassung":"Umfassende Studien-Sammlungen von Scenic America zeigen, dass digitale Werbetafeln (DOOH) den Blick von Autofahrern erheblich länger von der Straße ablenken als statische Schilder.","kernbefund":"Ein Blick weg von der Straße, der länger als zwei Sekunden dauert – was häufig durch wechselnde oder animierte digitale Inhalte ausgelöst wird –, erhöht das Unfallrisiko drastisch. Studien in den USA (u.a. in Alabama und Florida) belegen erhöhte Unfallraten in direkter Nähe zu solchen Anlagen.","relevanz":"DOOH-Anlagen sind nicht nur eine visuelle Verschmutzung, sondern ein konkretes Risiko für die öffentliche Verkehrssicherheit. Profitinteressen der Werbeindustrie stehen hier im direkten Widerspruch zum Schutz von Verkehrsteilnehmern."},{"id":"safety-002","title":"Methodische Mängel in industrie-finanzierten Sicherheitsstudien zu digitalen Werbetafeln","category":"safety","impact_score":8,"year":2014,"source_type":"ngo","institution":"Jerry Wachtel / Scenic America","open_access":true,"file":"data/safety/safety-002.md","source_url":"https://www.scenic.org","tags":[],"zusammenfassung":"Die Werbeindustrie zitiert häufig Studien (wie die FHWA-Studie von 2013), um zu behaupten, digitale Werbetafeln seien verkehrssicher. Unabhängige Überprüfungen zeigen jedoch schwere methodische Mängel in diesen industrie-unterstützten Untersuchungen auf.","kernbefund":"Unabhängige Verkehrssicherheitsexperten (wie Jerry Wachtel) weisen nach, dass entlastende Studien oft an zu kleinen Stichproben, untauglichen Messgeräten und fehlerhaften Versuchsaufbauten leiden. Unabhängige Daten zeigen konsistent ein erhöhtes Risiko für kognitive und visuelle Ablenkung.","relevanz":"Die Sicherheit von DOOH-Werbung wird durch gezieltes Lobbying und potenziell fehlerhafte Regierungsstudien systematisch verharmlost."},{"id":"env-008","title":"Werbung für SUVs und fossile Produkte blockiert Klimaziele ('Upselling Smoke')","category":"environment","impact_score":9,"year":2020,"source_type":"ngo","institution":"Badvertising / New Weather Institute","open_access":true,"file":"data/environment/env-008.md","source_url":"https://static1.squarespace.com/static/5ebd0080238e863d04911b51/t/5f21659998148a15d80ba9be/1596024223673/Upselling+Smoke+FINAL+23+07+20.pdf","tags":[],"zusammenfassung":"Die \"Badvertising\"-Kampagne belegt, dass Werbung für stark emittierende Produkte (wie SUVs und Kurzstreckenflüge) direkt den Absatzzahlen und damit den CO2-Emissionen zugutekommt, und zieht Parallelen zur Tabakwerbung.","kernbefund":"Trotz massiver Bemühungen um Klimaschutz treibt Außenwerbung aktiv den Verkauf von besonders klimaschädlichen SUVs an. Der Bericht argumentiert, dass eine Verkehrswende unmöglich ist, solange der öffentliche Raum für die Bewerbung der schädlichsten Transportmittel genutzt wird.","relevanz":"Außenwerbung ist nicht klimaneutral – sie ist ein aktiver Treiber der Klimakrise, solange High-Carbon-Produkte beworben werden dürfen."},{"id":"equity-003","title":"Außenwerbung steht überproportional oft in einkommensschwachen Vierteln ('Unavoidable Impact')","category":"equity","impact_score":9,"year":2022,"source_type":"ngo","institution":"Adfree Cities","open_access":true,"file":"data/equity/equity-003.md","source_url":"https://adfreecities.org.uk/unavoidable-impact/","tags":[],"zusammenfassung":"Eine umfassende Untersuchung in Großbritannien zeigt, dass kommerzielle Außenwerbung in einkommensschwachen Gebieten bis zu sechsmal häufiger vorkommt als in wohlhabenden Stadtteilen.","kernbefund":"Der Report \"Unavoidable Impact\" belegt, dass Menschen in ärmeren Vierteln nicht nur häufiger Werbung für Junk-Food, Alkohol und Glücksspiel ausgesetzt sind, sondern auch unter der visuellen Verschmutzung und Lichtverschmutzung (DOOH) stärker leiden. Wohlhabende Wohngebiete wehren Werbetafeln oft erfolgreich ab.","relevanz":"Außenwerbung verschärft soziale und gesundheitliche Ungleichheiten (Environmental Justice), indem vulnerable Bevölkerungsgruppen systematisch ins Visier genommen werden."},{"id":"env-009","title":"LANUV NRW Fachbericht 113: Kommerzielle Außenbeleuchtung treibt regionale Lichtverschmutzung","category":"environment","impact_score":8,"year":2021,"source_type":"government","institution":"Landesamt für Natur, Umwelt und Verbraucherschutz NRW (LANUV)","open_access":true,"file":"data/environment/env-009.md","source_url":"https://www.lanuv.nrw.de","tags":[],"zusammenfassung":"Das nordrhein-westfälische Landesamt (LANUV) hat in einer landesweiten Bestandsaufnahme die Himmelsaufhellung in NRW untersucht. Dabei wird kommerzielle Außenbeleuchtung und Lichtwerbung als relevanter Immissionsfaktor benannt.","kernbefund":"Der Fachbericht und die dazugehörigen Leitfäden (\"Licht-Erlass\" NRW) zeigen auf, dass künstliche Außenbeleuchtung, zu der auch intensiv leuchtende DOOH-Anlagen zählen, zu massiven Störungen des Biorhythmus von Menschen und zum Insektensterben beitragen. Das Amt empfiehlt strenge Begrenzungen der Leuchtdichten und nächtliche Abschaltungen zur Emissionsminderung.","relevanz":"Staatliche Umweltbehörden in dicht besiedelten Bundesländern wie NRW erkennen Außenwerbung offiziell als ernstzunehmende umwelt- und gesundheitsschädliche Immissionsquelle an, die strenger Regulierung bedarf."},{"id":"pol-004","title":"Kölner Werbekonzern Ströer sichert sich durch Lobbying Monopolstellung in NRW-Kommunen","category":"politics","impact_score":8,"year":2021,"source_type":"ngo","institution":"Correctiv / Lobbyregister des Bundestages","open_access":true,"file":"data/politics/pol-004.md","source_url":"https://correctiv.org","tags":[],"zusammenfassung":"Der in Köln (NRW) ansässige Außenwerbe-Riese Ströer SE & Co. KGaA nutzt seine Finanzkraft und direkten politischen Lobbyismus, um sich exklusive und langfristige Konzessionen für Werbeflächen auf staatlichem Grund zu sichern.","kernbefund":"Recherchen von investigativen NGOs wie Correctiv zeigen, dass die Marktmacht des Unternehmens so groß ist, dass Städte bei der Vergabe von Stadtmobiliar-Verträgen (Wartehäuschen) de facto keine echten Alternativen mehr haben. Ströer ist zudem offiziell im Lobbyregister eingetragen und nimmt direkten Einfluss auf stadtentwicklungspolitische Fragen und Datenschutzrichtlinien.","relevanz":"Die massive lokale Verwurzelung von Werbekonzernen führt zu einer Abhängigkeit der Kommunen. Demokratische Gestaltung des öffentlichen Raums wird durch wirtschaftliche Monopole untergraben."},{"id":"reg-008","title":"Bürgerinitiativen in NRW fordern restriktive Bauordnungen gegen digitale Werbetafeln","category":"regulation","impact_score":7,"year":2023,"source_type":"ngo","institution":"Lokale Bürgerinitiativen NRW","open_access":true,"file":"data/regulation/reg-008.md","source_url":"https://koeln-werbefrei.de","tags":[],"zusammenfassung":"In mehreren Großstädten in NRW (insbesondere Köln, der Heimatstadt von Ströer, sowie Münster) haben sich zivilgesellschaftliche Initiativen formiert, die ein Verbot oder starke Einschränkungen kommerzieller Außenwerbung fordern.","kernbefund":"Diese Initiativen streben an, die lokale Bauordnung so zu verändern, dass besonders digitale Werbeanlagen (DOOH) und Wechsellichtanlagen im öffentlichen Raum verboten werden. Sie argumentieren mit visuellem Lärm, unnötigem Energieverbrauch in Zeiten der Klimakrise und der Kommerzialisierung der Städte.","relevanz":"Der Widerstand gegen Außenwerbung formiert sich stark auf der Graswurzelebene direkt in den Kommunen, in denen die Werbeflächen aufgestellt werden. Es zeigt den wachsenden Unmut der Zivilgesellschaft über die Privatisierung des öffentlichen Raums."},{"id":"priv-001","title":"DOOH-Screens erfassen heimlich biometrische Daten zur Zielgruppenanalyse","category":"privacy","impact_score":9,"year":2022,"source_type":"ngo","institution":"Adfree Cities / Privacy International","open_access":true,"file":"data/privacy/priv-001.md","source_url":"https://adfreecities.org.uk/privacy","tags":[],"zusammenfassung":"Moderne digitale Werbetafeln (DOOH) sind zunehmend mit Kameras und Sensoren ausgestattet, die biometrische Daten und Bewegungsprofile von Passanten erfassen, um Werbung zielgruppengenau (\"programmatic\") auszuspielen.","kernbefund":"Untersuchungen von NGOs zeigen, dass Firmen Technologien zur automatischen Gesichtserkennung (Automated Facial Detection - AFD) sowie Wi-Fi-Sniffing nutzen, um Alter, Geschlecht, Stimmung und Verweildauer von Personen vor Bildschirmen zu analysieren. Dies geschieht im öffentlichen Raum meist ohne aktive Zustimmung (Opt-in) der Betroffenen, was massive datenschutzrechtliche und ethische Bedenken aufwirft.","relevanz":"Außenwerbung entwickelt sich von einem passiven Sendemedium zu einer proaktiven Überwachungsinfrastruktur im öffentlichen Raum. Bürger können sich diesem Tracking kaum entziehen (Opt-out Illusion), da sie sich im öffentlichen Raum bewegen müssen."},{"id":"safety-003","title":"Schweden verbietet digitale Werbetafeln an Landstraßen nach Studie der Transportbehörde","category":"safety","impact_score":10,"year":2012,"source_type":"government","institution":"Swedish Transport Administration (Trafikverket)","open_access":true,"file":"data/safety/safety-003.md","source_url":"https://www.scenic.org/wp-content/uploads/2021/10/Billboard-Safety-Study-Compendium-10-16-2020.pdf","tags":[],"zusammenfassung":"Eine detaillierte Feldstudie der schwedischen Transportbehörde (Trafikverket) wies nach, dass digitale Werbetafeln Fahrer signifikant ablenken. Als direkte Konsequenz ordnete die schwedische Regierung den Abbau der Tafeln an.","kernbefund":"Die Studie ergab, dass Fahrer ihren Blick bei DOOH-Anlagen deutlich länger von der Straße abwenden (oft über 2 Sekunden), verglichen mit statischen Schildern. Da Blickabwendungen über 2 Sekunden als hochgefährlich gelten, entschied die Regierung, dass die wirtschaftlichen Interessen der Betreiber dem Schutz der Verkehrssicherheit unterzuordnen sind. Das Experiment zur Genehmigung solcher Tafeln wurde daraufhin abgebrochen.","relevanz":"Staatliche Studien ohne Industrie-Einfluss kommen zu klaren, negativen Ergebnissen bezüglich der Verkehrssicherheit von DOOH-Anlagen und können zu rigorosen Verboten führen."},{"id":"health-008","title":"Glücksspiel- und Sportwetten-Werbung im öffentlichen Raum normalisiert Suchtverhalten","category":"health","impact_score":9,"year":2023,"source_type":"ngo","institution":"Public Health England / Adfree Cities","open_access":true,"file":"data/health/health-008.md","source_url":"https://adfreecities.org.uk/2023/07/why-we-must-ban-gambling-ads-on-public-infrastructure/","tags":[],"zusammenfassung":"Die Allgegenwärtigkeit von Sportwetten- und Glücksspielwerbung an Bushaltestellen und auf Plakatwänden wird von Public Health Experten als massiver Treiber für Suchtverhalten identifiziert.","kernbefund":"Außenwerbung für Glücksspiel normalisiert riskantes Verhalten, triggert trockene Spielsüchtige (Relapse) und führt Jugendliche frühzeitig an Sportwetten heran. Anders als bei TV-Werbung können vulnerable Personen der Werbung im öffentlichen Raum, etwa auf dem Weg zur Schule oder Arbeit, nicht ausweichen.","relevanz":"Außenwerbung fungiert als direkter Multiplikator für gesundheitliche und finanzielle Krisen vulnerabler Gruppen durch die aggressive Bewerbung von Suchtmitteln (neben Alkohol auch Glücksspiel)."},{"id":"res-011","title":"Eine doppelseitige digitale Werbetafel verbraucht jährlich den Strom von 3 bis 4 Durchschnittshaushalten","category":"resources","impact_score":9,"year":2022,"source_type":"ngo","institution":"Adfree Cities / New Weather Institute","open_access":true,"file":"data/resources/res-011.md","source_url":"https://adfreecities.org.uk/2022/12/the-electricity-costs-of-digital-out-of-home-advertising-screens/","tags":[],"zusammenfassung":"Trotz des Wechsels zu LED-Technologie ist der absolute Energieverbrauch von digitalen Werbetafeln (DOOH) immens hoch, da sie rund um die Uhr leuchten, gekühlt werden müssen und extrem hell strahlen.","kernbefund":"Recherchen belegen, dass ein typischer, doppelseitiger digitaler Werbebildschirm an einer Bushaltestelle etwa 11.000 bis 14.000 kWh Strom pro Jahr verbraucht. Dies entspricht dem Stromverbrauch von drei bis vier durchschnittlichen Haushalten. Dieser massive Ressourcenverbrauch findet mitten in einer globalen Energie- und Klimakrise statt.","relevanz":"DOOH steht im direkten Widerspruch zu städtischen und nationalen Energieeinsparzielen. Die von der Industrie beworbenen \"Net Zero\"-Strategien kompensieren oft nur, mindern aber nicht den exorbitanten direkten Stromverbrauch der Hardware."},{"id":"eco-005","title":"Hoch-Emissions-Branchen (Airlines, SUVs, Fast Food) dominieren die Werbebudgets für digitale Außenwerbung","category":"economy","impact_score":8,"year":2021,"source_type":"ngo","institution":"Badvertising / New Weather Institute","open_access":true,"file":"data/economy/eco-005.md","source_url":"https://www.badverts.org","tags":[],"zusammenfassung":"Eine Analyse der Werbekunden für Außenwerbung zeigt, dass Flächen im öffentlichen Raum überproportional oft von klimaschädlichen Branchen gebucht werden, um nicht-nachhaltigen Konsum anzukurbeln.","kernbefund":"Die profitabelsten Kunden für Außenwerbekonzerne sind Automobilhersteller (insbesondere SUVs), Billigfluglinien, Fast-Food-Ketten und die Modeindustrie (Fast Fashion). Durch die ständige visuelle Präsenz dieser Produkte im öffentlichen Raum wird ein extrem ressourcenintensiver Lebensstil als gesellschaftliche Norm zementiert (induzierter Konsum).","relevanz":"Außenwerbung ist nicht nur durch den Stromverbrauch der Tafeln selbst schädlich (Scope 1/2), sondern vor allem durch die sogenannten \"Advertised Emissions\" (Scope 3) – die Treibhausgase, die durch den beworbenen Mehrkonsum von High-Carbon-Produkten entstehen."},{"id":"psych-007","title":"Bewegtbild auf digitalen Werbescreens erzwingt unwillkürliche Aufmerksamkeit ('Orienting Response')","category":"psychology","impact_score":9,"year":2021,"source_type":"ngo","institution":"Adfree Cities / Cognitive Psychology Studies","open_access":true,"file":"data/psychology/psych-007.md","source_url":"https://adfreecities.org.uk","tags":[],"zusammenfassung":"Die Psychologie hinter digitalen Screens (DOOH) basiert auf der Ausnutzung evolutionärer Reflexe. Im Gegensatz zu statischen Plakaten zwingen wechselnde oder bewegte Bilder das menschliche Gehirn dazu, hinzusehen.","kernbefund":"Der sogenannte Orientierungsreflex (Orienting Response) ist ein unwillkürlicher neurologischer Mechanismus, der Menschen zwingt, auf plötzliche Veränderungen in ihrem peripheren Sichtfeld (wie Lichtwechsel oder Bewegung auf einem Screen) zu achten, da dies evolutionär mit Gefahr assoziiert ist. DOOH-Anlagen nutzen diesen Reflex gezielt aus, um Aufmerksamkeit zu \"stehlen\". Man kann sich nicht entscheiden, nicht hinzusehen.","relevanz":"Digitale Werbetafeln sind psychologisch weitaus aggressiver als traditionelle OOH-Plakate. Sie stellen einen permanenten kognitiven Stressor im öffentlichen Raum dar, da sie das Gehirn in einem ständigen Zustand der Alarmbereitschaft halten."},{"id":"urban-006","title":"Freistehende, doppelseitige Werbeanlagen fungieren als visuelle und physische Barrieren","category":"urban","impact_score":8,"year":2020,"source_type":"peer-reviewed","institution":"Public Space Research Group","open_access":true,"file":"data/urban/urban-006.md","source_url":"https://www.publicspace.org","tags":[],"zusammenfassung":"Das Hardware-Design von sogenannten \"Doppel-Postern\" (City-Light-Boards) hat weitreichende Konsequenzen für die Architektur des öffentlichen Raums, da sie physisch in Gehwege und Fußgängerzonen eingreifen.","kernbefund":"Während klassische Plakate meist flach an Wänden montiert werden, werden doppelseitige Werbeanlagen (oft 2 bis 3 Meter hoch) freistehend und quer zur Laufrichtung von Fußgängern installiert, um die maximale Sichtbarkeit aus beiden Richtungen zu garantieren. Studien zeigen, dass diese Platzierung Gehwege verengt, Barrierefreiheit für Rollstuhlfahrer einschränkt und städtische Sichtachsen zerschneidet.","relevanz":"Die Hardware von Doppel-Postern privatisiert den tatsächlichen physischen Raum (den Bürgersteig) und ordnet die Bewegungsfreiheit der Fußgänger der Sichtbarkeit von Werbebotschaften unter."},{"id":"env-010","title":"Aktive LED-Screens verursachen ein Vielfaches an Lichtverschmutzung gegenüber hinterleuchteten Plakaten","category":"environment","impact_score":9,"year":2022,"source_type":"ngo","institution":"DarkSky International","open_access":true,"file":"data/environment/env-010.md","source_url":"https://darksky.org","tags":[],"zusammenfassung":"Der technologische Wechsel von klassischen \"beleuchteten Flächen\" (hinterleuchtetes Papier) zu digitalen LED-Screens (DOOH) bedeutet eine drastische Verschlechterung der Lichtimmissionen.","kernbefund":"Ein traditionelles City-Light-Poster leuchtet passiv, indem fluoreszierendes Licht durch bedrucktes Papier gefiltert wird. Ein digitaler DOOH-Screen besteht jedoch aus tausenden winzigen LED-Lampen, die Licht direkt (und oft ungerichtet) in die Umgebung emittieren. Um bei Tageslicht sichtbar zu sein, strahlen LEDs extrem hell (bis zu 7.000 Nits). Selbst im gedimmten Nachtmodus tragen sie aufgrund des blaulastigen LED-Spektrums massiv zur Himmelsaufhellung (Skyglow) bei.","relevanz":"Städte, die digitale Screens zulassen, tauschen nicht einfach ein Werbeformat gegen ein anderes. Sie erlauben den Bau massiver, aktiver Lichtquellen, die nachweislich Schlafzyklen (Circadianer Rhythmus) stören und Insektenpopulationen dezimieren."},{"id":"reg-009","title":"Der fließende Umbau von beleuchteten Werbeflächen zu digitalen Screens umgeht Regulationsprozesse","category":"regulation","impact_score":8,"year":2023,"source_type":"ngo","institution":"Adfree Cities","open_access":true,"file":"data/regulation/reg-009.md","source_url":"https://adfreecities.org.uk","tags":[],"zusammenfassung":"Werbekonzerne nutzen Lücken in städtischen Bau- und Planungsordnungen, um den öffentlichen Raum ohne erneute Bürgerbeteiligung zu digitalisieren.","kernbefund":"In vielen Kommunen gelten Verträge oder Genehmigungen für bestehende \"beleuchtete Werbeanlagen\" (z.B. analoge City-Light-Poster). Außenwerber nutzen diese bestehenden Genehmigungen zunehmend, um das Papier-Plakat physisch durch einen grellen DOOH-LED-Screen auszutauschen (\"Digital Upgrade\"). Da die physischen Ausmaße des Kastens oft gleich bleiben, werten Planungsämter dies oft fälschlicherweise nicht als Neubau, wodurch Umweltprüfungen und Einsprüche von Anwohnern umgangen werden.","relevanz":"Die gravierenden Unterschiede in der Lichtemission und psychologischen Wirkung zwischen analogem Plakat und digitalem Screen werden durch juristische Spitzfindigkeiten ignoriert. Eine rigorose Anpassung der Bauordnungen ist zwingend nötig."},{"id":"alt-001","title":"Werbefreie Städte reinvestieren Werbeflächen in Kulturförderung und lokale Kunst","category":"alternatives","impact_score":8,"year":2014,"source_type":"government","institution":"The Guardian / City of Grenoble","open_access":true,"file":"data/alternatives/alt-001.md","source_url":"https://www.theguardian.com/cities/2015/aug/11/can-cities-kick-ads-ban-urban-billboards","tags":[],"zusammenfassung":"Die französische Stadt Grenoble hat bewiesen, dass kommerzielle Außenwerbung nicht alternativlos ist. Statt Werbeverträge zu verlängern, wurden kommerzielle Flächen abgebaut oder durch Bürgerinformationen und Kunst ersetzt.","kernbefund":"Im Jahr 2014 entschied der Bürgermeister von Grenoble, 326 kommerzielle Werbetafeln aus dem öffentlichen Raum zu entfernen. Anstatt des erwarteten kommerziellen Vakuums wurden 50 neue Flächen für lokale kulturelle und soziale Ankündigungen geschaffen. Die Stadt pflanzte Bäume an den ehemaligen Werbestandorten. Der Verlust an Werbeeinnahmen (ca. 600.000 Euro) wurde durch Kürzungen im Repräsentationsbudget des Bürgermeisters und durch die positiven Effekte der gesteigerten Lebensqualität kompensiert.","relevanz":"Dieses Beispiel entkräftet das Branchen-Argument, Städte seien finanziell zwingend auf Außenwerbung angewiesen. Der öffentliche Raum kann aktiv für Kulturförderung, Kunst und Begrünung genutzt werden, anstatt ihn an Werbekonzerne zu privatisieren."},{"id":"alt-002","title":"Finanzierung von ÖPNV-Infrastruktur durch Abgaben statt durch Werbekonzerne","category":"alternatives","impact_score":7,"year":2023,"source_type":"ngo","institution":"Adfree Cities / Local Government Analysis","open_access":true,"file":"data/alternatives/alt-002.md","source_url":"https://adfreecities.org.uk","tags":[],"zusammenfassung":"Das Argument, Außenwerbung sei notwendig zur Finanzierung von Bus- und Straßenbahnhaltestellen, ist strukturell fehlerhaft. Es gibt nachhaltigere, werbefreie Finanzierungsmodelle.","kernbefund":"Städte tauschen oft die Bereitstellung von Wartehäuschen gegen weitreichende Werberechte ein (Public-Private Partnerships). Analysen zeigen jedoch, dass die indirekten Kosten (Stromverbrauch der Tafeln, Ablenkung im Verkehr, induzierter CO2-Ausstoß) den scheinbaren finanziellen Vorteil oft übersteigen. Alternativ finanzieren Städte wie São Paulo (nach dem Werbeverbot \"Cidade Limpa\") ihre Infrastruktur durch umgelegte Abgaben, Steuern auf Leerstand oder städtische Eigenfinanzierung, wodurch sie die volle Kontrolle über das Design und den Energieverbrauch ihres Stadtmobiliars behalten.","relevanz":"Infrastrukturfinanzierung wird oft als Erpressungsmittel der AdTech-Industrie genutzt. Eine Entkopplung von Stadtmobiliar und Werbevermarktung ist fiskalisch möglich und führt zu besseren, werbefreien Stadträumen."},{"id":"reg-010","title":"Werbekonzerne ignorieren systematisch Bauvorschriften und Helligkeitslimits","category":"regulation","impact_score":9,"year":2022,"source_type":"ngo","institution":"Adfree Cities","open_access":true,"file":"data/regulation/reg-010.md","source_url":"http://adfreecities.org.uk/resources/how-to-object-to-new-advertising-billboards/","tags":[],"zusammenfassung":"Die Installation und der Betrieb von digitalen Werbetafeln verstoßen häufig gegen lokale Bauordnungen. Konzerne nutzen die Überlastung kommunaler Behörden aus.","kernbefund":"Untersuchungen in Großbritannien zeigen eine systematische Missachtung von Auflagen. Oft werden DOOH-Anlagen gänzlich ohne Baugenehmigung errichtet. Selbst wenn Auflagen existieren, werden vertraglich vereinbarte Helligkeitslimits (Luminanz) überschritten oder verpflichtende Nachtabschaltungen (z.B. von 23 bis 06 Uhr) einfach ignoriert. Werbekonzerne nehmen Bußgelder oft als \"Cost of Doing Business\" in Kauf, da die Einnahmen durch die illegale Werbezeit höher sind und städtische Bauämter zu unterbesetzt sind, um Abschaltverfügungen (Discontinuance Notices) juristisch durchzusetzen.","relevanz":"Die Branche kann nicht effektiv kontrolliert werden. Wenn die Hardware einmal physisch installiert ist, liegt die Beweislast (Messung der Helligkeit) und der Aufwand der rechtlichen Verfolgung komplett bei den Kommunen und Anwohnern."},{"id":"reg-011","title":"Britische Kommunen erlassen strikte Werbeverbote für Hoch-Emissions-Produkte","category":"regulation","impact_score":8,"year":2023,"source_type":"government","institution":"Badvertising UK / City Councils","open_access":true,"file":"data/regulation/reg-011.md","source_url":"https://www.badverts.org/engage-with-your-local-council","tags":[],"zusammenfassung":"Immer mehr städtische und regionale Regierungen nutzen ihre Rolle als Grundstückseigentümer, um Werbung für klimaschädliche Produkte auf städtischer Infrastruktur zu verbieten.","kernbefund":"Städte wie Edinburgh, Sheffield, Cambridgeshire und Somerset haben in ihren Werberichtlinien juristisch bindende Klauseln eingeführt. Diese verbieten Werbekonzernen (wie JCDecaux oder Clear Channel), auf städtischem Grund (z.B. Bushaltestellen, städtische Plakatwände) Werbung für Flugreisen, fossil angetriebene SUVs und fossile Brennstoffe auszuspielen. Die Kommunen argumentieren, dass die Bewerbung dieser Produkte im direkten Widerspruch zu den städtischen Klimaschutzzielen (\"Net Zero\") steht.","relevanz":"Diese Regelsätze beweisen, dass die Regulierung der *Inhalte* von Außenwerbung auf lokaler Ebene rechtlich machbar und politisch gewollt ist. Es etabliert \"High-Carbon\" auf derselben Verbots-Stufe wie Tabak- oder Waffenwerbung."},{"id":"reg-012","title":"Das Schweizer Bundesgericht bestätigt die Legalität kommunaler Werbeverbote","category":"regulation","impact_score":10,"year":2024,"source_type":"government","institution":"Swiss Federal Supreme Court (Bundesgericht)","open_access":true,"file":"data/regulation/reg-012.md","source_url":"https://www.bger.ch","tags":[],"zusammenfassung":"Die juristische Annahme, ein Komplettverbot von Außenwerbung sei ein unzulässiger Eingriff in die Wirtschaftsfreiheit, wurde vom höchsten Schweizer Gericht widerlegt.","kernbefund":"Die Gemeinde Vernier (Kanton Genf) beschloss ein Verbot kommerzieller Plakatwerbung auf Gemeindegebiet, um das Landschaftsbild zu schützen und visuelle Umweltverschmutzung zu reduzieren. Werbekonzerne (u.a. APG SGA) klagten dagegen durch alle Instanzen. Im Jahr 2024 urteilte das Schweizer Bundesgericht final zugunsten der Gemeinde: Das Verbot ist rechtmäßig. Das Gericht stellte fest, dass das öffentliche Interesse an einem intakten Ortsbild und dem Schutz der Einwohner vor aufgedrängtem Konsumdruck schwerer wiegt als die rein kommerziellen Interessen der Werbeindustrie.","relevanz":"Dieses Urteil ist ein massiver juristischer Präzedenzfall für ganz Europa. Es gibt Städten und Kommunen die rechtliche Sicherheit, dass Zero-Billboard-Policies verhältnismäßig und durchsetzbar sind."},{"id":"reg-013","title":"Die Selbstregulierung der Werbeindustrie ist strukturell unzureichend und reaktiv","category":"regulation","impact_score":8,"year":2023,"source_type":"ngo","institution":"Adfree Cities / Public Health Agencies","open_access":true,"file":"data/regulation/reg-013.md","source_url":"https://adfreecities.org.uk/regulation","tags":[],"zusammenfassung":"Organe der \"freiwilligen Selbstkontrolle\" (wie der Werberat in Deutschland oder die ASA in UK) sind nicht in der Lage, schädliche Außenwerbung effektiv zu verhindern.","kernbefund":"Die Selbstregulierungssysteme der Werbebranche weisen einen strukturellen Konstruktionsfehler auf: Sie agieren fast ausschließlich reaktiv. Es gibt keinen Pre-Clearance-Prozess für Plakate. Das bedeutet, dass eine stark schädliche oder irreführende Werbung erst aufgehängt wird und der Öffentlichkeit (inkl. Kindern) aufgezwungen wird. Bis Beschwerden eingereicht, geprüft und Rügen ausgesprochen sind, ist der meist ein- bis zweiwöchige Buchungszeitraum der Plakate ohnehin abgelaufen. Der Schaden ist bereits eingetreten.","relevanz":"\"Wir halten uns an die Regeln des Werberats\" ist ein Argument der Industrie, das Sicherheit suggeriert, de facto aber wertlos ist. Um Bürger zu schützen, müssen Städte proaktive Ausschlusskriterien (wie Junkfood-Bans in London) rechtlich verankern."},{"id":"reg-014","title":"Vier US-Bundesstaaten haben Außenwerbung komplett verboten, um Wirtschaft und Tourismus zu schützen","category":"regulation","impact_score":9,"year":2021,"source_type":"ngo","institution":"Scenic America","open_access":true,"file":"data/regulation/reg-014.md","source_url":"https://www.scenic.org/sign-control/billboards/billboard-bans/","tags":[],"zusammenfassung":"Ein striktes Verbot von Außenwerbung ist kein wirtschaftlicher Nachteil, sondern ein harter wirtschaftlicher Standortvorteil, wie vier US-Bundesstaaten beweisen.","kernbefund":"In den Vereinigten Staaten haben die vier Bundesstaaten Hawaii, Maine, Vermont und Alaska Außenwerbung auf ihrem gesamten Staatsgebiet gesetzlich verboten. Entgegen der Behauptung der Werbeindustrie, Verbote würden der lokalen Wirtschaft schaden, argumentieren die Regierungen dieser Bundesstaaten genau andersherum: Der Schutz der Landschaft (\"Scenic Beauty\") vor visueller Verschmutzung (\"Billboard Blight\") ist ein entscheidender Faktor, um den Tourismus und die Lebensqualität zu fördern. Der Erhalt des unverbauten Landschaftsbildes ist wirtschaftlich wertvoller als Werbeeinnahmen.","relevanz":"Diese massiven juristischen Präzedenzfälle entkräften das \"TINA\"-Argument (There Is No Alternative) der Industrie. Ein Totalverbot von Außenwerbung ist auf staatlicher Ebene umsetzbar und wirtschaftlich sinnvoll."},{"id":"urban-007","title":"Werbetafeln in Wohngebieten senken signifikant die angrenzenden Immobilienwerte","category":"urban","impact_score":8,"year":2019,"source_type":"ngo","institution":"Scenic America / Urban Studies","open_access":true,"file":"data/urban/urban-007.md","source_url":"https://www.scenic.org","tags":[],"zusammenfassung":"Die visuelle Verschmutzung durch Außenwerbung schadet nicht nur der Ästhetik, sondern hat direkt messbare negative ökonomische Auswirkungen auf Anwohner.","kernbefund":"Analysen des US-Immobilienmarktes zeigen, dass die unmittelbare Nähe zu gewerblichen Werbetafeln (sogenannter \"Billboard Blight\") den Wert von angrenzenden Wohnimmobilien signifikant senkt. Die Faktoren hierfür sind Lichtverschmutzung durch Beleuchtung oder digitale LEDs, die Zerstörung von Sichtachsen und die psychologische Assoziation von Werbetafeln mit Vernachlässigung und reiner Kommerzialisierung. Besonders kritisch ist dies, da Werbetafeln historisch überproportional in ohnehin einkommensschwachen Vierteln konzentriert werden (\"Redlining\").","relevanz":"Außenwerbung verschiebt Vermögenswerte: Werbekonzerne generieren Profite, während Anwohner die realen Kosten durch Lärm, Licht und sinkende Immobilienwerte tragen (negative Externalitäten)."},{"id":"alt-003","title":"Metropolen ersetzen kommerzielle Werbetafeln temporär durch stadtweite Kunstausstellungen","category":"alternatives","impact_score":8,"year":2015,"source_type":"government","institution":"The Guardian","open_access":true,"file":"data/alternatives/alt-003.md","source_url":"https://www.theguardian.com/world/2015/may/07/tehran-swaps-death-to-america-billboards-picasso-matisse-hockney-iran","tags":[],"zusammenfassung":"Die Infrastruktur der Außenwerbung kann subversiv umgenutzt werden. Ein Projekt in Teheran bewies die massive gesellschaftliche und psychologische Heilwirkung von Kunst anstelle von Konsumdruck.","kernbefund":"Im Mai 2015 wies der Bürgermeister von Teheran (Iran) an, im Rahmen des Projekts \"A Gallery as Big as a Town\" alle rund 1.500 kommerziellen Werbetafeln der Millionenmetropole für zehn Tage zu überkleben. Statt Werbung für Smartphones und Waschmittel zeigten die Tafeln plötzlich Werke von Picasso, Matisse, Munch sowie traditionelle persische Kunst. Das Experiment zeigte eindrucksvoll, dass die logistische Infrastruktur der Werbeindustrie genutzt werden kann, um eine Stadt in eine gigantische Open-Air-Galerie zu verwandeln und den Bürgern echten kulturellen Mehrwert zu bieten.","relevanz":"Das Projekt visualisierte das \"Was-wäre-wenn\": Eine Welt, in der Plakatwände nicht dem Meistbietenden gehören, sondern dem öffentlichen und kulturellen Interesse der Stadtgesellschaft dienen."},{"id":"pol-005","title":"Zivilgesellschaftliche 'Adblock'-Netzwerke blockieren jährlich hunderte Neu-Genehmigungen","category":"politics","impact_score":8,"year":2023,"source_type":"ngo","institution":"Adfree Cities / Subvertisers International","open_access":true,"file":"data/politics/pol-005.md","source_url":"https://adfreecities.org.uk/adblock","tags":[],"zusammenfassung":"Bürger wehren sich zunehmend erfolgreich gegen die Privatisierung des öffentlichen Raums durch Außenwerbung, indem sie Planungs- und Bauordnungen strategisch nutzen.","kernbefund":"Lokale Graswurzel-Organisationen (wie das Adblock-Netzwerk im UK oder Résistance à l'Agression Publicitaire in Frankreich) überwachen systematisch städtische Bauportale auf neue Anträge für DOOH-Screens und Plakatwände. Durch die massenhafte Mobilisierung von Anwohnern und das Einreichen fundierter Einsprüche (basierend auf Verkehrssicherheit, Lichtimmission und Denkmalschutz) zwingen diese Gruppen die Werbekonzerne regelmäßig dazu, Bauanträge zurückzuziehen, oder erreichen Ablehnungen durch die Stadtplanung.","relevanz":"Die Werbeindustrie stößt nicht mehr auf passive Akzeptanz, sondern auf organisierten, informierten und juristisch wirksamen demokratischen Widerstand aus der Zivilgesellschaft."},{"id":"pol-006","title":"Gesetzesentwürfe aus der Zivilgesellschaft: Die Initiative 'Berlin Werbefrei'","category":"politics","impact_score":9,"year":2018,"source_type":"ngo","institution":"Berlin Werbefrei e.V.","open_access":true,"file":"data/politics/pol-006.md","source_url":"https://berlin-werbefrei.de","tags":[],"zusammenfassung":"Die Kommerzialisierung des öffentlichen Raums stößt in Deutschland auf massiven demokratischen Widerstand, der sich bis in formelle Gesetzgebungsverfahren manifestiert.","kernbefund":"Die Bürgerinitiative \"Berlin Werbefrei\" sammelte in der ersten Stufe eines Volksbegehrens über 36.000 gültige Unterschriften, um einen eigenen, knallharten Gesetzesentwurf in das Berliner Abgeordnetenhaus einzubringen. Der Entwurf sieht vor, Produkt- und Konsumwerbung im öffentlichen Raum Berlins radikal zu verbieten. Erlaubt bleiben sollen lediglich Werbung an der Stätte der Leistung (z.B. das Schild über einem Bäcker) sowie Veranstaltungsankündigungen und gemeinnützige Informationen.","relevanz":"Diese Initiative beweist, dass eine starke, wahlberechtigte Zivilgesellschaft den ständigen visuellen Konsumdruck ablehnt. Außenwerbung wird zunehmend nicht mehr als harmlose Dekoration, sondern als psychologische Übergriffigkeit in den öffentlichen Raum wahrgenommen."},{"id":"reg-015","title":"Das französische Klimagesetz (Loi Climat) verbietet fossile Werbung und stärkt lokale DOOH-Verbote","category":"regulation","impact_score":9,"year":2022,"source_type":"government","institution":"Gouvernement de la République française","open_access":true,"file":"data/regulation/reg-015.md","source_url":"https://www.legifrance.gouv.fr","tags":[],"zusammenfassung":"Die französische Regierung hat auf nationaler Ebene historische Klima- und Werbegesetze erlassen, die direkt in die Geschäftsmodelle von OOH und DOOH eingreifen.","kernbefund":"Das im August 2022 in Kraft getretene \"Loi Climat et Résilience\" (Klima- und Resilienzgesetz) verbietet landesweit Werbung für fossile Energien (Gas, Kohle, Öl). Darüber hinaus gibt dieses Gesetz den Bürgermeistern und lokalen Kommunen (\"Maires\") nun offiziell die juristische Exekutivgewalt (Pouvoir de Police), digitale und leuchtende Werbetafeln auf ihrem Stadtgebiet durch lokale Dekrete rigoros einzuschränken oder komplett abzubauen. Vorher lag diese Entscheidungskompetenz oft auf unsicheren, national-regionalen Zwischenebenen.","relevanz":"Dies ist einer der stärksten legislativen Eingriffe in der EU. Die Werbung für klimaschädliche Produkte wird auf eine Stufe mit Tabakwerbung gestellt, und die Entscheidungsgewalt über digitale Lichtverschmutzung wird den Städten formell zurückgegeben."},{"id":"env-011","title":"Digitale Screens kollidieren in Deutschland mit den strengen Vorgaben zum Insekten- und Immissionsschutz","category":"environment","impact_score":8,"year":2021,"source_type":"government","institution":"Länderarbeitsgemeinschaft für Immissionsschutz / Umweltbundesamt","open_access":true,"file":"data/environment/env-011.md","source_url":"https://www.umweltbundesamt.de/themen/lichtverschmutzung","tags":[],"zusammenfassung":"Die Ausweitung von Digital Out-of-Home (DOOH) stößt in Deutschland zunehmend an harte Grenzen des nationalen Umwelt- und Naturschutzrechts.","kernbefund":"In Deutschland regelt die Lichtimmissionsrichtlinie (LAI) basierend auf dem Bundes-Immissionsschutzgesetz (BImSchG) strikte Grenzwerte für schädliche Umwelteinwirkungen durch Licht. DOOH-Screens, die bis zu 10.000 Nits Helligkeit erreichen können, überschreiten häufig diese Toleranzwerte, was Blendwirkung für den Verkehr und \"Raumaufhellung\" in Schlafzimmern angeht. Zudem verbietet das neue deutsche Insektenschutzgesetz (und Änderungen im Bundesnaturschutzgesetz BNatSchG) die Errichtung von Beleuchtungsanlagen in bestimmten Naturschutzgebieten und fordert massiv reduzierte Lichtemissionen in der Nacht, da künstliches LED-Licht (insbesondere im blauen Spektrum von DOOH) nachtaktive Insektenpopulationen dezimiert (Staubsauger-Effekt).","relevanz":"Die Werbeindustrie gerät massiv unter juristischen Druck durch den Umweltschutz. DOOH ist aus Sicht des Immissionsschutzes eine signifikante, oft unzulässige Umweltbelastung."},{"id":"priv-002","title":"Der 'Path-to-Purchase' Abgleich: Passives Tracking von Mobile-IDs durch DOOH-Stelen","category":"privacy","impact_score":9,"year":2022,"source_type":"ngo","institution":"Big Brother Watch / EFF","open_access":true,"file":"data/privacy/priv-002.md","source_url":"https://bigbrotherwatch.org.uk/campaigns/stop-facial-recognition/","tags":[],"zusammenfassung":"Die Verknüpfung von physischen Werbestandorten mit digitalen Identitätsmerkmalen ermöglicht ein lückenloses Tracking von Bürgern im öffentlichen Raum.","kernbefund":"Moderne DOOH-Stelen (Digital-Out-of-Home) nutzen häufig WLAN- und Bluetooth-Sensoren, um passiv die eindeutigen MAC-Adressen oder mobilen Werbe-IDs von vorbeigehenden Passanten zu erfassen. Diese Daten werden mit Standortdaten aus Apps und Drittanbietern abgeglichen, um den sogenannten \"Path-to-Purchase\" zu messen: Es wird getrackt, ob eine Person, die an einem Plakat vorbeigegangen ist, später den beworbenen Laden betritt oder das Produkt online sucht. NGOs wie Big Brother Watch kritisieren, dass dieser Abgleich ohne informierte Zustimmung der Bürger erfolgt und den öffentlichen Raum in ein privates Überwachungsnetzwerk verwandelt.","relevanz":"DOOH ist nicht mehr nur eine Anzeige, sondern ein aktiver Sensor im Überwachungskapitalismus. Die Anonymität im Stadtraum wird durch die technologische Aufrüstung der Werbeinfrastruktur systematisch abgeschafft."},{"id":"health-011","title":"Störung des zirkadianen Rhythmus durch hochintensives blaues LED-Licht von DOOH-Screens","category":"health","impact_score":8,"year":2016,"source_type":"peer-reviewed","institution":"American Medical Association (AMA) / NIH","open_access":true,"file":"data/health/health-011.md","source_url":"https://www.ama-assn.org","tags":[],"zusammenfassung":"Die nächtliche Beleuchtung durch digitale Werbeplakate greift direkt in die hormonelle Steuerung des menschlichen Schlaf-Wach-Rhythmus ein.","kernbefund":"Digitale Werbebildschirme nutzen LEDs mit oft sehr hohen Farbtemperaturen (über 6500 Kelvin), die einen hohen Anteil an blauem Licht aufweisen. Dieses kurzwellige Licht unterdrückt die Ausschüttung von Melatonin in der Zirbeldrüse – ein Hormon, das für den Schlaf und die Zellregeneration essenziell ist. Bewohner in urbanen Gebieten, deren Fenster durch DOOH-Screens aufgehellt werden, leiden unter einer chronischen Verschiebung ihres zirkadianen Rhythmus. Die American Medical Association (AMA) warnt vor den langfristigen Folgen wie Schlafstörungen, Stoffwechselerkrankungen und einem erhöhten Risiko für bestimmte Krebserkrankungen durch künstliches Licht bei Nacht (ALAN).","relevanz":"DOOH-Betreiber argumentieren oft mit der Helligkeit pro Fläche, ignorieren aber die biologische Potenz der Farbtemperatur. Die nächtliche Emission von blauem Licht ist ein massiver Eingriff in die körperliche Integrität der Anwohner."},{"id":"env-013","title":"Der versteckte E-Waste-Zyklus: Kurze Lebensdauer und Ressourcenverbrauch von DOOH-Hardware","category":"environment","impact_score":9,"year":2021,"source_type":"peer-reviewed","institution":"Environmental Science & Technology Reports","open_access":true,"file":"data/environment/env-013.md","source_url":"https://pubs.acs.org/journal/estlcu","tags":[],"zusammenfassung":"Die \"Digitalisierung\" der Außenwerbung erzeugt enorme Mengen an schwer recycelbarem Elektroschrott und verbraucht kritische Rohstoffe.","kernbefund":"Im Gegensatz zu analogen Plakatwänden, die Jahrzehnte halten können, haben digitale LED-Screens eine kurze technische und wirtschaftliche Lebensdauer von oft nur 5 bis 8 Jahren. Der schnelle technologische Fortschritt und die Degradation der LEDs führen zu häufigen \"Hardware-Upgrades\". Dies erzeugt tonnenweise Elektroschrott, der seltene Erden, Blei und Cadmium enthält. Studien zeigen, dass das Recycling dieser komplexen elektronischen Bauteile extrem energieaufwendig ist und die Entsorgung oft in Ländern des Globalen Südens unter prekären Bedingungen erfolgt, was zu schweren Boden- und Wasserverunreinigungen führt.","relevanz":"Die Branche bewirbt die \"papierlose\" Zukunft als ökologisch, verschweigt aber die massive Umweltbelastung durch die Produktion und Entsorgung der Hardware. DOOH ist eine Wegwerf-Technologie im öffentlichen Raum."},{"id":"urban-009","title":"Physische Invasion des Privatraums durch Licht-Immission (Light Trespass)","category":"urban","impact_score":8,"year":2022,"source_type":"ngo","institution":"International Dark-Sky Association (IDA)","open_access":true,"file":"data/urban/urban-009.md","source_url":"https://darksky.org","tags":[],"zusammenfassung":"Digital Out-of-Home-Anlagen verletzen die Grenzen des Privatraums, indem sie unaufgefordert Licht in Wohnungen und Schlafzimmer emittieren.","kernbefund":"In der Stadtplanung wird das Phänomen des \"Light Trespass\" (Lichteinbruch) als eine Form der räumlichen Grenzverletzung gewertet. DOOH-Screens strahlen Licht oft ungerichtet ab, wodurch Fassaden und Innenräume von Anwohnern taghell erleuchtet werden. Da das Licht kommerziell und oft dynamisch (wechselnde Bilder, Blinken) ist, lässt es sich psychologisch schwerer ignorieren als statisches Straßenlicht. Betroffene berichten von einer massiven Minderung der Lebensqualität und dem Gefühl, in den eigenen vier Wänden dem Werbedruck nicht mehr entkommen zu können.","relevanz":"Werbekonzerne privatisieren die Aufmerksamkeit der Bürger, indem sie deren Privaträume visuell besetzen. Das Recht auf Dunkelheit und Rückzug im eigenen Heim wird dem kommerziellen Interesse untergeordnet."},{"id":"psych-008","title":"Screens, die zurückschauen: Echtzeit-Analyse von Passanten durch Anonymized Video Analytics (AVA)","category":"psychology","impact_score":9,"year":2021,"source_type":"ngo","institution":"Privacy International","open_access":true,"file":"data/psychology/psych-008.md","source_url":"https://privacyinternational.org/examples/surveillance-billboards","tags":[],"zusammenfassung":"Moderne Werbebildschirme sind mit Sensoren ausgestattet, die das Publikum in Echtzeit scannen, um Werbebotschaften psychologisch zu optimieren.","kernbefund":"Immer mehr DOOH-Anlagen integrieren Kamerasysteme, die mittels \"Anonymized Video Analytics\" (AVA) die Gesichter von Passanten erfassen. Die Technologie analysiert in Sekundenbruchteilen Alter, Geschlecht, Blickdauer und teilweise sogar die emotionale Reaktion (Stimmung) auf die angezeigte Werbung. Obwohl die Industrie behauptet, keine Bilder zu speichern, erfolgt die Analyse ohne Wissen oder Einwilligung der Passanten. Dieses \"Eye-Tracking\" im öffentlichen Raum wird genutzt, um die Wirksamkeit von Manipulationstechniken zu perfektionieren und die kognitive Wehrhaftigkeit der Bürger gezielt zu unterwandern.","relevanz":"Der öffentliche Raum wird zum Labor der Werbeindustrie. Passanten werden unfreiwillig zu Probanden in einem massenpsychologischen Experiment, bei dem jede Regung biometrisch erfasst und kommerziell verwertet wird."},{"id":"equity-004","title":"Hardware-Dumping: Export veralteter und energieintensiver Werbeanlagen in den Globalen Süden","category":"equity","impact_score":9,"year":2022,"source_type":"ngo","institution":"Basel Action Network (BAN) / E-Waste Monitor","open_access":true,"file":"data/equity/equity-004.md","source_url":"https://www.ban.org","tags":[],"zusammenfassung":"Die Modernisierung der Werbeinfrastruktur im Globalen Norden führt zum Export ökologisch schädlicher und ineffizienter Hardware in Entwicklungsländer.","kernbefund":"Wenn Werbekonzerne in Europa oder Nordamerika ihre Bestände auf die neueste, energieeffizientere LED-Generation umstellen, werden die alten, stromfressenden und oft instandhaltungsanfälligen Panele häufig als \"Gebrauchthardware\" in Länder des Globalen Südens exportiert. Dort tragen diese Anlagen zur Überlastung lokaler Stromnetze bei und landen am Ende ihres Lebenszyklus auf informellen Mülldeponien. Dieses Phänomen wird als \"Öko-Kolonialismus\" kritisiert: Der Globale Norden \"reinigt\" seine städtische Bilanz, während der ökologische und energetische Schaden in Länder mit schwächeren Umweltgesetzen verschoben wird.","relevanz":"Nachhaltigkeitsberichte der Branche sind oft geografisch selektiv. Der globale Fußabdruck der Hardware wird verschleiert, indem der schädliche Teil der Wertschöpfungskette (Entsorgung/Dumping) externalisiert wird."},{"id":"eco-007","title":"Die kommunale Schuldenfalle: Langfristige Abhängigkeit durch Werbefinanzierung städtischer Infrastruktur","category":"economy","impact_score":8,"year":2022,"source_type":"ngo","institution":"Corporate Europe Observatory / Municipal Finance Studies","open_access":true,"file":"data/economy/eco-007.md","source_url":"https://corporateeurope.org","tags":[],"zusammenfassung":"Langfristige Werbeverträge binden Kommunen an private Konzerne und schränken die demokratische Gestaltungshoheit über den öffentlichen Raum ein.","kernbefund":"Städte schließen oft Verträge über 15 bis 20 Jahre mit Werbekonzernen ab, bei denen die Bereitstellung von Wartehäuschen oder Toiletten gegen exklusive Werberechte getauscht wird. Diese Public-Private Partnerships (PPP) entwickeln sich oft zu Schuldenfallen: Die Kommunen verlieren die Kontrolle über das Stadtbild und können neue ökologische oder soziale Standards (z.B. Werbeverbote für Junk-Food) oft nur gegen massive Entschädigungszahlungen an die Konzerne durchsetzen. Zudem priorisieren die Standorte der Infrastruktur oft die Werbesichtbarkeit und nicht den Bedarf der Bürger, was zu einer Vernachlässigung von Außenbezirken führt.","relevanz":"Die vermeintliche \"kostenlose\" Infrastruktur wird teuer erkauft durch den Verlust an politischem Handlungsspielraum und die langfristige Privatisierung des öffentlichen Raums."},{"id":"safety-004","title":"Signal-Maskierung: Beeinträchtigung der Sichtbarkeit von Notfall- und Verkehrssignalen durch DOOH","category":"safety","impact_score":9,"year":2021,"source_type":"peer-reviewed","institution":"Traffic Safety Research Journal","open_access":true,"file":"data/safety/safety-004.md","source_url":"https://www.trafficsafetyresearch.com","tags":[],"zusammenfassung":"Die extreme Leuchtdichte digitaler Werbetafeln kann die Wahrnehmung lebenswichtiger Verkehrssignale und Rettungsfahrzeuge behindern.","kernbefund":"In der optischen Wahrnehmungspsychologie ist bekannt, dass stärkere Lichtreize schwächere Reize maskieren können. Hochleistungs-LED-Screens, die in Sichtlinie zu Ampelanlagen oder Verkehrsschildern platziert sind, können deren Signalwirkung insbesondere bei Nacht oder schlechter Witterung (Regen, Nebel) drastisch reduzieren. Zudem kann die enorme Helligkeit und Farbdynamik von DOOH-Anlagen dazu führen, dass die blinkenden Warnlichter von herannahenden Rettungsfahrzeugen (Blaulicht) im visuellen Rauschen der Umgebung untergehen oder zu spät wahrgenommen werden, was die Reaktionszeit von Verkehrsteilnehmern gefährlich verlängert.","relevanz":"Außenwerbung ist ein Sicherheitsrisiko, wenn sie mit der offiziellen Sicherheitsinfrastruktur um die visuelle Dominanz konkurriert. Die Priorisierung von Werbebotschaften gefährdet im Zweifelsfall Menschenleben."},{"id":"pol-007","title":"Verdrängung lokaler Kultur: Die Kommerzialisierung von Flächen für Community-Art und Murals","category":"politics","impact_score":7,"year":2022,"source_type":"ngo","institution":"Urban Sociology Review / Culture Action Europe","open_access":true,"file":"data/politics/pol-007.md","source_url":"https://cultureactioneurope.org","tags":[],"zusammenfassung":"Die aggressive Expansion kommerzieller Werbeflächen entzieht der lokalen Kunstszene und Bürgerbewegungen den physischen Raum für nicht-kommerzielle Ausdrucksformen.","kernbefund":"In vielen Metropolen werden ehemals freie oder für Community-Murals (Wandgemälde) genutzte Fassaden durch großformatige Werbeplanen oder digitale Screens besetzt. Dieser Prozess führt zu einer kulturellen Homogenisierung: Anstelle von lokal verwurzelter, politischer oder ästhetischer Kunst treten austauschbare globale Markenbotschaften. Soziologische Studien zeigen, dass dies die Identifikation der Bewohner mit ihrem Viertel schwächt, da der öffentliche Raum nicht mehr als Ort der Mitgestaltung, sondern als reine Konsumzone wahrgenommen wird. Die \"Canvas\" der Stadt wird an den Meistbietenden verkauft, anstatt der lokalen Kultur als Bühne zu dienen.","relevanz":"Außenwerbung ist ein aktiver Verdrängungsfaktor für nicht-kommerzielle Kultur. Sie ersetzt Vielfalt durch Monotonie und Bürgerbeteiligung durch einseitige Beschallung."},{"id":"alt-004","title":"Der 'Nordische Minimalismus': Werbefreie Smart-City-Konzepte zur Förderung der Lebensqualität","category":"alternatives","impact_score":8,"year":2021,"source_type":"government","institution":"Nordic Council of Ministers / Urban Planning Case Studies","open_access":true,"file":"data/alternatives/alt-004.md","source_url":"https://www.norden.org","tags":[],"zusammenfassung":"Einige skandinavische Städte zeigen, dass moderne Stadtentwicklung (\"Smart City\") ohne die visuelle und psychologische Belastung durch Außenwerbung erfolgreicher ist.","kernbefund":"In verschiedenen Stadtentwicklungsprojekten in Skandinavien (z.B. in Stadtteilen von Oslo oder Stockholm) wird ein \"Human-Centric\"-Ansatz verfolgt, der die Reduktion von visuellem Rauschen priorisiert. Bei der Planung von vernetzter Infrastruktur (Smarte Lichtmasten, Informationskioske) wird bewusst auf die Integration von Werbedisplays verzichtet. Stattdessen werden diese Flächen für Echtzeit-Bürgerinformationen, Klimadaten oder schlichte Begrünung genutzt. Die Studien belegen, dass Bürger in diesen werbefreien Räumen ein höheres Sicherheitsgefühl, weniger Stress und eine stärkere soziale Kohäsion erleben, was die langfristige Attraktivität des Standorts steigert.","relevanz":"Das Beispiel beweist, dass \"Smart City\" nicht automatisch \"Werbestadt\" bedeuten muss. Eine technologisch fortschrittliche Stadt kann sich bewusst für visuelle Ruhe entscheiden, um das Wohlbefinden ihrer Bewohner ins Zentrum zu stellen."},{"id":"reg-016","title":"Amsterdam und Haarlem verbieten Werbung für Fleisch und fossile Produkte im öffentlichen Raum","category":"regulation","impact_score":9,"year":2024,"source_type":"government","institution":"The Guardian / City of Amsterdam","open_access":true,"file":"data/regulation/reg-016.md","source_url":"https://www.theguardian.com/world/2022/sep/06/haarlem-netherlands-bans-meat-adverts-public-spaces-climate-crisis","tags":[],"zusammenfassung":"Niederländische Städte nutzen ihre Kontrolle über den öffentlichen Raum, um den Konsum von klimaschädlichen Produkten aktiv zu reduzieren.","kernbefund":"Als erste Hauptstadt weltweit hat Amsterdam im Jahr 2026 ein Gesetz verabschiedet, das Werbung für Fleischprodukte sowie fossile Brennstoffe (Autos, Flüge, Öl) an städtischen Werbeflächen (Bushaltestellen, Bahnhöfe) verbietet. Haarlem war 2022 der Pionier dieser Bewegung. Ziel ist es, die Klimaziele der Städte zu unterstützen, indem die visuelle Normalisierung von Produkten mit hohem CO2-Fußabdruck beendet wird. Die Städte argumentieren, dass die Bereitstellung von öffentlichem Raum für die Promotion von Klimasündern im direkten Widerspruch zum öffentlichen Auftrag steht.","relevanz":"Dieses Verbot beweist, dass Kommunen das Recht haben, die *Inhalte* der Außenwerbung nach ethischen und ökologischen Kriterien zu filtern, um ihre Klimaschutzverpflichtungen einzuhalten."},{"id":"health-009","title":"Das Werbeverbot für Junk-Food in London verhindert geschätzt 95.000 Adipositas-Fälle","category":"health","impact_score":10,"year":2022,"source_type":"peer-reviewed","institution":"London School of Hygiene & Tropical Medicine (LSHTM)","open_access":true,"file":"data/health/health-009.md","source_url":"https://journals.plos.org/plosmedicine/article?id=10.1371/journal.pmed.1003915","tags":[],"zusammenfassung":"Wissenschaftliche Studien belegen den massiven positiven Effekt von Werbebeschränkungen auf die Volksgesundheit.","kernbefund":"Eine umfassende Studie der LSHTM und der University of Sheffield untersuchte das 2019 eingeführte Verbot von Werbung für Produkte mit hohem Fett-, Zucker- und Salzgehalt (HFSS) im Londoner Verkehrsnetz (TfL). Das Ergebnis: Das Verbot führte zu einer Reduktion der wöchentlichen Energieaufnahme aus HFSS-Produkten um durchschnittlich 6,7 % pro Haushalt. Dies entspricht einer langfristigen Vermeidung von geschätzt 94.867 Adipositas-Fällen und fast 3.000 Fällen von Typ-2-Diabetes in London. Zudem werden dem britischen Gesundheitssystem (NHS) dadurch Kosten in Höhe von über 200 Millionen Pfund erspart.","relevanz":"Dies ist einer der stärksten Beweise dafür, dass Außenwerbung keine bloße Information ist, sondern das Essverhalten einer Millionenstadt direkt beeinflusst. Werbeverbote sind eine hochwirksame Maßnahme der Präventivmedizin."},{"id":"reg-017","title":"Frankreich verbietet kommerzielle Großplakate in Gemeinden unter 10.000 Einwohnern","category":"regulation","impact_score":8,"year":2015,"source_type":"government","institution":"Gouvernement de la République française","open_access":true,"file":"data/regulation/reg-017.md","source_url":"https://www.legifrance.gouv.fr","tags":[],"zusammenfassung":"Das französische Umweltrecht schützt den ländlichen Raum und kleinere Kommunen aktiv vor der visuellen Überflutung durch kommerzielle Werbung.","kernbefund":"Im Rahmen einer umfassenden Reform des Werberechts hat Frankreich 2010 ein Gesetz verabschiedet, das seit Juli 2015 vollumfänglich gilt: In allen Gemeinden mit weniger als 10.000 Einwohnern (die nicht Teil einer größeren Metropolregion sind) ist kommerzielle Außenwerbung an großformatigen Plakatwänden grundsätzlich verboten. Erlaubt bleiben lediglich spezifische Hinweisschilder für lokale kulturelle Aktivitäten, regionale Produkte oder essenzielle Dienstleistungen. Bei Verstößen drohen den Werbebetreibern tägliche Bußgelder.","relevanz":"Das Gesetz belegt, dass der Erhalt der ästhetischen Integrität und Lebensqualität in kleineren Gemeinden ein schutzwürdiges Gut ist, das über den Verwertungsinteressen der Werbeindustrie steht."},{"id":"health-010","title":"Strenge gesetzliche Werbeverbote an Schulen zum Schutz von Minderjährigen vor Konsumdruck","category":"health","impact_score":9,"year":2023,"source_type":"government","institution":"Ministerium für Schule und Bildung NRW","open_access":true,"file":"data/health/health-010.md","source_url":"https://recht.nrw.de/lrgv/gesetz/01082005-schulgesetz-fuer-das-land-nordrhein-westfalen-schulgesetz-nrw-schulg","tags":[],"zusammenfassung":"In Deutschland ist die Schule als werbefreier Schutzraum gesetzlich verankert, um die pädagogische Integrität und die Unabhängigkeit der Schüler zu wahren.","kernbefund":"Beispielhaft regelt § 99 des Schulgesetzes NRW, dass Werbung, die nicht schulischen Zwecken dient, in der Schule grundsätzlich unzulässig ist. Dies umfasst sowohl das Verteilen von Material als auch das Anbringen von Plakaten auf dem Schulgelände. Ziel ist es, Minderjährige in einer sensiblen Entwicklungsphase vor dem Einfluss kommerzieller Akteure zu schützen und sicherzustellen, dass die Schule ein Ort der kritischen Reflexion und nicht des ungefilterten Konsums ist. Sponsoring ist nur unter strengsten Auflagen möglich, wobei die Werbewirkung \"deutlich hinter dem schulischen Nutzen zurücktreten\" muss.","relevanz":"Wenn der Staat Schulen als werbefreie Zonen schützt, stellt sich die ethische Frage, warum derselbe Schutz für Kinder im unmittelbaren Umfeld der Schule (an Bushaltestellen und Schulwegen) durch kommerzielle OOH-Anlagen systematisch untergraben wird."},{"id":"eco-006","title":"Das Konzept der 'Advertised Emissions': Außenwerbung als Treiber von Scope-3-Emissionen","category":"economy","impact_score":9,"year":2022,"source_type":"ngo","institution":"Purpose Disruptors / Badvertising","open_access":true,"file":"data/economy/eco-006.md","source_url":"https://www.purposedisruptors.org/advertised-emissions","tags":[],"zusammenfassung":"Die Klimaauswirkung der Werbeindustrie geht weit über den Stromverbrauch der Screens hinaus – sie liegt im induzierten Mehrkonsum CO2-intensiver Produkte.","kernbefund":"Berichte von Purpose Disruptors zeigen, dass Werbung die Treibhausgasemissionen der Bevölkerung massiv erhöht, indem sie den Absatz von klimaschädlichen Produkten (wie SUVs, Flugreisen oder Fast Food) künstlich steigert. Diese \"Advertised Emissions\" (beworbene Emissionen) machen einen erheblichen Teil des ökologischen Fußabdrucks einer Stadtgesellschaft aus. Schätzungen für den britischen Markt zeigen, dass die durch Werbung generierte zusätzliche Nachfrage die Emissionen um ca. 32 % erhöht. Außenwerbung wirkt hierbei als \"Choice Architect\", der klimaschädliche Lebensstile im öffentlichen Raum normalisiert.","relevanz":"Werbekonzerne, die sich als \"klimaneutral\" bezeichnen (indem sie nur den Strom ihrer Screens kompensieren), ignorieren den massiven Scope-3-Effekt der beworbenen Inhalte. Dies ist eine Form des systemischen Greenwashing."},{"id":"reg-018","title":"Städte nutzen 'Amenity'-Regeln, um die Konzentration digitaler Screens in benachteiligten Vierteln zu stoppen","category":"regulation","impact_score":7,"year":2021,"source_type":"government","institution":"Bristol City Council / Adblock Bristol","open_access":true,"file":"data/regulation/reg-018.md","source_url":"https://adblockbristol.org.uk/resources","tags":[],"zusammenfassung":"Das Planungsrecht bietet Städten Handhabe, die visuelle Überfrachtung (Clutter) und die damit verbundene Minderung der Lebensqualität in Wohnvierteln zu begrenzen.","kernbefund":"In Bristol (UK) hat der Stadtrat Richtlinien verschärft, die den Begriff der \"Amenity\" (Annehmlichkeit/Lebensqualität) im Planungsrecht interpretieren. Ziel ist es zu verhindern, dass digitale Werbescreens einseitig in Stadtteilen mit ohnehin geringerer Aufenthaltsqualität oder in einkommensschwachen Vierteln konzentriert werden. Die Stadt argumentiert, dass eine übermäßige Dichte an DOOH-Anlagen das Erscheinungsbild eines Viertels degradiert, Lichtverschmutzung für Anwohner schafft und das Recht auf einen werbefreien, ruhigen öffentlichen Raum verletzt.","relevanz":"Dies ist ein Instrument zur Durchsetzung von räumlicher Gerechtigkeit. Es bricht mit der Industriepraxis, einkommensschwache Viertel mit Billigwerbung zu fluten, während wohlhabende Viertel \"clean\" bleiben."},{"id":"env-012","title":"Lichtverschmutzung durch DOOH desorientiert ziehende Vögel über europäischen Städten","category":"environment","impact_score":8,"year":2021,"source_type":"ngo","institution":"European Biodiversity Research / DarkSky International","open_access":true,"file":"data/environment/env-012.md","source_url":"https://darksky.org","tags":[],"zusammenfassung":"Die extreme Helligkeit digitaler Werbeanlagen in der Nacht stört die biologischen Rhythmen und Migrationsrouten geschützter Vogelarten.","kernbefund":"Wissenschaftliche Studien in Europa zeigen, dass großformatige, helle LED-Screens (insbesondere solche mit hohem Blauanteil) in den Nachtstunden zu \"Skyglow\" beitragen, der ziehende Vögel desorientiert. Vögel werden von den Lichtquellen angezogen (Phototaxis), was zu tödlichen Kollisionen mit Gebäuden oder zur Erschöpfung durch unnötige Umwege führt. Da viele europäische Metropolen auf den Hauptzugrouten liegen, stellt die ungefilterte Lichtemission von DOOH eine direkte Bedrohung für die Biodiversität dar und konterkariert städtische Bemühungen zum Artenschutz.","relevanz":"DOOH ist keine \"saubere\" Technologie. Die ökologischen Kosten durch Artensterben und gestörte Ökosysteme werden in den Nachhaltigkeitsberichten der Werbekonzerne systematisch ausgeklammert."},{"id":"psych-009","title":"Werbung fördert Materialismus bei Kindern und zerstört intrinsische Werte langfristig","category":"psychology","impact_score":9,"year":2003,"source_type":"peer-reviewed","institution":"Journal of Advertising / American Academy of Advertising","open_access":false,"file":"data/psychology/psych-009.md","source_url":"https://www.tandfonline.com/doi/abs/10.1080/00913367.2003.10639127","tags":["children","materialism","values","advertising","psychology","long-term-effects"],"zusammenfassung":"Peer-reviewte Analyse der Langzeitfolgen von Werbeexposition auf Kinder: Werbung verankert materialistische Werthaltungen, die in direktem Widerspruch zu prosozialem Verhalten, intrinsischer Motivation und psychischer Resilienz stehen.","kernbefund":"Kinder, die intensiv Werbung ausgesetzt sind, entwickeln nachweislich stärkere materialistische Einstellungen — die Gleichsetzung von Besitz mit Glück, Status und Identität. Dies korreliert mit niedrigerem Selbstwertgefühl, erhöhter Unzufriedenheit und verminderter Lebenszufriedenheit im Erwachsenenalter. Außenwerbung im öffentlichen Raum ist als permanente, nicht zustimmungspflichtige Exposition besonders wirksam für diese Prägung.","relevanz":"Im Gegensatz zu TV-Werbung ist OOH/DOOH im öffentlichen Raum nicht abschaltbar — Kinder auf dem Schulweg, beim Spielen oder in der Stadt können sich dieser Exposition nicht entziehen. Die psychische Prägung durch materialistische Botschaften findet damit ohne elterliche Kontrolle statt."},{"id":"health-012","title":"Alkohol-Außenwerbung erhöht nachweislich den Alkoholkonsum bei Jugendlichen","category":"health","impact_score":9,"year":2007,"source_type":"peer-reviewed","institution":"Journal of Studies on Alcohol and Drugs","open_access":false,"file":"data/health/health-012.md","source_url":"https://www.jsad.com/doi/10.15288/jsad.2007.68.587","tags":["alcohol","outdoor-advertising","adolescents","youth","public-health","schools"],"zusammenfassung":"Peer-reviewte Längsschnittstudie, die den Zusammenhang zwischen der Dichte von Alkohol-Außenwerbung in der Nähe von Schulen und dem Alkoholkonsum sowie den Konsumabsichten von Jugendlichen untersucht.","kernbefund":"Jugendliche in Stadtteilen mit hoher Dichte an Alkohol-Außenwerbung zeigen signifikant höhere Absichten, Alkohol zu konsumieren, und berichten über höheren tatsächlichen Konsum. Alkohol-Außenwerbung in Schul- und Wohnnähe wirkt als unabhängiger Risikofaktor — stärker als TV-Werbung, da sie nicht vermeidbar ist.","relevanz":"Alkohol-Außenwerbung ist in Deutschland weitgehend legal und unreguliert. Die WHO hat Pflichtbeschränkungen für Alkohol-Marketing an öffentlichen Orten gefordert. Im Gegensatz zu TV-Werbung (nach 22 Uhr eingeschränkt) ist OOH rund um die Uhr sichtbar — auch für Kinder auf dem Schulweg."},{"id":"env-014","title":"Mikroplastik aus PVC-Werbebannern kontaminiert Böden und Gewässer in städtischen Räumen","category":"environment","impact_score":8,"year":2017,"source_type":"peer-reviewed","institution":"Environmental Chemistry Letters, Springer","open_access":false,"file":"data/environment/env-014.md","source_url":"https://link.springer.com/article/10.1007/s10311-016-0569-z","tags":["microplastics","pvc","environment","urban","pollution","stormwater","billboard"],"zusammenfassung":"PVC-Planenwerbestoffe — das Standardmaterial für Großflächenwerbung — verwittern durch UV-Strahlung und mechanischen Abrieb zu Mikroplastikpartikeln, die in Böden, Kanalisation und Gewässer gelangen. In urbanen Räumen mit hoher OOH-Werbedichte ist dieser Eintragspfad signifikant.","kernbefund":"PVC-Werbeplane (Standard-Werbematerial) enthält Weichmacher wie DEHP (endokrin wirksam) und Stabilisatoren wie Blei und Cadmium. Durch UV-Verwitterung entstehen Mikroplastikpartikel < 5mm, die in städtische Regenabflüsse gelangen. Städtischer Regenabfluss transportiert Mikroplastik direkt in Gewässer — Abwasserbehandlung filtert < 60% heraus.","relevanz":"In Deutschland werden Werbebanner alle 4 Wochen ausgetauscht (Kampagnenzyklus). Auch vor dem Austausch tragen bestehende Banner durch Verwitterung zur Mikroplastikbelastung bei. Das Problem wird durch steigende DOOH-Verbreitung (die statische Poster verdrängt) nur teilweise gelöst — DOOH-Hardware selbst enthält erhebliche Kunststoffmengen (Gehäuse, Kabel, Platinen)."},{"id":"priv-003","title":"Programmatisches DOOH-Targeting verstößt strukturell gegen DSGVO — keine wirksame Einwilligung möglich","category":"privacy","impact_score":9,"year":2020,"source_type":"government","institution":"European Data Protection Board (EDPB)","open_access":true,"file":"data/privacy/priv-003.md","source_url":"https://edpb.europa.eu/our-work-tools/our-documents/guidelines/guidelines-32019-processing-personal-data-through-video_en","tags":["gdpr","dsgvo","privacy","dooh","programmatic","facial-recognition","eu-law","edpb"],"zusammenfassung":"Der Europäische Datenschutzausschuss (EDPB) hat klargestellt, dass das Erfassen von Personenmerkmalen (Alter, Geschlecht, Emotionen) durch Kamerasysteme in öffentlichen Werbeanlagen ohne wirksame Einwilligung rechtswidrig ist. Das programmatische DOOH-Geschäftsmodell, das auf Audience-Measurement basiert, ist damit strukturell mit der DSGVO unvereinbar.","kernbefund":"DOOH-Screens nutzen Kamerasysteme zur anonymisierten Zählung und Klassifikation von Passanten (Anonymized Video Analytics / AVA). Der EDPB stellt fest: Selbst wenn keine biometrischen Templates gespeichert werden, ist die Verarbeitung von Gesichts- und Körpermerkmalen zur Zielgruppenanalyse eine Verarbeitung personenbezogener Daten gemäß Art. 4 DSGVO. Im öffentlichen Raum ist eine wirksame, informierte Einwilligung aller Betroffenen faktisch unmöglich.","relevanz":"Programmatische DOOH-Buchungsplattformen (z.B. Broadsign, Vistar Media, The Trade Desk) verkaufen \"Audience Targeting\" für Außenwerbung. Dies setzt de facto voraus, dass Passanten auf ihre demografischen Merkmale hin analysiert werden. Unternehmen, die programmatisches DOOH buchen, exponieren sich gegenüber erheblichem DSGVO-Haftungsrisiko — insbesondere nach den jüngsten Millionenbußen der EU-Datenschutzbehörden."},{"id":"reg-019","title":"Belgien verbietet als erstes Land weltweit Werbung für fossile Brennstoffe (2023)","category":"regulation","impact_score":9,"year":2023,"source_type":"government","institution":"The Guardian / Belgian Federal Government","open_access":true,"file":"data/regulation/reg-019.md","source_url":"https://www.theguardian.com/world/2023/jun/16/belgium-bans-fossil-fuel-advertising","tags":["belgium","fossil-fuels","advertising-ban","climate","regulation","dooh","ooh"],"zusammenfassung":"Belgien ist 2023 das erste Land weltweit, das Werbung für fossile Brennstoffe auf nationaler Ebene vollständig verboten hat — einschließlich aller Außenwerbeflächen (OOH/DOOH). Das Gesetz gilt als Blaupause für ähnliche Regulierung auf EU-Ebene.","kernbefund":"Das belgische Verbot umfasst alle Medien inkl. OOH/DOOH und gilt für Werbung, die den Konsum fossiler Brennstoffe (Erdöl, Erdgas, Kohle) fördert. Die belgische Wettbewerbsbehörde ist für die Durchsetzung zuständig. Das Gesetz folgte auf eine erfolgreiche Klage von NGOs gegen greenwashing-Werbung von Energiekonzernen. Frankreich hatte zuvor mit der Loi Climat (2022) fossile Werbung eingeschränkt — Belgien geht weiter.","relevanz":"Für DOOH-Netzbetreiber, die erhebliche Einnahmen aus der Energiebranche (Ölkonzerne, Gasinitiativen, Automobilhersteller) generieren, stellt das belgische Modell ein direktes Erlösrisiko dar, wenn weitere EU-Länder nachziehen. Deutschland diskutiert ähnliche Regelungen im Rahmen des Klimaschutzgesetzes."},{"id":"safety-005","title":"Digitale Werbetafeln erhöhen die Ablenkungsgefahr für Fußgänger und Radfahrer signifikant","category":"safety","impact_score":8,"year":2011,"source_type":"peer-reviewed","institution":"Traffic Injury Prevention, Taylor & Francis","open_access":false,"file":"data/safety/safety-005.md","source_url":"https://www.tandfonline.com/doi/abs/10.1080/15389588.2011.572034","tags":["pedestrian-safety","distraction","cycling","urban","dooh","traffic","cognitive-load"],"zusammenfassung":"Peer-reviewte Untersuchung der Ablenkungseffekte auf Fußgänger in städtischen Umgebungen. Digitale und bewegte Außenwerbung steigert die visuelle Ablenkung signifikant und erhöht das Unfallrisiko an Kreuzungen und Übergängen.","kernbefund":"Fußgänger und Radfahrer, die visuell ablenkenden Reizen ausgesetzt sind (Screens, bewegte Bildwechsel), zeigen messbar verzögerte Reaktionszeiten an Straßenübergängen, häufigeres Überqueren ohne Blickkontakt zum Verkehr und erhöhte Fehlerquoten bei der Situationsbeurteilung. Digitale Werbeformate mit hoher Lichtintensität und Bewegtbild (DOOH) sind wirksamer als statische Werbung in der Ablenkungswirkung.","relevanz":"Im Gegensatz zu Fahrerablenkung durch DOOH (breit dokumentiert) ist Fußgänger- und Radfahrerablenkung in der DOOH-Regulierung bisher kaum adressiert. In Städten mit hoher Fußgänger- und Raddichte (Berlin, Hamburg, Amsterdam) ist die Risikoexposition durch DOOH-Screens an Kreuzungen besonders relevant."},{"id":"culture-004","title":"UNESCO warnt: kommerzielle Außenwerbung bedroht visuelle Integrität von Weltkulturerbe-Stätten","category":"culture","impact_score":8,"year":2019,"source_type":"government","institution":"UNESCO World Heritage Centre","open_access":true,"file":"data/culture/culture-004.md","source_url":"https://whc.unesco.org/en/sustainabledevelopment/","tags":["unesco","heritage","culture","visual-integrity","outdoor-advertising","urban","tourism"],"zusammenfassung":"Die UNESCO hat in ihren Leitlinien für nachhaltiges Stadtmanagement explizit kommerzielle Außenwerbung als Bedrohung für die visuelle Integrität von Weltkulturerbe-Stätten identifiziert. Mehrere europäische Städte wurden aufgefordert, OOH-Werbung in Pufferzonen zu begrenzen.","kernbefund":"Kommerzielle Außenwerbung in historischen Innenstädten und UNESCO-Pufferzonen untergräbt die authentische visuelle Wahrnehmung von Kulturerbestätten. Die UNESCO definiert \"Visual Integrity\" als Schutzgut: Das Stadtbild soll die historische Bedeutung eines Ortes widerspiegeln — großflächige Werbung, insbesondere DOOH mit bewegten Inhalten und nächtlicher Beleuchtung, kollidiert direkt mit diesem Schutzanliegen.","relevanz":"Städte wie Paris, Prag, Wien und Florenz haben OOH-Werbebeschränkungen in historischen Kernzonen eingeführt, teilweise unter Druck der UNESCO. In Deutschland sind Nürnbergs Altstadt und Berlins Mitte als Pufferzonen von UNESCO-Stätten potenziell betroffen. Werbekonzessionen in diesen Bereichen unterliegen zunehmendem juristischen Druck."},{"id":"econ-008","title":"Geplante Obsoleszenz von DOOH-Hardware erzeugt Milliarden-Entsorgungskosten die Städte tragen","category":"economy","impact_score":8,"year":2020,"source_type":"government","institution":"United Nations University / ITU / ISWA","open_access":true,"file":"data/economy/econ-008.md","source_url":"https://ewastemonitor.info/gem-2020/","tags":["e-waste","hardware","dooh","obsolescence","economy","municipal-costs","un"],"zusammenfassung":"DOOH-Hardware (LED-Screens, Steuereinheiten, Stromversorgung) hat eine reale Lebensdauer von 5–7 Jahren, nach der die Hardware ersetzt werden muss. Die Entsorgungskosten für Elektroschrott aus kommerzieller Signage werden bisher größtenteils externalisiert — auf Kommunen, Steuerzahler und Entwicklungsländer.","kernbefund":"Der UN E-Waste Monitor 2020 dokumentiert, dass kommerzieller elektronischer Signage-Abfall einer der am stärksten wachsenden E-Waste-Ströme ist. DOOH-Hardware enthält Schadstoffe (Blei, Quecksilber in älteren LEDs, Indium), für deren fachgerechte Entsorgung keine ausreichenden Rücknahmesysteme existieren. Städte und Kommunen tragen die Folgekosten entsorgter oder illegal im öffentlichen Raum zurückgelassener Werbeanlagen.","relevanz":"Investoren in DOOH-Infrastruktur müssen die Entsorgungskosten am Ende des Hardwarelebenszyklus einkalkulieren. In Städten mit strikten Werbeverboten (São Paulo, Grenoble) entstanden erhebliche Demontage- und Entsorgungskosten. Das EU-Lieferkettensorgfaltspflichtengesetz (CSDDD) könnte zukünftig DOOH-Betreiber zur Verantwortung für die gesamte Hardware-Lebenszykluswirkung verpflichten."},{"id":"pol-008","title":"Berlin verkauft Werberechte im öffentlichen Raum für 350 Mio. Euro — 20.643 Werbeflächen in einer Stadt","category":"politics","impact_score":9,"year":2018,"source_type":"government","institution":"Der Tagesspiegel","open_access":true,"file":"data/politics/pol-008.md","source_url":"https://www.tagesspiegel.de/berlin/berliner-senat-vergibt-rechte-fuer-aussenwerbung-einnahmen-des-landes-durch-werbung-steigen-signifikant/20834244.html","tags":["berlin","stadtvertrag","wall","jcdecaux","ströer","öffentlicher-raum","privatisierung","350-millionen","werberechte","exklusiv"],"zusammenfassung":"Berlin hat 2018 seine Werberechte im öffentlichen Straßenland neu vergeben: Für die nächsten 15 Jahre (ab 2019) kassiert das Land 350 Millionen Euro von Werbekonzernen. Berlin ist die am stärksten kommerzialisierte Außenwerbungsstadt Deutschlands — 18,5 % der gesamten deutschen OOH-Werbeeinnahmen fließen durch eine einzige Stadt.","kernbefund":"Berlin verfügt über **20.643 Werbeflächen**, die jährlich **272 Millionen Euro** Poster-Umsatz generieren. Das entspricht 18,5 % aller deutschen Außenwerbungseinnahmen. Die Vergabe erfolgte in Losen an Wall/JCDecaux (169 großformatige Leuchttafeln + 883 Schaukästen), ILG-Außenwerbung (2.500 Litfaßsäulen), Mediateam Stadtservice (4.100 Plakatstellen) und Ströer (430 Uhrenstandorte). Vertragslaufzeiten: 10–15 Jahre.\n\nDas vorherige Modell \"Infrastruktur gegen Werberechte\" (Wall wartete Toiletten und Brunnen im Tausch gegen Flächen) wurde durch Direktzahlungen ersetzt — mit der Konsequenz, dass der Senat nun für diese Infrastruktur selbst aufkommen muss.","relevanz":"Exklusivverträge über 10–15 Jahre mit Konzernen wie JCDecaux/Wall und Ströer bedeuten: Demokratisch gewählte Stadträte können für diese Zeiträume weder die Anzahl der Werbeflächen reduzieren, noch Verbote für bestimmte Produktkategorien durchsetzen, noch die Expansion auf digitale Screens stoppen — ohne Vertragsstrafen zu riskieren. Der öffentliche Raum ist auf 15 Jahre kommerziell blockiert."},{"id":"pol-009","title":"Ströer-Buchungssystem als Kanal für 3 Mio. Euro illegale AfD-Wahlkampfspenden — Konzern verweigert Auskunft","category":"politics","impact_score":9,"year":2021,"source_type":"ngo","institution":"CORRECTIV / ZDF Frontal / Der Spiegel","open_access":true,"file":"data/politics/pol-009.md","source_url":"https://correctiv.org/top-stories/2021/09/15/afd-wahlkampf-werbung-millionenauftraege-anonyme-spender-spendenaffaere/","tags":["ströer","afd","parteispenden","correctiv","political-advertising","anonyme-spenden","wahlkampf","deutschland","lobbyismus"],"zusammenfassung":"Investigativrecherche von CORRECTIV, ZDF Frontal und Spiegel: Zwischen 2016 und 2018 wurden über Ströers Buchungssystem mehr als 9.400 Großplakate für die AfD in ca. 70 deutschen Städten gebucht — bezahlt von anonymen Spendern für über 3 Millionen Euro. Die AfD war im Buchungssystem als \"Direktkunde\" eingetragen. Ströer ließ den Fragenkatalog unbeantwortet.","kernbefund":"Die Recherche dokumentiert: **über 3 Millionen Euro** anonyme Wahlkampfhilfe für die AfD über Ströer-Flächen, davon 1,9 Mio. Euro zur Bundestagswahl 2017 (ca. 4.900 Plakate), 521.000 Euro NRW-Landtagswahl, 221.000 Euro Baden-Württemberg. Parteirechtlerin Sophie Schönberger: *\"Wir haben jetzt den Beweis, dass die Kampagne zumindest beim Plakatproduzenten koordiniert wurde\"* — mögliche illegale Parteispendenstruktur. Ströer verstand sich als \"neutraler Dienstleister\" und verweigerte Stellungnahmen.","relevanz":"Ströer betreibt Werbeflächen in über 1.200 deutschen Städten auf Basis kommunaler Exklusivverträge. Als de-facto-Monopolist für Außenwerbung in vielen Kommunen kontrolliert der Konzern, welche politischen Inhalte im öffentlichen Raum sichtbar sind — ohne parlamentarische Kontrolle oder Transparenzpflichten. Das Unternehmen besitzt zudem Statista (Datendienst) und t-online (Nachrichtenportal), was seine Meinungsmacht über die physische Werbeinfrastruktur hinaus ausdehnt."},{"id":"pol-010","title":"Hannover: Ströer verdreifacht Werbeinfrastruktur in 7 Jahren — Stadt verweigert Auskunft über Vertragsdetails","category":"politics","impact_score":8,"year":2021,"source_type":"ngo","institution":"freiheitsfoo.de (Bürgerrechtsblog)","open_access":true,"file":"data/politics/pol-010.md","source_url":"https://freiheitsfoo.de/2021/01/20/hannover-in-der-hand-von-stroeer/","tags":["hannover","ströer","stadtvertrag","intransparenz","öffentlicher-raum","privatisierung","kommunen","dsm"],"zusammenfassung":"Dokumentation der schleichenden Kommerzialisierung des öffentlichen Raums in Hannover durch Ströer (Tochter DSM — Deutsche Städte Medien GmbH): Zwischen 2014 und 2021 hat Ströer seine Werbeinfrastruktur in der Stadt verdreifacht. Die Stadt verweigert Auskunft über Vertragsdetails, da angeblich die Unternehmen selbst kommunizieren sollen.","kernbefund":"Hannovers Ströer-Präsenz 2021 (laut Recherche): **90 City-Star-Säulen, 1.200 Großflächenplakate, 350 Mega-Light-Installationen** (Wachstum von 70 auf 210 = ×3 seit 2014), **2.200 City-Light-Postkästen, 11 LED-Billboards, 200 Uhrenstandorte, 350 klassische Litfaßsäulen**. Ursprung: 2009 erhielt DSM die Genehmigung für 7 City-Star-Systeme im Tausch gegen kostenlose Wahlplakatflächen an 45 Standorten. Aus diesen 7 wurden über 90.\n\nAuf Anfrage nach Vertragsdetails antwortete der städtische Pressesprecher: *\"Unternehmen sollten ihre eigenen Pläne kommunizieren.\"*","relevanz":"Das Hannover-Muster ist exemplarisch für Deutschland: Kleiner Anfangsvertrag → schleichende Ausweitung → Monopolstellung → intransparente Vertragskonditionen → demokratisch unkontrollierbare Expansion. Kommunen verlieren sukzessive die Kontrolle darüber, wie ihr öffentlicher Raum kommerziell genutzt wird, weil Vertragsdetails als Geschäftsgeheimnisse geschützt sind."},{"id":"reg-020","title":"JCDecaux-CEO: 'Wir wissen, wie man mit Entscheidungsträgern umgeht' — Konzern offen über politischen Einfluss","category":"regulation","impact_score":8,"year":2012,"source_type":"ngo","institution":"Der Tagesspiegel","open_access":true,"file":"data/regulation/reg-020.md","source_url":"https://www.tagesspiegel.de/wirtschaft/wir-wissen-wie-man-mit-entscheidungstragern-umgeht-3779758.html","tags":["jcdecaux","lobbying","entscheidungsträger","stadtverträge","exklusiv","öffentlicher-raum","demokratie","tagesspiegel"],"zusammenfassung":"Tagesspiegel-Interview mit dem JCDecaux-Chef: Der Geschäftsführer des weltgrößten Außenwerbers gibt offen zu, dass der Konzern gezielt Netzwerke zu politischen Entscheidungsträgern in Städten pflegt, um Werberechtsverträge zu sichern. Dies ist die strukturelle Grundlage des \"Stadtmöbel\"-Geschäftsmodells.","kernbefund":"Das Geschäftsmodell von JCDecaux basiert explizit auf dem Aufbau von Beziehungen zu politischen Entscheidungsträgern in Kommunen, die über die Vergabe von Werberechten entscheiden. Der CEO: *\"Wir wissen, wie man mit Entscheidungsträgern umgeht.\"* JCDecaux hält in Köln einen 15-jährigen Exklusivvertrag für 1.550 Fahrgastunterstände und 350 Stadtinformationsanlagen. In Berlin hielt JCDecaux/Wall über Jahrzehnte den dominanten Stadtmöbelvertrag. Karlsruhe verlängerte seine Werberechtsverträge ebenfalls mit Wall/JCDecaux.","relevanz":"Das \"Stadtmöbel\"-Modell ist kein Service-Angebot — es ist eine politische Lobbystrategie: Kommunen erhalten Infrastruktur (Wartehäuschen, Uhren, Toiletten), im Gegenzug vergeben sie exklusive Werberechte auf 10–20 Jahre, die dem Konzern de-facto-Kontrolle über den öffentlichen Raum geben. Kein Gemeinderat kann in dieser Zeit Werbeverbote beschließen, ohne Vertragsstrafen zu riskieren."},{"id":"pol-011","title":"Hamburg verkauft öffentlichen Raum für €508M: JCDecaux und Ströer teilen Exklusivvertrag","category":"politics","impact_score":9,"year":2023,"source_type":"government","file":"data/politics/pol-011.md","institution":"Transparenzportal Hamburg / Hamburgische Bürgerschaft","source_url":"https://suche.transparenz.hamburg.de/dataset/jcdecaux-deutschland-gmbh-vertrag-werbung-an-stadtinformationsanlagen-und-fahrgastunterstaenden","tags":["hamburg","jcdecaux","ströer","stadtvertrag","508-millionen","öffentlicher-raum","transparenz","exklusiv","werberechte"],"zusammenfassung":"Hamburg hat nach europaweiter Ausschreibung 2007/2009 seine Werberechte für den öffentlichen Raum für 508 Millionen Euro an JCDecaux und Ströer vergeben. JCDecaux erhielt ca. 2.150 Fahrgastunterstände und 350 Stadtinformationsanlagen (2009–2024). Die Verträge sind im Hamburgischen Transparenzportal öffentlich einsehbar — eine der wenigen deutschen Städte, die Vertragsdetails veröffentlicht.","kernbefund":"Hamburg garantierte Werbekonzernen im Tausch für Stadtmöblierung **508 Millionen Euro** Werbeeinnahmen über die Vertragslaufzeit. Obwohl vertraglich vereinbart war, dass Werbeanlagen in Fahrgastunterstände integriert werden, überschwemmten freistehende Werbesysteme das Stadtbild — an fast jeder Kreuzung in prominenter Lage. Der Hamburgische Transparenzportal veröffentlicht die Vertragsunterlagen beider Lose (JCDecaux Los 1: Stadtinformationsanlagen; JCDecaux Los 2: 18/1-Großwerbeanlagen).","relevanz":"Hamburg ist einer der wenigen Fälle in Deutschland, wo Vertragsdetails öffentlich zugänglich sind. Die 508-Millionen-Euro-Garantie zeigt: Städte vergeben de facto Monopolrechte auf ihren öffentlichen Raum gegen Einnahmen. In der Laufzeit (15 Jahre) können keine Werbeverbote für bestimmte Produktkategorien (z.B. Fossile, Alkohol, Junkfood) erlassen werden, ohne Vertragsstrafen zu riskieren. Demokratische Stadtpolitik wird durch kommerzielle Vertragslogik ausgehebelt."},{"id":"pol-012","title":"Hedgefonds Muddy Waters wirft Ströer IFRS-Buchhaltungsbetrug vor — Aktie bricht in 45 Minuten um 25% ein","category":"politics","impact_score":8,"year":2016,"source_type":"ngo","file":"data/politics/pol-012.md","institution":"Muddy Waters Research","source_url":"https://muddywatersresearch.com/research/sax/mw-is-short-stroeer/","tags":["ströer","muddy-waters","ifrs","bilanzierung","short-attack","finanzskandal","mdax","buchhaltung"],"zusammenfassung":"Im April 2016 veröffentlichte der US-amerikanische Shortseller Muddy Waters Research (bekannt für Aufdeckung von Bilanzskandalen bei chinesischen Firmen) einen Bericht, der Ströer SE & Co. KGaA schwerwiegender IFRS-Verstöße bezichtigt. Die Ströer-Aktie verlor innerhalb von 45 Minuten nach Veröffentlichung über 25 % ihres Wertes (von 52 € auf unter 35 €).","kernbefund":"Muddy Waters behauptete, Ströers ausgewiesenes organisches Wachstum, EBITDA, operativer Cashflow und freier Cashflow seien **erheblich niedriger als berichtet** und verstießen gegen IFRS-Rechnungslegungsstandards — was den falschen Eindruck erwecke, das Unternehmen finanziere sich aus eigenen Mitteln. Konkret: Digitale organische Wachstumsraten seien manipuliert dargestellt. Ströer wies alle Vorwürfe zurück; die Staatsanwaltschaft Frankfurt ermittelte anschließend gegen Muddy Waters wegen möglicher Marktmanipulation. Die WirtschaftsWoche berichtete 2021 erneut über \"merkwürdiges Finanzgebaren\" des Konzerns.","relevanz":"Ströer betreibt als größter deutscher Außenwerber kommunale Exklusivverträge in über 1.200 Städten. Investoren und Kommunen, die langfristige Partnerschaften mit dem Konzern eingehen, stehen vor einem dokumentierten Transparenzproblem: Sowohl die Finanzberichterstattung (Muddy Waters 2016, WiWo 2021) als auch die politische Einflussnahme (AfD-Spendenaffäre 2021) zeigen ein Unternehmen, das systematisch Kontrolle und Rechenschaftspflicht vermeidet."},{"id":"env-015","title":"Studie: 30% aller deutschen TV-Werbespots sind Klimakiller — verstößt gegen Medienstaatsvertrag (2024)","category":"environment","impact_score":9,"year":2024,"source_type":"ngo","file":"data/environment/env-015.md","institution":"Otto Brenner Stiftung / Universität Leipzig","source_url":"https://www.otto-brenner-stiftung.de/reklame-fuer-klimakiller/","tags":["klimakiller","werbung","medienstaatsvertrag","tv","otto-brenner-stiftung","fossile-produkte","autos","greenwashing","deutschland"],"zusammenfassung":"Die Otto Brenner Stiftung und die Universität Leipzig analysierten 9.779 Werbespots aus deutschen TV-Sendern und YouTube-Kanälen. Ergebnis: **30,3 % aller Werbespots** bewerben klimaschädliche Produkte und Dienstleistungen — und verstoßen damit nach Einschätzung der Forscher gegen den Medienstaatsvertrag, der Werbung für in hohem Maße umweltschädigende Verhaltensweisen untersagt.","kernbefund":"9.779 Spots wurden manuell kodiert (ca. 52 Stunden Videomaterial). **Jeder dritte Spot** wirbt für Klimakiller — primär Automobil, Luftfahrt und Lebensmittel. Besonders absurd laut Studie: Werbung für klimaschädliche Produkte transportiert häufig die Botschaft, man tue etwas Gutes für die Umwelt (Greenwashing). Die Studienautoren fordern strikte Regulierung oder vollständiges Werbeverbot für klimaschädigende Produktkategorien. Obwohl die Studie TV und YouTube untersucht, gelten die Produktkategorien (Autos, Flüge, fossile Energie) genauso für OOH/DOOH-Werbung.","relevanz":"DOOH-Netze in Deutschland generieren erhebliche Einnahmen aus den gleichen Produktkategorien: Automobil, Energie, Lebensmittel/Fast Food. Der Medienstaatsvertrag gilt für Rundfunk — für Außenwerbung fehlt eine entsprechende Regelung bisher. Die Studie liefert aber die wissenschaftliche Grundlage für eine Ausweitung des Verbots auf OOH/DOOH, wie sie u.a. von Badvertising (UK) und der Initiative Fossil Werbung Abschaffen (DE) gefordert wird."},{"id":"reg-021","title":"Den Haag: Erste Stadt weltweit verbietet Fossil-Fuel OOH-Werbung für Autos, Flüge & Kreuzfahrten ab 2025","category":"regulation","impact_score":10,"year":2024,"source_type":"government","file":"data/regulation/reg-021.md","institution":"invidis / Stadt Den Haag / t-online","source_url":"https://invidis.de/2024/09/den-haag-verbot-fuer-ooh-kampagnen-von-autos-fluegen-und-fossilen-brennstoffen/","tags":["den-haag","niederlande","fossil-fuel","werbeverbot","ooh","dooh","autos","flüge","kreuzfahrten","klimaschutz","2025","eu"],"zusammenfassung":"Den Haag (Niederlande, 500.000 Einwohner) ist ab 1. Januar 2025 die erste Stadt weltweit mit einem gesetzlichen Verbot für OOH-Werbung für fossile Brennstoffprodukte — konkret: Benzin/Diesel-Fahrzeuge, Flüge und Kreuzfahrten. Das Verbot gilt für alle Werbetafeln und Bushaltestellen im öffentlichen Raum. Andere EU-Städte folgen.","kernbefund":"Das Den-Haag-Verbot ist **ein direktes OOH/DOOH-Verbot** — es betrifft explizit Werbetafeln und Fahrgastunterstände im öffentlichen Raum. Die Stadt folgt damit dem Aufruf von UN-Generalsekretär António Guterres, der ein globales Werbeverbot für Fossile forderte. In Reaktion kündigte der niederländische Reiseverband ANVR rechtliche Schritte an. Weitere Städte, die ähnliche Verbote diskutieren oder erlassen haben: Amsterdam, Edinburgh, Sydney, Zwolle, Tilburg, Graz (Österreich). Belgien hat 2023 ein nationales Fossil-Fuel-Werbeverbot (alle Medien) erlassen.","relevanz":"Den Haag demonstriert, dass OOH/DOOH-Werbung für bestimmte Produktkategorien legal verboten werden kann — trotz bestehender Werberechtsverträge mit Konzernen. Das Modell wird sich durch die EU ausbreiten. Für DOOH-Investoren: Zwei der lukrativsten Werbekategorien (Automobile und Luftfahrt) sind in Den Haag bereits verboten — mit einer Signalwirkung für andere EU-Märkte, einschließlich Deutschland."},{"id":"reg-022","title":"Landgericht Hamburg: Shell-Werbung CO2-neutral für 1,1 Cent/Liter ist irreführend — OOH-Greenwashing verboten","category":"regulation","impact_score":9,"year":2024,"source_type":"government","file":"data/regulation/reg-022.md","institution":"Deutsche Umwelthilfe e.V. / Landgericht Hamburg","source_url":"https://www.duh.de/presse/pressemitteilungen/pressemitteilung/erfolgreiche-klimaklage-der-deutschen-umwelthilfe-gegen-shell-landgericht-hamburg-untersagt-irrefueh/","tags":["shell","greenwashing","duh","landgericht-hamburg","co2-neutral","irreführend","klage","urteil","ooh-werbung","2024","deutschland"],"zusammenfassung":"Das Landgericht Hamburg verbot Shell Deutschland am 9. August 2024 per Urteil, seine Außenwerbung mit dem Versprechen \"CO2-neutrales Fahren für 1,1 Cent pro Liter\" zu bewerben. Die Deutsche Umwelthilfe hatte 2022 geklagt, nachdem Shell trotz Abmahnung nicht aufgehört hatte. Das Gericht: Die Werbung sei \"in hohem Maße irreführend für Verbraucher.\"","kernbefund":"Shell versprach in seiner Tankstellen- und OOH-Werbung CO2-Neutralität durch Kompensationsprojekte (Waldschutz in Peru und Indonesien). Das Gericht (Az. 315 O 108/22) stellte fest: (1) Die Werbung war nicht transparent bezüglich der Kompensationsmethode; (2) Waldschutzprojekte können die CO2-Persistenz über Jahrhunderte nicht zuverlässig ausgleichen — Wälder können das gespeicherte CO2 binnen Jahren oder Jahrzehnten freisetzen. Die DUH hatte festgestellt: Bei 6 großen Energiekonzernen waren **81 % von Shells Werbeanzeigen Greenwashing**.","relevanz":"Das Urteil gilt direkt für OOH-Werbung: Shell-Tankstellenwerbung und Außenkampagnen waren Teil der beanstandeten Werbemaßnahmen. Das Urteil setzt einen Präzedenzfall für Deutschland: Vage \"Klimaneutralitäts\"-Versprechen in OOH-Kampagnen sind angreifbar. DOOH-Netzbetreiber, die Greenwashing-Kampagnen von Energiekonzernen schalten, exponieren sich — und ihre Kunden — gegenüber juristischen Risiken."},{"id":"reg-023","title":"EU-Kommission: JCDecaux Brüssel erhielt illegale Staatsbeihilfe durch Phantom-Werbetafeln ohne Miete oder Steuern","category":"regulation","impact_score":10,"year":2019,"source_type":"government","file":"data/regulation/reg-023.md","institution":"Europäische Kommission / EuG","source_url":"https://ec.europa.eu/commission/presscorner/detail/en/ip_15_4661","tags":["jcdecaux","brüssel","staatsbeihilfe","eu-kommission","phantom-billboards","korruption","eu-recht","wettbewerbsrecht","2019","eu"],"zusammenfassung":"Die Europäische Kommission eröffnete 2015 ein formelles Staatsbeihilfe-Prüfverfahren gegen zwei Verträge zwischen der Stadt Brüssel und JCDecaux. Ergebnis 2019: JCDecaux hatte nach Vertragsablauf weiterhin Werbetafeln (\"Phantom-Billboards\") betrieben — ohne Miete oder Steuern zu zahlen. Dies stellt eine illegale Staatsbeihilfe dar, unvereinbar mit dem EU-Binnenmarkt. Das EU-Gericht wies JCDecaux' Berufung ab.","kernbefund":"JCDecaux nutzte städtische Infrastruktur in Brüssel über den vertraglich vereinbarten Zeitraum hinaus, ohne dafür Entgelt zu entrichten. Konkurrenten mussten für vergleichbare Werberechte reguläre Marktpreise zahlen. Die EU-Kommission qualifizierte dies als unzulässigen Wettbewerbsvorteil. Das EuG (Az. T-642/19) bestätigte die Kommissionsentscheidung und wies die Klage von JCDecaux vollständig zurück. Wettbewerber Clear Channel Belgien hatte die ursprüngliche Beschwerde eingereicht.","relevanz":"Dieser Fall dokumentiert das strukturelle Muster im OOH-Markt: Werbekonzerne sichern sich durch undurchsichtige Vertragsgestaltung öffentliche Räume zu Vorzugsbedingungen und Kontrolle über Infrastruktur, die eigentlich der Allgemeinheit gehört. Das EU-Beihilfeverfahren liefert den höchsten denkbaren institutionellen Beleg für die These, dass JCDecaux systematisch städtische Institutionen zum eigenen Vorteil nutzt. Investoren und Kommunen in der EU sind diesem Risiko direkt ausgesetzt."},{"id":"pol-013","title":"JCDecaux-Gründer Jean-Claude Decaux wegen Korruption strafrechtlich verurteilt — Bordeaux Tribunal, Frankreich","category":"politics","impact_score":9,"year":2000,"source_type":"government","file":"data/politics/pol-013.md","institution":"Tribunal de Bordeaux / Marketing Week","source_url":"https://www.marketingweek.com/decaux-sentenced-in-corruption-scandal-2/","tags":["jcdecaux","korruption","strafurteil","bordeaux","frankreich","günstlingswirtschaft","beschaffung","öffentliche-aufträge"],"zusammenfassung":"Jean-Claude Decaux, Gründer und Vorsitzender von JCDecaux, wurde vom Strafgericht Bordeaux wegen \"Favoritismus\" (Günstlingswirtschaft) und Korruption bei der Vergabe öffentlicher Aufträge verurteilt. Auslöser: Ein Auftrag über 39,8 Millionen Franc (~6 Mio. €) für Schuluhren in 204 Schulen des Aquitaine-Regionalrats wurde ohne Ausschreibung an eine Decaux-Tochtergesellschaft vergeben. Senator Jacques Verlade wurde wegen Bestechung verurteilt. Decaux erhielt eine sechsmonatige Bewährungsstrafe und eine Geldstrafe von 100.000 Franc. Er legte Berufung ein.","kernbefund":"Der Fall dokumentiert die direkte persönliche Verstrickung des JCDecaux-Konzernchefs in die Manipulation öffentlicher Vergabeverfahren. Statt kompetitiver Ausschreibung erhielt eine Decaux-Gesellschaft den Auftrag durch persönliche Beziehungen zu einem gewählten Politiker. Das Strafgericht befand die Vergabe als gesetzwidrig und sprach Schuldsprüche aus.","relevanz":"JCDecaux ist der weltgrößte OOH-Konzern und europaweit an hunderten kommunalen Exklusivverträgen beteiligt. Die strafrechtliche Verurteilung des Gründers wegen der Manipulation öffentlicher Vergabeverfahren steht paradigmatisch für das Geschäftsmodell: Städte sind von der Vergabepraxis des Konzerns abhängig, und die Kontrolle durch öffentliche Institutionen hat sich als unzureichend erwiesen. Der Fall ist der früheste dokumentierte Straftatbestand in der Geschichte des Unternehmens."},{"id":"pol-014","title":"Berlin: Gericht erlaubt JCDecaux, Finanzkonditionen des BVG-Werbevertrags geheim zu halten","category":"politics","impact_score":8,"year":2019,"source_type":"government","file":"data/politics/pol-014.md","institution":"FragDenStaat / Verwaltungsgericht Berlin","source_url":"https://fragdenstaat.de/blog/2019/09/02/senuvk-werbevertrage/","tags":["berlin","jcdecaux","wall-gmbh","ströer","bvg","vertragsgeheimnis","informationsfreiheit","öffentlicher-nahverkehr","transparenz","2019","deutschland"],"zusammenfassung":"FragDenStaat stellte einen Informationsfreiheitsantrag auf Offenlegung der Werberechtsverträge zwischen der BVG (Berliner Verkehrsbetriebe) und Wall GmbH (JCDecaux-Tochter) sowie Ströer. Das Berliner Verwaltungsgericht urteilte 2019: Die Finanzkonditionen der Verträge müssen nicht offengelegt werden — obwohl die Verträge selbst die Klausel enthielten, sie enthielten \"keine Geschäftsgeheimnisse\". Das Gericht wertete JCDecaux' Interesse an Geheimhaltung dennoch höher als das öffentliche Transparenzinteresse.","kernbefund":"Die Öffentlichkeit finanziert durch Steuergelder die öffentliche Infrastruktur (BVG-Busse, Trams, U-Bahnhöfe), auf der JCDecaux exklusiv Werbung schaltet. Die genauen Finanzbedingungen — also wie viel die Stadt für diese Nutzung ihrer Infrastruktur erhält — bleiben geheim. Einzig öffentlich: BVG-Werbeeinnahmen betrugen nach eigenen Angaben ca. 10 Mio. € pro Jahr. Das ursprüngliche JCDecaux-Gebot von 2006 soll 103 Mio. € über die Vertragslaufzeit betragen haben. Der Vertrag wurde 2021 für weitere fünf Jahre ohne öffentliche Ausschreibung verlängert.","relevanz":"Der Fall Berlin zeigt: Selbst wenn Verträge ausdrücklich keine Geschäftsgeheimnisse beinhalten sollen, setzen OOH-Konzerne Geheimhaltung gerichtlich durch. Demokratische Kontrolle über die Monetarisierung öffentlicher Infrastruktur ist strukturell ausgehebelt. Das Muster — geheime Finanzkonditionen, Verlängerungen ohne Ausschreibung — findet sich in Berlin, Hamburg, Frankfurt und anderen deutschen Städten."},{"id":"reg-024","title":"Schweiz: Bundesgericht bestätigt vollständiges Werbeverbot in Vernier — 172 Werbetafeln entfernt, Zürich und Bern folgen","category":"regulation","impact_score":10,"year":2024,"source_type":"government","file":"data/regulation/reg-024.md","institution":"Bundesgericht der Schweiz / Adfree Cities / Bloomberg","source_url":"https://adfreecities.org.uk/2024/07/swiss-vernier-take-down-billboards/","tags":["schweiz","vernier","zürich","bern","bundesgericht","werbeverbot","visual-pollution","billboard-ban","ooh","dooh","2024"],"zusammenfassung":"Das Schweizer Bundesgericht bestätigte 2024, dass die Gemeinde Vernier (38.000 Einwohner, Genf) alle kommerziellen Werbetafeln im öffentlichen Raum verbieten darf — auch auf Privatgrundstücken. Das Verbot dient der Bekämpfung von \"visueller Verschmutzung\" und gibt Bürgerinnen das Recht, sich unerwünschter Werbung zu entziehen. Über drei Viertel der 172 Werbetafeln wurden entfernt. Zürich und Bern kündigen ähnliche Verbote an. OOH-Unternehmen in der Schweiz sehen sich nach Medienberichten einer \"existenziellen Bedrohung\" ausgesetzt.","kernbefund":"Das Bundesgericht stufte das vollständige Werbeverbot nicht als wettbewerbswidrigenEingriff ein, sondern als legitime kommunale Maßnahme gegen \"visuelle Umweltverschmutzung\". Damit ist in der Schweiz rechtlich anerkannt: Öffentliche Werbung im Außenraum ist eine Form von Umweltverschmutzung, gegen die Bürgerinnen einen Schutzanspruch haben. Das Präzedenzurteil gilt für alle Schweizer Gemeinden. Zürich zielt dabei besonders auf Digitalscreens wegen Energieverbrauch und Lichtverschmutzung ab.","relevanz":"Das Bundesgerichtsurteil ist die stärkste gerichtliche Bestätigung weltweit, dass vollständige OOH-Verbote rechtlich haltbar sind. Der \"Domino-Effekt\" in der Schweiz — Vernier → Zürich → Bern — zeigt, dass ein einziges Präzedenzurteil eine Lawine auslösen kann. Für DOOH-Investoren, die auf langfristige Einnahmen aus öffentlichen Standorten setzen, ist das Schweizer Modell ein direkter Vorläufer europäischer Rechtsentwicklung."},{"id":"reg-025","title":"Amsterdam: Erste Hauptstadt weltweit verbietet OOH-Werbung für fossile Brennstoffe UND Fleisch — in Kraft ab Mai 2026","category":"regulation","impact_score":10,"year":2026,"source_type":"government","file":"data/regulation/reg-025.md","institution":"DeSmog / Euronews / Invidis","source_url":"https://www.desmog.com/2026/01/23/amsterdam-defies-last-minute-lobbying-to-become-first-capital-city-to-ban-fossil-fuel-ads/","tags":["amsterdam","niederlande","fossil-fuel","werbeverbot","fleisch","ooh","dooh","hauptstadt","klimaschutz","2026","eu"],"zusammenfassung":"Amsterdam verabschiedete im Januar 2026 (27:17 Ratsstimmen) das erste gesetzliche Verbot einer Hauptstadt für OOH-Werbung für fossile Brennstoffe, Fleisch, Flüge, Benzin/Diesel-Fahrzeuge und Gasheizungen — auf allen öffentlichen Flächen inkl. Trams, Zügen, Bussen und Digitalscreens. In Kraft ab 1. Mai 2026. Eine zweite Phase verbietet ab April 2028 zudem die Unternehmens-Image-Werbung von Hochemissions-Konzernen. Der Stadtrat widerstand intensivem Lobbydruck von Industrie und Bundesregierung.","kernbefund":"Amsterdam geht über Den Haag (nur fossile Kraftstoffe) hinaus und schließt erstmals Fleisch und Flüge ein. Die Abstimmung erfolgte trotz einer letzten Lobbyoffensive. Das Verbot gilt für alle DOOH-Netzwerke im öffentlichen Raum. Die zweite Phase 2028 betrifft explizit \"Corporate Image Advertising\" von Unternehmen mit hohem CO₂-Ausstoß — ein Präzedenzfall für Unternehmens-Markenkommunikation. Der Stadtrat bezeichnete Lobbying durch Industrie und Regierung als unangemessene Einflussnahme auf demokratische Entscheidungsprozesse.","relevanz":"Amsterdam ist die erste EU-Hauptstadt mit einem solchen Verbot. Zusammen mit Den Haag (2025), Belgien (2023), Frankreich (2022) und nun Amsterdam (2026) entsteht ein sich verdichtendes regulatorisches Netz in der EU. Zwei der wertvollsten DOOH-Kategorien — Automobil und Ernährung — sind in Amsterdam verboten. DOOH-Investitionen in EU-Hauptstädten sind mit einem strukturellen und beschleunigenden Regulierungsrisiko behaftet, das die Rentabilität bestehender Verträge gefährdet."},{"id":"env-016","title":"Deutsche Bundesregierung bestätigt: DOOH-Infrastruktur verbraucht 113.000 MWh/Jahr — Energiesparverordnung erzwingt Nachtabschaltung","category":"environment","impact_score":9,"year":2022,"source_type":"government","file":"data/environment/env-016.md","institution":"Bundesregierung Deutschland / Adzine / OneToOne","source_url":"https://www.adzine.de/2022/09/energiesparverordnung-trifft-auf-unverstaendnis-bei-den-aussenwerbern/","tags":["energieverbrauch","dooh","deutschland","energiesparverordnung","nachtabschaltung","bundesregierung","klimaschutz","2022"],"zusammenfassung":"Im September 2022 trat in Deutschland die Energiesparverordnung in Kraft, die beleuchtete Außenwerbung von 22:00 bis 16:00 Uhr abzuschalten verpflichtete. Die OOH-Branche selbst bezifferte den Jahresenergieverbrauch digitaler Werbeanlagen in Deutschland auf **113.000 MWh** — das entspricht dem Jahresstromverbrauch von ca. 40.000 Zwei-Personen-Haushalten. Die Bundesregierung reagierte auf die Energiekrise mit einer bundesweiten Abschaltpflicht; die Außenwerbewirtschaft bezeichnete die Maßnahme als \"unverständlich\" und kritisierte \"Lücken\".","kernbefund":"Die vom OOH-Verband selbst genannte Zahl — 113.000 MWh/Jahr für digitale Außenwerbung allein in Deutschland — ist ein von der Industrie anerkanntes Maß für den Ressourcenverbrauch. Dieser Energiebedarf dient ausschließlich der Monetarisierung öffentlicher Aufmerksamkeit; keine Grundversorgung, kein öffentlicher Nutzen. Die Bundesregierung stufte ihn im Rahmen der Energiesicherung als verzichtbar ein — die erste bundesweite staatliche Qualifizierung von DOOH-Betrieb als nicht-essentiellem Energieverbrauch.","relevanz":"Die Energiesparverordnung ist das direkteste regulatorische Signal der deutschen Bundesregierung gegen DOOH-Betrieb. Gleichzeitig belegt die Industrie-eigene Zahl (113.000 MWh/Jahr) die Dimension des Energieverbrauchs: DOOH-Netzwerke in Deutschland verbrauchen mehr Strom als 40.000 Haushalte — für reine Werbezwecke. Mit steigenden Energiepreisen und Klimaschutzzielen ist weiterer regulatorischer Druck auf den Betrieb von Digitalscreens im öffentlichen Raum absehbar."},{"id":"safety-006","title":"Schwedische Trafikverket-Studie: Digitale Werbetafeln auf Autobahn verursachen gefährliche Blickabwendung — Tafeln daraufhin entfernt","category":"safety","impact_score":9,"year":2013,"source_type":"peer-reviewed","file":"data/safety/safety-006.md","institution":"Schwedische Transportverwaltung (Trafikverket) / Accident Analysis & Prevention","source_url":"https://pubmed.ncbi.nlm.nih.gov/23682577/","tags":["fahrablenkung","dooh","autobahn","schweden","eye-tracking","verkehrssicherheit","2013","peer-reviewed"],"zusammenfassung":"Die schwedische Transportverwaltung (Trafikverket) ließ zwölf digitale Werbetafeln testweise auf einem dreispurigen Stadtautobahnabschnitt in Stockholm installieren. Eine instrumentierte Fahrzeugstudie mit 41 Fahrerinnen und Fahrern per Eye-Tracking dokumentierte: Digitale Werbetafeln wurden deutlich länger fixiert als andere Straßenschilder auf demselben Abschnitt. Blickabwendungszeiten überschritten häufig die kritische 2-Sekunden-Schwelle (ab der Ablenkung als gefährlich gilt). Ergebnis: Trafikverket entschied, die digitalen Werbetafeln vom Autobahnabschnitt zu entfernen. Die Studie wurde in Accident Analysis & Prevention veröffentlicht.","kernbefund":"Das Studiendesign — real road, instrumented vehicle, eye-tracking — ist methodisch stärker als Simulatorstudien. Die Messung ergab \"considerably longer dwell time, greater fixation count, and longer maximum fixation duration\" für DOOH-Tafeln gegenüber statischen Schildern. Dies ist der seltene Fall, in dem eine Behörde nach eigener Studie direkt handelte: Die digitalen Werbetafeln wurden auf Grundlage der Forschungsergebnisse entfernt. Das Ergebnis widerlegt die Branchenbehauptung, DOOH sei für den Verkehr sicher.","relevanz":"Die schwedische Studie ist eine der methodisch stärksten Belege für die Verkehrsgefahr durch DOOH an Schnellstraßen — und der direkteste Beleg für eine behördliche Konsequenz: nicht nur eine Empfehlung, sondern eine Entscheidung zur Entfernung. Städte und Straßenbaubehörden, die DOOH-Konzessionen für Standorte an Schnellstraßen genehmigen, tun dies entgegen der vorliegenden Forschungslage."},{"id":"priv-004","title":"Clear Channel RADAR: Werbetafeln tracken Mobiltelefon-Bewegungsprofile von Passanten — US-Senatoren fordern Untersuchung","category":"privacy","impact_score":8,"year":2016,"source_type":"ngo","file":"data/privacy/priv-004.md","institution":"NPR / US-Senat (Schumer, Franken) / Private Internet Access","source_url":"https://www.npr.org/sections/thetwo-way/2016/02/29/468598100/using-billboards-company-will-collect-personal-information-to-help-advertisers","tags":["clear-channel","radar","überwachung","tracking","mobiltelefon","datenschutz","usa","eu","senat","2016"],"zusammenfassung":"Clear Channel Outdoor Americas startete 2016 das Programm \"RADAR\": Anonymisierte Standortdaten von Mobiltelefonen (über Partner wie AT&T, Placed, PlaceIQ) werden mit der Reichweite von Clear-Channel-Werbetafeln verknüpft, um Bewegungsmuster von Passanten zu analysieren. Der US-Senator Charles Schumer bezeichnete das System öffentlich als \"Spionage-Werbetafeln\". Senator Al Franken forderte schriftlich Auskunft über Einwilligungsmechanismen, Datenweitergabe und Sicherheitsmaßnahmen. RADAR wurde anschließend auch in Europa (UK, Spanien, Schweden) ausgerollt.","kernbefund":"RADAR nutzt Mobiltelefon-Standortdaten, um Verhaltensmuster und Bewegungsprofile von Menschen im öffentlichen Raum zu erstellen — ohne deren Wissen und ohne direkte Einwilligung. Datenschützer kritisierten: Die Behauptung der \"Anonymisierung\" ist nicht verifizierbar. In Europa wurde RADAR für DSGVO-Konformität angepasst; das Grundproblem — kommerzielle Überwachung öffentlicher Räume ohne aktive Zustimmung — bleibt strukturell bestehen. DOOH-Displays fungieren faktisch als Datenpunkte in einem privaten Überwachungsnetzwerk.","relevanz":"Clear Channel ist einer der drei größten OOH-Konzerne weltweit mit umfangreicher europäischer Präsenz. RADAR belegt: DOOH ist nicht nur ein Werbemedium, sondern ein Instrument zur Massenüberwachung des öffentlichen Raums. Die Nutzung als Überwachungsinfrastruktur erfolgt ohne demokratische Entscheidung — durch langfristige kommunale Exklusivverträge ist diese Infrastruktur dem demokratischen Zugriff entzogen."},{"id":"safety-007","title":"US-Studie: 25–29% höhere Unfallraten in der Nähe digitaler Werbetafeln auf Highways (Florida und Alabama)","category":"safety","impact_score":9,"year":2015,"source_type":"government","file":"data/safety/safety-007.md","institution":"Georgia Institute of Technology / US Department of Transportation","source_url":"https://rosap.ntl.bts.gov/view/dot/36939","tags":["verkehrsunfall","digital-billboard","highway","fahrablenkung","usa","florida","alabama","crashrate","2015","peer-reviewed"],"zusammenfassung":"Eine staatlich geförderte US-Studie analysierte 18 digitale Werbetafel-Standorte auf US-Highways. An Standorten in Florida wurden **25 % höhere Unfallraten** gemessen, in Alabama **29 % höhere Unfallraten** — verglichen mit Kontrollstandorten auf demselben Streckenabschnitt ohne digitale Werbetafeln. Die Studie wurde vom US-Verkehrsministerium (DOT) gefördert und am Georgia Institute of Technology durchgeführt.","kernbefund":"Die Studie verglich Unfalldaten an 18 DOOH-Standorten mit Kontrollpunkten stromabwärts derselben Strecken. Ergebnis: Signifikant erhöhte Crashraten direkt bei und unmittelbar nach digitalen Werbetafeln. Die Analyse kontrollierte für Fahrbahngeometrie und Verkehrsvolumen. Das ist eine der meistzitierten Real-World-Unfallstudien im Kompendium von Scenic America (dem US-amerikanischen Gegner von Highway-Werbung).","relevanz":"Digitale Werbetafeln an Schnellstraßen erhöhen das Unfallrisiko für alle Verkehrsteilnehmer nachweislich. Die gesellschaftlichen Kosten — medizinische Behandlung, Sachschäden, Produktivitätsverluste — werden auf die Allgemeinheit externalisiert, während der Gewinn beim OOH-Betreiber verbleibt. Straßenbehörden, die DOOH-Konzessionen an Schnellstraßen vergeben, übertragen damit ein dokumentiertes Sicherheitsrisiko auf die Öffentlichkeit."},{"id":"pol-015","title":"Frankfurt: Ströer-Vertrag zu 1/13 des Hamburger Marktpreises — Öffentlicher Raum für €2,6 Mio./Jahr statt €34 Mio./Jahr","category":"politics","impact_score":8,"year":2017,"source_type":"ngo","file":"data/politics/pol-015.md","institution":"W&V (Werben & Verkaufen)","source_url":"https://www.wuv.de/Archiv/Str%C3%B6er-wirbt-in-Frankfurt-zum-Schn%C3%A4ppchenpreis","tags":["frankfurt","ströer","unterbewertung","öffentlicher-raum","vertragskonditionen","hamburg","marktpreis","2017","deutschland"],"zusammenfassung":"Eine W&V-Untersuchung (2017) ergab: Ströer DSM hatte die Außenwerberechte in Frankfurt zu einem Fixpachtzins von nur €409.000 jährlich plus Revenue-Sharing — insgesamt ca. €2,6 Mio./Jahr für die Stadt. Zum Vergleich: Hamburg hatte seine OOH-Rechte 2007 neu ausgeschrieben und erhielt seitdem ca. €34 Mio./Jahr. Frankfurt erhielt damit rechnerisch **1/13 des Hamburger Marktpreises** für öffentlichen Raum vergleichbarer Größe.","kernbefund":"Das Missverhältnis — €2,6 Mio. vs. €34 Mio. für vergleichbare kommunale Werberechte — belegt, wie stark städtische Einnahmen von der Verhandlungsmacht und Transparenz bei der Vergabe abhängen. Frankfurt war vertraglich verpflichtet, bis zum 1. Januar 2018 neu auszuschreiben. Die Studie impliziert, dass ohne diesen Vergleichsdruck viele deutsche Städte öffentlichen Raum zu weit unter Marktpreis an OOH-Konzerne abgeben — dauerhaft und ohne demokratischen Überblick über den entgangenen Wert.","relevanz":"Dieses Beispiel zeigt das systemische Muster: OOH-Konzerne erschleichen sich durch langfristige Erstverträge Festpreise, die weit unter dem Marktwert liegen. Wenn Verträge nach 10–20 Jahren auslaufen, haben sich politische und institutionelle Abhängigkeiten aufgebaut, die eine marktgerechte Neuvergabe erschweren. Der entgangene öffentliche Wert — im Fall Frankfurt über eine Vertragslaufzeit von 15 Jahren potenziell mehrere hundert Millionen Euro — wird nicht transparent ausgewiesen."},{"id":"health-013","title":"Umbrella-Review: Glücksspielwerbung verursacht nachweislich dosisabhängige Suchtgefährdung — 74 Studien, kausaler Zusammenhang belegt","category":"health","impact_score":9,"year":2023,"source_type":"peer-reviewed","file":"data/health/health-013.md","institution":"ScienceDirect / Public Health journal / PubMed","source_url":"https://www.sciencedirect.com/science/article/pii/S0033350622003420","tags":["glücksspiel","werbung","sucht","kinder","jugendliche","dosisabhängigkeit","kausalität","umbrella-review","2023","ooh"],"zusammenfassung":"Ein systematischer Umbrella-Review (2023, Public Health) fasste 8 systematische Reviews zusammen, die zusammen 74 Einzelstudien abdeckten. Ergebnis: Es gibt konsistente Belege für einen **kausalen Zusammenhang** zwischen Glücksspielwerbung und positiveren Einstellungen zum Glücksspiel sowie erhöhter Spielbereitschaft — mit einem klaren **Dosis-Wirkungs-Effekt**. Kinder, Jugendliche und bereits gefährdete Personen sind am stärksten betroffen. 1 von 7 UK-Glücksspielanzeigen enthielt keinerlei Altershinweis; 84% der Warnhinweise und 54% der Schadenminimierungsbotschaften hatten sehr geringe Sichtbarkeit.","kernbefund":"Der kausale Zusammenhang ist auf dem Stand von 74 Studien belegt — deutlich mehr als die Evidenzlage zu den meisten regulierten Produktkategorien. Die Dosis-Wirkungs-Relation bedeutet: je mehr Werbung, desto stärker die Wirkung. OOH ist besonders kritisch, weil Kinder ihr nicht ausweichen können. Bestehende Selbstregulierungsmaßnahmen (Warnhinweise) sind nachweislich ineffektiv.","relevanz":"Glücksspielwerbung ist eine der wichtigsten Einnahmekategorien für DOOH-Netzwerke in Europa. Die Evidenzlage belegt eindeutig: OOH-Glücksspielwerbung verursacht messbare, dosisabhängige Schäden — insbesondere bei Kindern auf Schulwegen und einkommensschwachen Bevölkerungsgruppen, die überproportional exponiert sind. Regulierungsbehörden in UK, Belgien und Spanien haben bereits Einschränkungen erlassen; Deutschland steht unter zunehmendem politischen Druck."},{"id":"reg-026","title":"EU-Richtlinie 2024/825: Generische Greenwashing-Claims in Werbung verboten — CO2-neutral ohne Nachweis illegal ab 2026","category":"regulation","impact_score":9,"year":2024,"source_type":"government","file":"data/regulation/reg-026.md","institution":"Europäische Kommission / EUR-Lex","source_url":"https://eur-lex.europa.eu/legal-content/EN/TXT/PDF/?uri=OJ:L_202400825","tags":["eu-richtlinie","greenwashing","co2-neutral","klimafreundlich","werbung","ooh","dooh","verbraucher","2024","2026","eu"],"zusammenfassung":"Die EU-Richtlinie 2024/825 (\"Empowering Consumers for the Green Transition\"), verabschiedet am 27. März 2024, verbietet generische Umweltversprechen in Werbung ohne spezifischen Nachweis auf demselben Medium. Verboten ab September 2026 (nationale Umsetzung bis März 2026): Aussagen wie \"CO2-neutral\", \"klimafreundlich\", \"energieeffizient\", \"grün\", \"biologisch abbaubar\" ohne quantifizierte Belege. Ebenfalls verboten: Klimaneutralitätsversprechen, die ausschließlich auf CO₂-Kompensationsprojekten beruhen.","kernbefund":"Die Richtlinie gilt für alle Werbeformate — einschließlich OOH und DOOH. Da Werbetafeln physisch begrenzte Fläche bieten, werden generische Greenwashing-Aussagen auf DOOH-Screens de facto unmöglich: Ein \"CO2-neutral\"-Claim auf einem digitalen Display wäre ohne detaillierten Nachweis auf demselben Medium ab 2026 EU-rechtswidrig. Die zugehörige Green Claims Directive (detailliertere Regulierung) wurde 2025 von der Kommission zurückgezogen — aber Richtlinie 2024/825 bleibt in Kraft.","relevanz":"DOOH-Netze in Deutschland und der EU generieren erhebliche Einnahmen aus Kampagnen von Energieunternehmen, Automobilherstellern und Fluggesellschaften mit Greenwashing-Botschaften. Ab September 2026 sind diese Kampagnen in der bisherigen Form EU-rechtswidrig. DOOH-Betreiber sind mitverantwortlich für die Verbreitung irreführender Werbung auf ihrer Infrastruktur — das Landgericht Hamburg hat dies 2024 für Shell bereits bestätigt (reg-022)."}]};